    /// <summary>The clip whose gMarioAnimeData row decides the pump: the body clip, except where the port shows a stand-in whose row is not
    /// the game's -- the triple jump plays ma_demo_gate_out_rolling_get (a demo row, no pump) where the game's ultraJumping plays ANIM_ROLL
    /// (MarioJump.cpp: jumpingBasic(ULTRA_JUMP, ANIM_ROLL)), whose row pumps; so FLUDD works through a triple jump as it does in the game.</summary>
    private string SmsPumpClip() => stateOfMario == MarioState.tripleJump ? "ma_roll" : SmsCurrentClip();

    private static int SmsUpperPumpFor(string clip) =>
        !string.IsNullOrEmpty(clip) && SmsUpperPumpTable.TryGetValue(clip, out int id) ? id : SmsParams.Fludd.UpperPump;

    /// <summary>The upper clip to bind now: the body clip's column when that clip is in the library (else the tree's ma_pump stands,
    /// as the game stands on its default when a clip is missing). With the tree on it goes in at CarryBlend's "Animation 2"; with the
    /// tree off (the swim clips, the struggling hang) its graft is weighted in.</summary>
    private int SmsFluddBindId()
    {
        int id = SmsUpperPumpFor(SmsPumpClip());
        if (id == SmsParams.Fludd.UpperNone || id == SmsParams.Fludd.UpperPump)
            return SmsParams.Fludd.UpperPump;
        return _fluddUpperClipLen.ContainsKey(id) ? id : SmsParams.Fludd.UpperPump;
    }

    private static string SmsFluddUpperClipName(int id) => id switch
    {
        SmsParams.Fludd.UpperHgPmp => "ma_hgpmp",
        SmsParams.Fludd.UpperFePmp => "ma_fepmp",
        SmsParams.Fludd.UpperSwPmp => "ma_swpmp",
        _ => "ma_pump"
    };

    private static void SmsPlaySlot(AudioStreamPlayer3D p)
    {
        if (p != null && p.Stream != null)
            p.Play();
    }

    // ---- the upper-body damage run (pass 110): setUpperDamageRun (MarioDraw.cpp 1854) / UPPER_STATE_FIXED_ANIMATION (MarioUpper.cpp 131) ----
    private SmsUpperPose _smsDgrunGraft; private double _smsDgrunLen, _smsDgrunT; private bool _smsDgrunOn;
    private const double SmsUpperDamageRunRate = 0.5;   // setUpperDamageRun: frameCtrl.setRate(0.5f) -- the clip at half speed
    /// <summary>The upper body is in the fixed damage-run animation (the drives read it).</summary>
    public bool SmsUpperDamageRunOn => _smsDgrunOn;
    public double SmsUpperDamageRunTime => _smsDgrunT;
    private void SmsSetupUpperDamageRun()
    {
        if (skeleton == null || animPlayer == null || !animPlayer.HasAnimation("ma_dgrun")) return;
        var clip = animPlayer.GetAnimation("ma_dgrun");
        _smsDgrunGraft = new SmsUpperPose { Name = "SmsUpper_ma_dgrun" };
        skeleton.AddChild(_smsDgrunGraft);
        skeleton.MoveChild(_smsDgrunGraft, 0);
        _smsDgrunGraft.Bind(skeleton, clip, "chn_chest");
        _smsDgrunLen = clip.Length; _smsDgrunGraft.Weight = 0f;
        if (SmsDebugPrint) GD.Print($"[SMS damage] upper damage run graft: ma_dgrun ({clip.Length:F3} s) on {_smsDgrunGraft.BoneCount} bones under chn_chest");
    }
    /// <summary>setUpperDamageRun: the clip from its start (setFrame(getStart())) at rate 0.5; FIXED until it completes. False without the clip.</summary>
    private bool SmsUpperDamageRunStart()
    {
        if (_smsDgrunGraft == null) return false;
        _smsDgrunOn = true; _smsDgrunT = 0.0;
        _smsDgrunGraft.Time = 0.0; _smsDgrunGraft.Weight = 1f;
        return true;
    }
    /// <summary>Once a physics frame: the fixed animation advances at 0.5 and ends when the clip completes (someAnimationCompleted) -- or at once
    /// when a knockdown, the water or a talk takes the body (the game's status change re-targets the upper track).</summary>
    private void SmsUpperDamageRunTick(double delta)
    {
        if (!_smsDgrunOn || _smsDgrunGraft == null) return;
        bool body = stateOfMario == MarioState.hurt || stateOfMario == MarioState.swimming || stateOfMario == MarioState.dead || _smsTalking || heldBody != null;
        _smsDgrunT += delta * SmsUpperDamageRunRate;
        if (body || _smsDgrunT >= _smsDgrunLen) { _smsDgrunOn = false; _smsDgrunGraft.Weight = 0f; return; }
        _smsDgrunGraft.Time = _smsDgrunT; _smsDgrunGraft.Weight = 1f;
    }

    /// <summary>The upper clips the tree does not carry -- ma_swpmp (0x95), ma_hgpmp (0x45), ma_fepmp (0x94) -- each on the chn_chest subtree
    /// (SmsUpperPose), for the frames the tree does not drive; the one the body clip's column names is weighted in.</summary>
    private void SmsFluddSetupUpperGrafts()
    {
        if (skeleton == null || animPlayer == null)
            return;
        SmsSetupUpperDamageRun();
        foreach (var (id, name) in new[] { (SmsParams.Fludd.UpperPump, "ma_pump"), (SmsParams.Fludd.UpperSwPmp, "ma_swpmp"), (SmsParams.Fludd.UpperHgPmp, "ma_hgpmp"), (SmsParams.Fludd.UpperFePmp, "ma_fepmp") })
        {
            if (!animPlayer.HasAnimation(name))
            {
                if (SmsDebugPrint) GD.Print($"[SMS fludd] no {name} clip in the library: the tree's ma_pump stands where the game grafts it");
                continue;
            }
            var clip = animPlayer.GetAnimation(name);
            var graft = new SmsUpperPose { Name = "SmsUpper_" + name };
            skeleton.AddChild(graft);
            skeleton.MoveChild(graft, 0); // before the head jiggle / head lock modifiers, which add their bit on top
            graft.Bind(skeleton, clip, "chn_chest");
            _fluddUpperGraft[id] = graft;
            _fluddUpperClipLen[id] = clip.Length;
            if (SmsDebugPrint)
                GD.Print($"[SMS fludd] upper graft: {name} ({clip.Length:F3} s) on {graft.BoneCount} bones under chn_chest");
        }
    }

    // ---------------------------------------------------------------------------------------------------------------
    // FLUDD S2: the tank and the spray (TWaterGun::gunExec / suck / emit / damage, TNozzleDeform, TNozzleTrigger,
    // TModelWaterManager -> SmsWaterDrops). One SMS tick = one call of SmsFluddGunExecTick.
    // ---------------------------------------------------------------------------------------------------------------

    private SmsParams.Fludd.Nozzle SmsFluddCurrent => SmsParams.Fludd.ForNozzle((int)_fluddNozzle);

    /// <summary>The drops, the water level in the tank, the muzzle joints.</summary>
    private void SmsFluddSetupWater()
    {
        // pass 123b: the drops' ray also sees the hidden-coin spots (layer 8 -- off Mario's own mask so he never bumps into one); the game's
        // water hit actors test every actor's cylinder, hide objects included (TWaterHitHideObj::touchWater)
        _fluddDrops = new SmsWaterDrops { Name = "SmsWaterDrops", CollisionMask = CollisionMask | SmsHiddenCoin.HideLayer, Exclude = GetRid(), DebugPrint = SmsDebugPrint };
        AddChild(_fluddDrops);
        for (int i = 0; i < 4; i++)
        {
            var sk = _fluddNozzleSkel[i];
            if (sk == null)
                continue;
            int a = sk.FindBone("null_G_muzzle"), b = sk.FindBone("null_G_muzzle2");
            _fluddMuzzleBone[i] = b >= 0 ? new[] { a, b } : new[] { a };
        }
        if (_fluddTankSkel != null)
        {
            // the water in the tank: the shell (_mat_G_main_tank) is a cylinder along the tank's X (its height), x -3.0..33.3,
            // radius 18.9 about (y -40, z 0); the game shows the level on its waterline quad with a scrolled water texture
            // (a BTK the rip lacks), so the port fills the shell with a blue cylinder cut at the fill instead
            _fluddWaterLevel = new MeshInstance3D
            {
                Name = "SmsTankWater",
                Mesh = new CylinderMesh { TopRadius = 17.6f, BottomRadius = 17.6f, Height = 1f, RadialSegments = 24, Rings = 1 },
                CastShadow = GeometryInstance3D.ShadowCastingSetting.Off,
                MaterialOverride = new StandardMaterial3D
                {
                    ResourceName = "sms tank water",
                    AlbedoColor = new Color(0.12f, 0.55f, 1.0f, 0.78f),
                    Transparency = BaseMaterial3D.TransparencyEnum.Alpha,
                    Roughness = 0.15f,
                    Metallic = 0f,
                    EmissionEnabled = true,
                    Emission = new Color(0.02f, 0.12f, 0.35f),
                    EmissionEnergyMultiplier = 0.5f,
                },
            };
            _fluddTankSkel.AddChild(_fluddWaterLevel);
            // the rip's waterline quad (additive, its level texture unscrolled) would double the level: hidden
            var meshes = new System.Collections.Generic.List<MeshInstance3D>();
            SmsCollect(_fluddTank, meshes);
            foreach (var mi in meshes)
            {
                if (mi.Mesh == null) continue;
                for (int i = 0; i < mi.Mesh.GetSurfaceCount(); i++)
                {
                    string name = mi.GetActiveMaterial(i)?.ResourceName ?? "";
                    if (name.Length == 0 && mi.Mesh is ArrayMesh am) name = am.SurfaceGetName(i);
                    if (name.StartsWith("_mat_waterline"))
                        mi.SetSurfaceOverrideMaterial(i, new StandardMaterial3D { Transparency = BaseMaterial3D.TransparencyEnum.Alpha, AlbedoColor = new Color(0f, 0f, 0f, 0f), ResourceName = "_mat_waterline (hidden)" });
                }
            }
            SmsFluddPoseWater();
        }
    }

    /// <summary>The water cylinder in the shell: from the shell's bottom (x -3.0) up to the fill.</summary>
    private void SmsFluddPoseWater()
    {
        if (_fluddWaterLevel == null)
            return;
        float frac = Mathf.Clamp((float)_fluddWater / SmsFluddCurrent.AmountMax, 0f, 1f);
        const float bottom = -2.96f, top = 33.33f;
        float h = MathF.Max(0.05f, (top - bottom) * frac);
        _fluddWaterLevel.Visible = frac > 0.002f;
        // CylinderMesh stands along Y; the shell lies along the tank's X: rotate Y onto X
        _fluddWaterLevel.Transform = new Transform3D(
            Basis.FromEuler(new Vector3(0f, 0f, -Mathf.Pi * 0.5f)) * Basis.FromScale(new Vector3(1f, h, 1f)),
            new Vector3(bottom + h * 0.5f, -40f, 0f));
    }

    /// <summary>getEmitPosDirSpeed(): emitter <paramref name="e"/>'s world position and its matrix's +X (the way the water
    /// leaves), read from the nozzle's animated skeleton (the shooting clip poses the barrel; the aim callbacks are S2b).</summary>
    private bool SmsFluddMuzzle(int e, out Vector3 pos, out Vector3 dir)
    {
        pos = Vector3.Zero;
        dir = Vector3.Zero;
        int ni = (int)_fluddNozzle;
        var sk = _fluddNozzleSkel[ni];
        var bones = _fluddMuzzleBone[ni];
        if (sk == null || bones == null || e >= bones.Length || bones[e] < 0)
        {
            // no muzzle joint in the rip: from the nozzle node, along Mario's face
            var node = _fluddNozzleNode[ni];
            if (node == null)
                return false;
            pos = node.GlobalPosition;
            dir = _smsFaceValid ? SmsMath.DirFromYaw(_smsFaceYaw) : SmsFacingOrVelocityDir();
            return true;
        }
        Transform3D g = sk.GlobalTransform;
        // getEmitMtx() is the joint's ANM matrix, callbacks included: the turbo's neck aim (NozzleCtrl) and the hover's bank
        // (WaterGunDivingCtrlL/R) are SmsBoneRotZ modifiers, and Godot puts the clip's poses back after each skin update, so a
        // plain GetBoneGlobalPose() here is the barrel BEFORE the callback -- level on land, 22.5 deg too high in the surf
        SmsBoneRotZ cb = _fluddNozzle == SmsNozzle.Turbo ? _fluddNeckRot : _fluddNozzle == SmsNozzle.Hover ? _fluddTilt : _fluddNozzle == SmsNozzle.Spray ? _fluddSprayAim : null;
        Transform3D b = cb != null ? cb.DrawnGlobalPose(sk, bones[e]) : sk.GetBoneGlobalPose(bones[e]);
        pos = g * b.Origin;
        dir = (g.Basis * b.Basis.X).Normalized();
        return dir.LengthSquared() > 0.5f;
    }

    /// <summary>The emitter's own motion rides on the drops: mV = Mario's velocity x 0.125 (units a tick).</summary>
    private Vector3 SmsFluddInheritVel() => new Vector3(SmsUnits.MpsToSpeed(velocity.X) * 0.125f, 0f, SmsUnits.MpsToSpeed(velocity.Z) * 0.125f);

    /// <summary>MEANING_R, the GC trigger's click at the end of its travel: the button_rclick action when the map has one, else the
    /// pad's full pull (the analog is still the pressure; easing off the click keeps it -- the turbo's charge-then-go).</summary>
    private bool SmsRClick() => InputMap.HasAction("button_rclick") ? Input.IsActionPressed("button_rclick") : _fluddR >= SmsParams.Squat.RClickPull;

    /// <summary>gunExec() for one tick: the pressure, the nozzle's movement, the refill in water, the emit.</summary>
    private void SmsFluddGunExecTick()
    {
        var np = SmsFluddCurrent;
        _fluddPressure = (int)(_fluddR * 150f); // triggerPressureMovement(): mCurrentPressure
        if (_fluddNozzle == SmsNozzle.Spray)
            SmsFluddSprayMovementTick(np);
        else
        {
            SmsFluddTriggerMovementTick(np, ref _fluddTrigState, ref _fluddTrigLeft, ref _fluddTrigFill);
            if (_fluddWater > 0)
            {
                // TNozzleTrigger::movement() ends in calcGunAngle() (not without water): angle = -LAngleBase -- the turbo's 4096 = 22.5 deg,
                // the hover's 0 -- clamped [LAngleMin, LAngleMax], chased at LAngleChase (0.1: from 0 after a change in ~30 ticks); the
                // squat aims it with the stick
                SmsFluddCalcGunAngle(np);
            }
        }
        _fluddAFrame = false; // a frame press counts once
        _fluddEmittedTick = 0;
        if (_smsInWater)
        {
            // suck(): +pressure x SuckRate a tick to the cap; with the tank full and pumping he sprays for free
            int rate = (int)(_fluddPressure * np.SuckRate);
            if (rate > 0 && _fluddWater < np.AmountMax)
                _fluddWater = Math.Min(_fluddWater + rate, np.AmountMax);
            if (_fluddWater == np.AmountMax && _fluddUpper == SmsUpper.Pumping)
            {
                SmsFluddEmitTick(np);
                _fluddWater = np.AmountMax; // resetWaterToFull()
            }
        }
        else
            SmsFluddEmitTick(np);
        _fluddEmitting = _fluddNozzle == SmsNozzle.Spray ? (_fluddWater > 0 && _fluddSprayStrength > 0f) : _fluddTrigState == 1;
    }

    /// <summary>TNozzleDeform::movement(): TNozzleBase's pressure ramp, x EmitPowScale clamped to 1, the aim chase, the burst's machine.</summary>
    private void SmsFluddSprayMovementTick(SmsParams.Fludd.Nozzle np)
    {
        if (_fluddWater <= 0)
            return;
        // TNozzleBase::movement(): the strength is the ramp's distance below the pressure; the ramp climbs TriggerRate a tick
        int var1 = (int)(256f * _fluddR * 150f);
        if (var1 > _fluddSprayRamp)
        {
            _fluddSprayStrength = (var1 - _fluddSprayRamp) / 65536f;
            _fluddSprayRamp += np.TriggerRate;
            if (var1 < _fluddSprayRamp)
                _fluddSprayRamp = var1;
        }
        else
        {
            _fluddSprayStrength = 0f;
            _fluddSprayRamp = var1;
        }
        // calcGunAngle(): angle = -LAngleBase (0 shipped) -> the stream leaves along the barrel; the squat aims it with the stick; the L
        // camera is the Y cam pass
        SmsFluddCalcGunAngle(np);
        _fluddSprayStrength = MathF.Min(_fluddSprayStrength * np.EmitPowScale, 1f);
        // mBomb.movement(): the burst's trigger machine (manual fire: A while R is clicked)
        SmsFluddTriggerMovementTick(SmsParams.Fludd.Bomb, ref _fluddBombState, ref _fluddBombLeft, ref _fluddBombFill);
    }

    /// <summary>TNozzleTrigger::movement(): the charge (+150 x R a tick while pumping, minus the bleed, capped) fires the nozzle
    /// for TriggerTime ticks; then it is dead until R is released. A manual-fire nozzle (the burst) fires on A with R clicked
    /// instead of at the cap.</summary>
    private void SmsFluddTriggerMovementTick(SmsParams.Fludd.Nozzle p, ref int state, ref int left, ref float fill)
    {
        if (_fluddWater <= 0)
        {
            state = 0; left = 0; fill = 0f;
            return;
        }
        if (state == 1)
        {
            left--;
            if (_fluddUpper != SmsUpper.Pumping || left <= 0)
            {
                state = 2; fill = 0f; left = 0;
            }
        }
        if (p.ManualFire && _fluddAFrame && SmsRClick() && state == 0)
        {
            state = 1;
            left = p.TriggerTime;
            if (SmsDebugPrint) GD.Print($"[SMS fludd] {p.Name}: A with R clicked -> fires ({p.Num:F0} drops)");
        }
        bool canSpray = _fluddUpper == SmsUpper.Pumping && !(_smsInWater && _fluddWater < p.AmountMax);
        if (canSpray)
            fill += 150f * _fluddR;
        fill -= p.TriggerDec;
        if (fill < 0f) fill = 0f;
        if (fill > p.TriggerMax)
        {
            fill = p.TriggerMax;
            if (!p.ManualFire && state == 0)
            {
                state = 1;
                left = p.TriggerTime;
                if (SmsDebugPrint) GD.Print($"[SMS fludd] {p.Name}: charged -> ACTIVE for {p.TriggerTime} ticks");
            }
        }
        if (state == 2)
        {
            fill = 0f;
            if (_fluddR <= 0f)
                state = 0;
        }
    }

    /// <summary>TWaterGun::emit(): nothing while the pack is housed or the muzzle is under the water; each emitter fires.</summary>
    private void SmsFluddEmitTick(SmsParams.Fludd.Nozzle np)
    {
        if (_fluddStow > 0f || _fluddDrops == null)
            return;
        for (int e = 0; e < np.Emitters; e++)
        {
            if (!SmsFluddMuzzle(e, out Vector3 pos, out Vector3 dir))
                continue;
            if (_smsInWater && pos.Y < _smsWaterSurfaceY + SmsUnits.UnitsToMetres(20f))
                continue;
            if (_fluddNozzle == SmsNozzle.Spray)
                SmsFluddSprayEmit(np, pos, dir);
            else
                SmsFluddTriggerEmit(np, pos, dir, ref _fluddTrigState, ref _fluddTrigFill, ref _fluddTrigAccum);
        }
    }

    /// <summary>TNozzleDeform::emit(): the drops of one tick (0.8 a tick at full strength, the fraction carried), launched at
    /// 40 x strength with the tremble / size of the moment; then the burst's own emit.</summary>
    private void SmsFluddSprayEmit(SmsParams.Fludd.Nozzle np, Vector3 pos, Vector3 dir)
    {
        if (_fluddWater <= 0)
            return;
        if (_fluddBombState == 0 && _fluddSprayStrength > 0f)
        {
            float s = _fluddSprayStrength;
            _fluddEmitAccum += s * (np.Num - np.NumMin) + np.NumMin;
            int count = (int)_fluddEmitAccum;
            if (count > 0)
            {
                _fluddEmitAccum -= count;
                float pow = s * (np.EmitPow - np.EmitPowMin) + np.EmitPowMin;
                float tremble = s * (np.DirTremble - np.DirTrembleMin) + np.DirTrembleMin;
                // the decomp reads the size lerp as (minP - s) / (maxP - s), negative for 0 < s < maxP: taken as the plain lerp
                float sizeLerp = np.SizeMaxPressure > np.SizeMinPressure ? Mathf.Clamp((s - np.SizeMinPressure) / (np.SizeMaxPressure - np.SizeMinPressure), 0f, 1f) : 1f;
                float size = sizeLerp * (np.Size - np.SizeMin) + np.SizeMin;
                int emitted = _fluddDrops.Emit(count, pos, dir, tremble, pow, np.PowTremble, size, np.SizeTremble, np.Type, SmsFluddInheritVel());
                if (emitted > 0)
                {
                    _fluddWater = Math.Max(0, _fluddWater - emitted * np.DecRate);
                    _fluddEmittedTick += emitted;
                    SmsFluddRecoil(dir, pow, s * (np.ReactionPow - np.ReactionPowMin) + np.ReactionPowMin, np.ReactionY);
                }
            }
        }
        SmsFluddTriggerEmit(SmsParams.Fludd.Bomb, pos, dir, ref _fluddBombState, ref _fluddBombFill, ref _fluddBombAccum);
    }

    /// <summary>TNozzleTrigger::emit(): while ACTIVE, drops by the charge's pressure (count, launch speed), the tank charged
    /// DecRate each, the recoil (the hover's and the burst's are in; the rocket's ReactionY 0.7 launch is S4).</summary>
    private void SmsFluddTriggerEmit(SmsParams.Fludd.Nozzle p, Vector3 pos, Vector3 dir, ref int state, ref float fill, ref float accum)
    {
        if (_fluddWater <= 0 || state != 1)
            return;
        float pressure = p.TriggerMax > 0f ? fill / p.TriggerMax : 1f;
        accum += pressure * (p.Num - p.NumMin) + p.NumMin;
        int count = (int)accum;
        if (count == 0)
            return;
        accum -= count;
        float pow = pressure * (p.EmitPow - p.EmitPowMin) + p.EmitPowMin;
        int emitted = _fluddDrops.Emit(count, pos, dir, p.DirTremble, pow, p.PowTremble, p.Size, p.SizeTremble, p.Type, SmsFluddInheritVel());
        if (emitted > 0)
        {
            _fluddWater = Math.Max(0, _fluddWater - emitted * p.DecRate);
            _fluddEmittedTick += emitted;
            SmsFluddRecoil(dir, pow, pressure * (p.ReactionPow - p.ReactionPowMin) + p.ReactionPowMin, p.ReactionY);
        }
    }

    /// <summary>The emit's kick on Mario: addVelocity(reaction x (-dir . face) x pow) along the face, mVel.y += -dir.y x pow x
    /// ReactionY (in the air; on the ground the floor eats it, as the game's ground snap does).</summary>
    private void SmsFluddRecoil(Vector3 dir, float pow, float reaction, float reactionY)
    {
        if (reaction != 0f)
        {
            Vector3 face = _smsFaceValid ? SmsMath.DirFromYaw(_smsFaceYaw) : SmsFacingOrVelocityDir();
            float directionScale = -(dir.X * face.X + dir.Z * face.Z);
            float dv = reaction * directionScale * pow;
            if (dv != 0f)
            {
                float mps = SmsUnits.SpeedToMps(dv);
                velocity.X += face.X * mps;
                velocity.Z += face.Z * mps;
            }
        }
        if (reactionY != 0f)
        {
            float dvyUnits = -dir.Y * pow * reactionY; // TNozzleTrigger::emit: mMario->mVel.y += -dir.y x pow x ReactionY (+35 for the rocket)
            var np = SmsFluddCurrent;
            // a ROCKET entry follows this frame when rocketCheck() will pass: a RocketType-1 nozzle ACTIVE while pumping in a status that checks
            bool entryFollows = np.RocketType == 1 && _fluddTrigState == 1 && _fluddUpper == SmsUpper.Pumping && SmsHoverEntryState(stateOfMario)
                && !(stateOfMario == MarioState.ledgeFall && (_smsHangDropFall || _smsRocketLanding));
            if (stateOfMario == MarioState.fluddRocket)
            {
                _fluddHoverVy += dvyUnits; // rocketing() owns mVel.y: the launch ticks add to it
                _fluddRocketPushes++;
            }
            else if (entryFollows)
            {
                // the first ACTIVE tick's push is wiped in the game: rocketCheck() enters ROCKET on the next tick and setStatusToJumping
                // writes mVel.y = 10 over it; a later push fired in this frame before the entry waits for it
                if (_fluddTrigLeft != np.TriggerTime)
                    _fluddRocketVyPending += dvyUnits;
            }
            else if (!IsOnFloor())
            {
                float dvy = SmsUnits.SpeedToMps(dvyUnits);
                if (_smsTrueVyValid)
                    _smsTrueVy += dvy;
                else
                    velocity.Y += dvy;
            }
        }
    }

    /// <summary>damageExec(): each of the attacker's WaterEmit spills DamageLoss water (if there is any) as a 20-drop dribble
    /// from the muzzle (damagewateremit.prm: no launch speed, size 17, it just falls).</summary>
    private void SmsFluddDamage(int waterEmit)
    {
        if (!_fluddReady || waterEmit <= 0)
            return;
        var np = SmsFluddCurrent;
        for (int i = 0; i < waterEmit; i++)
        {
            if (_fluddWater <= 0)
                break;
            _fluddWater = Math.Max(0, _fluddWater - np.DamageLoss);
            if (_fluddDrops != null && SmsFluddMuzzle(0, out Vector3 pos, out _))
                _fluddDrops.Emit(20, pos, Vector3.Up, 0f, 0f, 0f, 17f, 0f, 0, Vector3.Zero);
        }
        if (SmsDebugPrint) GD.Print($"[SMS fludd] hit: -{waterEmit} x {np.DamageLoss} water -> {_fluddWater}/{np.AmountMax}");
    }

    // ---------------------------------------------------------------------------------------------------------------
    // FLUDD S3: the hover (MARIO_STATUS_ROCKET with the hover nozzle -- rocketCheck / rocketing, MarioJump.cpp; hhover.prm).
    // A JUMPING-type status of its own: vy = (pressY + 230 - y) x 0.02 ASSIGNED every tick (a spring to the press height plus
    // HoverHeight; the gravity fallProcess adds after the move is overwritten before the next), fwd x 0.985, the stick pushes
    // fore / aft or turns the face, ANIM_LAND with the pump on the upper body, the nozzles banking with the stick. It ends into
    // ROCKET_LANDING (landing(): the port's ledgeFall with _smsRocketLanding) when R lifts, the 3 s window closes, the tank runs
    // dry or the nozzle changes. Touching the floor does not land him (jumpProcess case 1 is a no-op in rocketing(): the spring
    // lifts him off again); a roof stops him (fwd 0) -- and never hangs him: hipAttacking calls jumpProcess(0), and checkGroundAtJumping gives the
    // fence-roof code 4 only with param_2 & 2 (MarioPhysics.cpp 393; the rocket's rise does, SmsRoofHangCheck). Pass 110 corrected this comment.
    // ---------------------------------------------------------------------------------------------------------------

    /// <summary>TWaterGun::canSpray(): water in the tank and, for a trigger nozzle, its state ACTIVE (the spray: a strength).</summary>
    private bool SmsFluddCanSpray() => _fluddReady && _fluddWater > 0
        && (_fluddNozzle == SmsNozzle.Spray ? _fluddSprayStrength > 0f : _fluddTrigState == 1);

    /// <summary>Who calls rocketCheck(): jumpingCommonEvents (JUMP, SECOND_JUMP, U_TURN_JUMP, TRAMPLE), ultraJumping, backJumping,
    /// jumpWall, rotateJumping, landing() (LANDING -- a walk-off fall; not LAND_SAFE_DOWN), running(), waiting(); squating()
    /// takes the hover from the squat when the nozzle emits. Not the dives, the broad jumps, the rolls, the slides, the hang,
    /// the water. landing() also runs for ROCKET_LANDING, but rocketCheck() itself refuses that status (see below).</summary>
    private static bool SmsHoverEntryState(MarioState s) =>
        s == MarioState.singleJump || s == MarioState.doubleJump || s == MarioState.tripleJump || s == MarioState.SpinJump
        || s == MarioState.sideFlip || s == MarioState.backFlip || s == MarioState.wallJump || s == MarioState.stomping
        || s == MarioState.ledgeFall || s == MarioState.idle || s == MarioState.walking || s == MarioState.running
        || s == MarioState.sprinting || s == MarioState.sneak || s == MarioState.rolloutRun || s == MarioState.crouch;

    /// <summary>rocketCheck(): not ROCKET, NOT ROCKET_LANDING (one hover per airtime: after it ends the fall keeps that status
    /// through wall stops until the landing, a ledge grab, a knockdown or the water change it -- the nozzle re-arms on R = 0,
    /// Mario's status is what rations it), HAS_FLUDD, the nozzle's RocketType 1 (the hover; the rocket nozzle is S4),
    /// UPPER_STATE_PUMPING (R down), canSpray() -> ROCKET with the target 230 units over the feet. Runs before the state
    /// handlers, as the game's stateMachine loop runs rocketing() in the tick that entered it.</summary>
    private void SmsFluddRocketCheck()
    {
        if (!_fluddReady || stateOfMario == MarioState.fluddRocket || !SmsHoverEntryState(stateOfMario))
            return;
        if (stateOfMario == MarioState.ledgeFall && (_smsHangDropFall || _smsRocketLanding))
            return; // LAND_SAFE_DOWN: landSafeDown() has no rocketCheck; ROCKET_LANDING: rocketCheck() returns 0 for it
        if (SmsFluddCurrent.RocketType != 1 || _fluddUpper != SmsUpper.Pumping || !SmsFluddCanSpray())
            return; // the rocket nozzle only gets here once its charge is full (ACTIVE); the hover the tick R goes down
        SmsEnterRocketStatus();
    }

    private void SmsEnterRocketStatus()
    {
        MarioState from = stateOfMario;
        Vector3 velXZ = new Vector3(velocity.X, 0f, velocity.Z);
        // a launched jump keeps its latched face; from the ground (or a face that never latched) it is the way he moves, else looks
        if (!_smsFaceValid || IsOnFloor())
            SmsLatchFace(velXZ.LengthSquared() > 0.25f ? velXZ : new Vector3(lastFacingDirection.X, 0f, lastFacingDirection.Z), 2);
        Vector3 face = SmsMath.DirFromYaw(_smsFaceYaw);
        _fluddHoverFwd = SmsUnits.MpsToSpeed(velXZ.Dot(face)); // mForwardVel: the jump's speed along the face carries on
        // setStatusToJumping(ROCKET): mVel.y = 10. The hover's spring overwrites it before the first move; for the rocket it is the
        // launch's base -- it wipes the first ACTIVE tick's push (fired the tick before the status change) and the later pushes add
        // to it; one fired earlier in this frame than this entry waits in _fluddRocketVyPending
        _fluddHoverVy = SmsHover.EntryVy + _fluddRocketVyPending;
        _fluddRocketPushes = _fluddRocketVyPending > 0f ? 1 : 0;
        _fluddRocketVyPending = 0f;
        // unk314 = mPosition.y + HoverHeight (running() / waiting() write mFloorPosition.y + HoverHeight: the same on the floor)
        _fluddHoverStartY = SmsFeetY();
        _fluddHoverTargetY = _fluddHoverStartY + SmsUnits.UnitsToMetres(SmsParams.Fludd.HoverHeight);
        _fluddHoverTicks = 0;
        _fluddHoverRoofDbg = false;
        _fluddHoverDbgNext = 120;
        isJumping = false;
        jumpBuffer = 0;
        _smsFallCancel = false;
        _smsHangDropFall = false;
        _smsRocketLanding = false;
        _smsTrueVyValid = false;
        StopWaistIKHard(); // the run's waist IK is started / stopped in the main path, which the hover skips
        isSpining(false);  // so are the spin jump's ring and particles (the main air path switches them every frame)
        SleepStatus(false);
        lastFacingDirection = face;
        armature.Rotation = new Vector3(0f, YawFromDir(face), 0f);
        stateOfMario = MarioState.fluddRocket;
        SetMarioState(MarioState.fluddRocket); // ANIM_LAND; the pump rides the upper-body blend
        if (SmsDebugPrint)
        {
            if (_fluddNozzle == SmsNozzle.Rocket)
                GD.Print($"[SMS rocket] launch from {from}: vy {_fluddHoverVy:F0} (the entry's 10{(_fluddRocketPushes > 0 ? " + a push of 35 already this frame" : "")}), fwd {_fluddHoverFwd:F1} ({SmsUnits.SpeedToMps(_fluddHoverFwd):F1} m/s), water {_fluddWater}, R {_fluddR:F2}");
            else
                GD.Print($"[SMS hover] start from {from}: target +{SmsParams.Fludd.HoverHeight:F0} units ({SmsUnits.UnitsToMetres(SmsParams.Fludd.HoverHeight):F2} m) over feet y {_fluddHoverStartY:F2}, fwd {_fluddHoverFwd:F1} ({SmsUnits.SpeedToMps(_fluddHoverFwd):F1} m/s), water {_fluddWater}, R {_fluddR:F2}");
        }
    }

    /// <summary>rocketing() for one physics frame: the exits, the stick, the spring, the brake; no other handler runs.</summary>
    private void SmsTickRocketStatus(double delta, Vector3 inputDirWorld)
    {
        _smsTrueVyValid = false;
        // the exits come first: !HAS_FLUDD / RocketType != 1 / !isUpperState(PUMPING) / !canSpray() -> ROCKET_LANDING
        string why = null;
        if (SmsFluddCurrent.RocketType != 1) why = "the nozzle changed";
        else if (_fluddWater <= 0) why = "the tank ran dry";
        else if (_fluddTrigState == 2) why = _fluddNozzle == SmsNozzle.Rocket ? "the 5 launch ticks are done" : "the 3 s ran out"; // DEAD also drops the pump (checkPumpEnable), so it is tested first
        else if (_fluddUpper != SmsUpper.Pumping) why = "R released";
        else if (_fluddTrigState != 1) why = "the nozzle is not spraying";
        if (why != null)
        {
            SmsExitRocketStatus(why);
            return;
        }
        int n = SmsUnits.TicksFor(delta, ref _smsTickAccum);
        var np = SmsParams.Fludd.Hover;
        bool stick = inputDirWorld.LengthSquared() > 1e-6f && _smsIntendedMag > 0f;
        float intendedYaw = stick ? SmsMath.YawFromDir(new Vector3(inputDirWorld.X, 0f, inputDirWorld.Z).Normalized()) : 0f;
        float mag = stick ? _smsIntendedMag : 0f;
        float y = SmsUnits.MetresToUnits(SmsFeetY());
        float target = SmsUnits.MetresToUnits(_fluddHoverTargetY);
        float fwd = _fluddHoverFwd, vy = _fluddHoverVy, sumVy = 0f;
        float tiltL = 0f, tiltR = 0f;
        bool roof = IsOnCeiling();
        bool rocketNozzle = _fluddNozzle == SmsNozzle.Rocket;
        for (int i = 0; i < n; i++)
        {
            if (rocketNozzle)
            {
                // rocketing() with the rocket nozzle: both switches have only the Hover case -- no push, no turn, no bank, mVel.y
                // left to fallProcess (the launch's pushes arrive through the emit, SmsFluddRecoil), fwd not braked; a roof zeroes
                // fwd and a rising vy (checkGroundAtJumping's roof branch); jumpProcess moves 0.25 x vel, then the gravity
                if (roof)
                {
                    fwd = 0f;
                    if (vy > 0f) vy = 0f;
                }
                if (fwd > SmsParams.Jump.JumpingMax) fwd = SmsParams.Jump.JumpingMax;
                float mv = vy;
                vy -= SmsParams.Jump.Gravity;
                if (vy < SmsParams.Timing.TerminalVy) vy = SmsParams.Timing.TerminalVy;
                y += 0.25f * mv;
                sumVy += mv;
                continue;
            }
            if (stick)
            {
                float d = SmsMath.WrapAngle(intendedYaw - _smsFaceYaw);
                float ad = MathF.Abs(d);
                if (ad < SmsHover.FrontBandBam * SmsUnits.BamToRad || ad > SmsHover.BackBandBam * SmsUnits.BamToRad)
                {
                    // within 30 deg of the face, or beyond 150: a push along the face at the dive's air-control rate, no turn;
                    // the nozzles tip together by SideAngleMaxFront (0 for the hover) ahead, SideAngleMaxBack (8000) behind
                    float maxTilt = ad <= MathF.PI * 0.5f ? np.SideAngleMaxFront : np.SideAngleMaxBack;
                    tiltL = tiltR = 0.03125f * -mag * maxTilt * MathF.Cos(d);
                    fwd += mag * MathF.Cos(d) * SmsHover.AccelControl;
                }
                else
                {
                    // sideways: the face turns toward the stick at RotSp (200 BAM a tick), no push; the nozzles bank opposite ways
                    float t = 0.03125f * -mag * np.SideAngleMaxSide * MathF.Sin(d);
                    tiltL = -t;
                    tiltR = t;
                    _smsFaceYaw = SmsMath.ConvergeAngle(_smsFaceYaw, intendedYaw, SmsHover.RotSp * SmsUnits.BamToRad);
                }
            }
            if (roof)
                fwd = 0f; // checkGroundAtJumping(): a roof overhead -> setPlayerVelocity(0), vy 0 (the spring restarts the climb)
            // Hover: mVel.y = (unk314 - mPosition.y) x AccelRate, assigned; mForwardVel *= Brake; jumpProcess moves 0.25 x vel
            vy = SmsHover.SpringVy(y, target);
            fwd *= SmsHover.Brake;
            y += 0.25f * vy;
            sumVy += vy;
        }
        _fluddHoverTicks += n;
        _fluddHoverFwd = fwd;
        _fluddHoverVy = vy;
        _fluddTiltTargetL = tiltL;
        _fluddTiltTargetR = tiltR;
        Vector3 face = SmsMath.DirFromYaw(_smsFaceYaw);
        float mps = SmsUnits.SpeedToMps(fwd);
        velocity.X = face.X * mps;
        velocity.Z = face.Z * mps;
        velocity.Y = SmsUnits.SpeedToMps(sumVy / n);
        lastFacingDirection = face;
        armature.Rotation = new Vector3(0f, YawFromDir(face), 0f);
        if (SmsDebugPrint)
        {
            if (roof && !_fluddHoverRoofDbg)
            {
                _fluddHoverRoofDbg = true;
                GD.Print("[SMS hover] a roof overhead: speed 0 while he presses on it (the game would hang him from a fence roof; none here)");
            }
            if (_fluddHoverTicks >= _fluddHoverDbgNext)
            {
                _fluddHoverDbgNext += 120;
                GD.Print($"[SMS hover] {_fluddHoverTicks / 120f:F1} s: +{SmsFeetY() - _fluddHoverStartY:F2} m of {SmsUnits.UnitsToMetres(SmsParams.Fludd.HoverHeight):F2}, vy {vy:F2}, fwd {fwd:F1} ({mps:F1} m/s), water {_fluddWater}");
            }
        }
    }

    /// <summary>changePlayerStatus(ROCKET_LANDING): landing() from the hover's last velocity -- the port's ledgeFall flagged
    /// _smsRocketLanding (no wall slide on a wall at 16..40); on the floor at that moment he lands at once (jumpingBasic case 1).</summary>
    private void SmsExitRocketStatus(string why)
    {
        Vector3 face = SmsMath.DirFromYaw(_smsFaceYaw);
        float mps = SmsUnits.SpeedToMps(_fluddHoverFwd);
        velocity.X = face.X * mps;
        velocity.Z = face.Z * mps;
        // the last rocketing() tick's fallProcess ran after its move: ROCKET_LANDING starts from the spring's vy less one tick of gravity
        float vy = _fluddHoverVy - SmsParams.Jump.Gravity;
        velocity.Y = SmsUnits.SpeedToMps(vy);
        _smsTrueVyValid = false;
        _fluddTiltTargetL = 0f;
        _fluddTiltTargetR = 0f;
        isJumping = false;
        _smsFallCancel = false;
        _smsHangDropFall = false;
        lastFacingDirection = face;
        float rose = SmsFeetY() - _fluddHoverStartY;
        if (SmsDebugPrint)
        {
            if (_fluddNozzle == SmsNozzle.Rocket)
                GD.Print($"[SMS rocket] off ({why}) after {_fluddHoverTicks} ticks: vy {vy:F0} from {_fluddRocketPushes} pushes of 35 (apex about {SmsUnits.UnitsToMetres(0.125f * vy * (vy + 1f)):F1} m up from here), fwd {_fluddHoverFwd:F1} ({mps:F1} m/s), water {_fluddWater}{(IsOnFloor() ? ", on the floor: lands" : "")}");
            else
                GD.Print($"[SMS hover] end ({why}) after {_fluddHoverTicks} ticks ({_fluddHoverTicks / 120f:F2} s): rose {rose:F2} m = {SmsUnits.MetresToUnits(rose):F0} units of the {SmsParams.Fludd.HoverHeight:F0}, fwd {_fluddHoverFwd:F1} ({mps:F1} m/s), vy {vy:F1}, water {_fluddWater}{(IsOnFloor() ? ", on the floor: lands" : "")}");
        }
        _fluddRocketVyPending = 0f;
        if (IsOnFloor())
        {
            // landing() on the floor at once (jumpingBasic() case 1 -> LAND_SLIP): his floor contact never counted as a landing
            // while he hovered, so the landing rule would not fire on its own
            velocity.Y = 0f;
            landingEnteredThisContact = false;
            _smsRocketLanding = false;
            EnterLanding(MarioState.landing, "ma_laend");
            return;
        }
        _smsRocketLanding = true;
        stateOfMario = MarioState.ledgeFall;
        SetMarioState(MarioState.ledgeFall);
    }

    /// <summary>TWaterGun::movement(): unk1CC8 / unk1CCC chase the bank rocketing() asked for (unk1CC2 / unk1CC4) by ChangeSpeed
    /// a tick; nothing asked (not hovering, or not spraying) reads as 0.</summary>
    private void SmsFluddTiltTick()
    {
        if (stateOfMario != MarioState.fluddRocket || _fluddNozzle != SmsNozzle.Hover || !SmsFluddCanSpray())
        {
            _fluddTiltTargetL = 0f;
            _fluddTiltTargetR = 0f;
        }
        _fluddTiltL += (_fluddTiltTargetL - _fluddTiltL) * SmsParams.Fludd.ChangeSpeed;
        _fluddTiltR += (_fluddTiltTargetR - _fluddTiltR) * SmsParams.Fludd.ChangeSpeed;
    }

    /// <summary>WaterGunDivingCtrlL / R: jnt_nozzle_L / R turned about their local Z by -unk1CC8 / -unk1CCC after the clip.</summary>
    private void SmsFluddApplyTilt()
    {
        if (_fluddTilt == null)
            return;
        _fluddTilt.Angles[0] = -_fluddTiltL * SmsUnits.BamToRad;
        _fluddTilt.Angles[1] = -_fluddTiltR * SmsUnits.BamToRad;
    }

    /// <summary>NozzleCtrl (WaterGun.cpp 126, bound to jnt_back_nozzle_neck): a gun angle below 0 turns the neck about its local Z
    /// after the clip -- the turbo's head tilted 22.5 deg down (-LAngleBase) whenever it is selected with water. A gun angle above 0
    /// bends the chest instead (MarioWaistCtrl: the squat aim up, S2b). The spray's callback joint (chn_muzzle_l) is not in
    /// normal_wg and its LAngleBase is 0; rocket_wg has no neck.</summary>
    private void SmsFluddApplyGunAngle()
    {
        if (_smsHeadGunRot != null && !_smsTalking)   // MarioHeadCtrl's READ_BILLBOARD branch owns the head during a talk (SmsTalkTick)
            _smsHeadGunRot.Angles[0] = _fluddGunAngle < 0f ? 0.5f * _fluddGunAngle * SmsUnits.BamToRad : 0f; // MarioHeadCtrl: Rz(angle / 2)
        if (_fluddSprayAim != null)
            _fluddSprayAim.Angles[0] = _fluddNozzle == SmsNozzle.Spray && _fluddGunAngle < 0f ? _fluddGunAngle * SmsUnits.BamToRad : 0f;
        if (_fluddNeckRot == null)
            return;
        _fluddNeckRot.Angles[0] = _fluddNozzle == SmsNozzle.Turbo && _fluddGunAngle < 0f ? _fluddGunAngle * SmsUnits.BamToRad : 0f;
    }

    private void SmsFluddSetupTurboNeck()
    {
        var sk = _fluddNozzleSkel[(int)SmsNozzle.Turbo];
        if (sk == null)
            return;
        _fluddNeckRot = new SmsBoneRotZ { Name = "SmsTurboNeckAim", BoneNames = new[] { "jnt_back_nozzle_neck" }, Angles = new float[1] };
        sk.AddChild(_fluddNeckRot);
        if (SmsDebugPrint)
            GD.Print($"[SMS fludd] turbo neck joint jnt_back_nozzle_neck {(sk.FindBone("jnt_back_nozzle_neck") >= 0 ? "yes" : "NO")}: the gun angle -{SmsParams.Fludd.Turbo.LAngleBase} BAM = {SmsParams.Fludd.Turbo.LAngleBase * SmsUnits.BamToRad * 180f / Mathf.Pi:F1} deg down");
    }

    /// <summary>NozzleCtrl's other binding (WaterGun.cpp 1357): the spray nozzle's muzzle chain root. A negative gun angle -- the
    /// squat's pull-back, the Y cam looking up -- turns it about its local Z, which lifts the forward barrel: the aim UP, to
    /// LAngleMin (-13000 = 71 deg); the aim down is the chest bend. The decomp's literal is "chn_muzzle_l" (a letter) while the
    /// model's joint is chn_muzzle_1 (a digit): the design, the shipped range and the game as played say the binding works.</summary>
    private void SmsFluddSetupSprayAim()
    {
        var sk = _fluddNozzleSkel[(int)SmsNozzle.Spray];
        if (sk == null)
            return;
        _fluddSprayAim = new SmsBoneRotZ { Name = "SmsSprayNozzleAim", BoneNames = new[] { "chn_muzzle_1" }, Angles = new float[1] };
        sk.AddChild(_fluddSprayAim);
        if (SmsDebugPrint)
            GD.Print($"[SMS fludd] spray aim joint chn_muzzle_1 {(sk.FindBone("chn_muzzle_1") >= 0 ? "yes" : "NO")}: a negative gun angle lifts the barrel, to {-SmsParams.Fludd.Spray.LAngleMin * 180f / 32768f:F0} deg");
    }

    private void SmsFluddSetupHoverTilt()
    {
        var sk = _fluddNozzleSkel[(int)SmsNozzle.Hover];
        if (sk == null)
            return;
        _fluddTilt = new SmsBoneRotZ { Name = "SmsHoverNozzleTilt", BoneNames = new[] { "jnt_nozzle_L", "jnt_nozzle_R" }, Angles = new float[2] };
        sk.AddChild(_fluddTilt);
        if (SmsDebugPrint)
            GD.Print($"[SMS fludd] hover nozzle bank joints: jnt_nozzle_L {(sk.FindBone("jnt_nozzle_L") >= 0 ? "yes" : "NO")}, jnt_nozzle_R {(sk.FindBone("jnt_nozzle_R") >= 0 ? "yes" : "NO")}");
    }

    // ---------------------------------------------------------------------------------------------------------------
    // FLUDD S5: the turbo nozzle -- the dash (MarioMove.cpp's input stage + running()), the broad jump, the surf (swimPaddle).
    // The dash is not a status: the input stage replaces the stick's magnitude with mDashSpeed (0.5 a tick to 32) while the
    // turbo pumps, and the FLUDD_EMITTING flag -- on once the trigger is ACTIVE, only while running or paddling -- makes
    // running() / swimPaddle() force the speed to DashMax 80 every tick.
    // ---------------------------------------------------------------------------------------------------------------

    /// <summary>The statuses that keep FLUDD_EMITTING: RUN (the port's ground locomotion; WAIT turns into RUN the same tick the
    /// dash's magnitude arrives) and SWIM_PADDLE.</summary>
    private bool SmsDashState() =>
        stateOfMario == MarioState.idle || stateOfMario == MarioState.walking || stateOfMario == MarioState.running
        || stateOfMario == MarioState.sprinting || stateOfMario == MarioState.sneak || stateOfMario == MarioState.rolloutRun
        || (stateOfMario == MarioState.swimming && _smsSwim == SmsSwim.Paddle)
        || (stateOfMario == MarioState.singleJump && _fluddBroadJump); // broadJumping(): onFlag(FLUDD_EMITTING) every tick

    /// <summary>FLUDD in use: the upper body pumps or holds the pump, or the turbo dashes / ramps. No waist IK then (Jaysonn).</summary>
    private bool SmsFluddBusy() =>
        SmsPumpingStyle() || (UseSmsPhysics && _fluddReady && (_fluddDashing || _fluddDashSpeed > 0f));

    /// <summary>isUpperPumpingStyle(): the upper body is PUMPING or HOLDING_PUMP -- the run and the swim turn at the pumping rates,
    /// no U-turn (isRunningTurnning() is false).</summary>
    private bool SmsPumpingStyle() => UseSmsPhysics && _fluddReady && _fluddUpper != SmsUpper.Idle;

    /// <summary>The turbo's charge: mDashSpeed climbing under a pumping turbo with water, before FLUDD_EMITTING.</summary>
    private bool SmsTurboCharging() => _fluddReady && !_fluddDashing && _fluddDashSpeed > 0f && _fluddNozzle == SmsNozzle.Turbo
        && _fluddUpper == SmsUpper.Pumping && _fluddR > 0f && _fluddWater > 0;

    /// <summary>The input stage's dash block, one tick (after the gun, so the trigger's state is this tick's).</summary>
    private void SmsFluddDashTick()
    {
        bool pumpingTurbo = _fluddReady && _fluddNozzle == SmsNozzle.Turbo && _fluddUpper == SmsUpper.Pumping && _fluddR > 0f && _fluddWater > 0;
        if (pumpingTurbo)
        {
            bool starting = !_fluddChargeTicked;
            float fwdNow = SmsUnits.MpsToSpeed(new Vector2(velocity.X, velocity.Z).Length());
            if (starting && SmsParams.Fludd.ChargeKeepsSpeed)
            {
                // DELIBERATE DEVIATION (SmsParams.Fludd.ChargeKeepsSpeed): the game's mDashSpeed starts at 0 whatever he was doing, and
                // mIntendedMag = mDashSpeed then brakes a sprint to a crawl in 6 ticks (DecBrake 5) before the 0.53 s climb -- the
                // turbo's wind-up. Jaysonn (2026-09-29 20:48): "he should[n't] have to stand still for a frame". The charge picks up at
                // the forward speed he already carries along his face; from a stand nothing changes.
                Vector3 velXZ = new Vector3(velocity.X, 0f, velocity.Z);
                float along = _smsFaceValid ? MathF.Max(0f, SmsUnits.MpsToSpeed(velXZ.Dot(SmsMath.DirFromYaw(_smsFaceYaw)))) : fwdNow;
                _fluddDashSpeed = Mathf.Clamp(MathF.Max(_fluddDashSpeed, along), 0f, 32f);
            }
            if (starting && SmsDebugPrint)
                GD.Print($"[SMS turbo] charge on (from {stateOfMario}): stick {_smsIntendedMag:F1} of 32, model {Mathf.RadToDeg(SmsMath.YawFromDir(SmsModelFacing())):F0} deg, face {Mathf.RadToDeg(_smsFaceYaw):F0} deg, fwd {fwdNow:F1}, dash speed from {_fluddDashSpeed:F1}");
            _fluddChargeTicked = true;
            _fluddDashSpeed += SmsParams.Mario.DashAcc;
            if (_fluddDashSpeed >= 32f)
            {
                _fluddDashSpeed = 32f;
                // mDashTimer > DashStartTime (0): at once. The flag needs the trigger ACTIVE (the 0.75 s charge) and a status that keeps it.
                bool wasOn = _fluddDashing;
                if (!_fluddDashing && _fluddTrigState == 1)
                {
                    // onFlag + SE_PO_SNIPER_TRIGGER; the status check below takes it away again unless he runs or paddles. In the
                    // air the game does this every tick -- the turbo's stutter is that SE. Nothing is heard here, so the print waits.
                    _fluddDashing = true;
                    _fluddDashDbgFrom = stateOfMario.ToString();
                    if (stateOfMario == MarioState.swimming && !_smsDrowned && _smsSwim != SmsSwim.PDamage)
                        SmsSwimSet(SmsSwim.Paddle); // changePlayerStatus(SWIM_PADDLE)
                }
                if (_fluddDashing && !SmsDashState())
                    _fluddDashing = false; // mDashTimer = 0, offFlag: the status is not RUN (0x440) or SWIM_PADDLE
                if (_fluddDashing && SmsDebugPrint && ++_fluddDashDbgTicks >= 60)
                {
                    // the surf question (2026-09-28 01:17): where the jet leaves, and everything that decides it
                    _fluddDashDbgTicks = 0;
                    string spine = "?";
                    if (_fluddAttach != null)
                    {
                        // the pack's attachment follows jnt_chest as DRAWN (graft, lean and all); the skeleton's own poses are the clip's
                        Vector3 up = _fluddAttach.GlobalTransform.Basis.X.Normalized(); // X = up the spine
                        spine = $"{Mathf.RadToDeg(Mathf.Acos(Mathf.Clamp(up.Y, -1f, 1f))):0} deg from upright";
                    }
                    string water = stateOfMario == MarioState.swimming
                        ? $", swim {_smsSwim}, feet {SmsUnits.MetresToUnits(_smsWaterSurfaceY - SmsFeetY()):0} u under the surface, pump graft {(_fluddUpperGraft.TryGetValue(SmsParams.Fludd.UpperSwPmp, out var sg) ? sg.Weight.ToString("0.0") : "none")}"
                        : $", {stateOfMario}";
                    GD.Print($"[SMS turbo] dashing: jet {SmsFluddJetDbg()}; spine {spine}; upper {_fluddUpper}, R {_fluddR:0.00}, trigger {_fluddTrigState}{water}; anim {(stateOfMario == MarioState.swimming ? _smsSwimAnim : _smsGaitClip)} rate {(stateOfMario == MarioState.swimming ? (animPlayer?.SpeedScale ?? 0f) : _smsRunRate):0.00}");
                }
                if (_fluddDashing && !wasOn && SmsDebugPrint)
                    GD.Print($"[SMS turbo] dash on (from {_fluddDashDbgFrom}): {SmsParams.Mario.DashMax:F0} a tick = {SmsUnits.SpeedToMps(SmsParams.Mario.DashMax):F1} m/s, water {_fluddWater}, jet {SmsFluddJetDbg()}");
                else if (!_fluddDashing && wasOn)
                    SmsFluddDashOff("not running or paddling");
            }
        }
        else
        {
            _fluddChargeTicked = false;
            if (_fluddDashSpeed > 0.1f)
                _fluddDashSpeed *= SmsParams.Mario.DashBrake;
            else
                _fluddDashSpeed = 0f;
            if (_fluddDashing)
                SmsFluddDashOff(_fluddNozzle != SmsNozzle.Turbo ? "the nozzle changed" : _fluddWater <= 0 ? "the tank ran dry" : "R released");
        }
    }


    // ---------------------------------------------------------------------------------------------------------------
    // MARIO_STATUS_SQUAT / SQUAT_STANDUP (MarioWait.cpp squating() 308, squatStandup() 387; MarioMove.cpp canSquat() 44).
    // ---------------------------------------------------------------------------------------------------------------

    /// <summary>canSquat(): the FLUDD out, not a RocketType-1 nozzle (the hover, the rocket) and not the turbo (mCurrentNozzle != 5:
    /// the click with the turbo is the dash's charge -- he keeps walking as mDashSpeed builds and runs into the dash), not Yoshi,
    /// and mInput 0x200 -- R or L held while not FLUDD_EMITTING (the dash). MEANING_R is the GC trigger's click at the end of its
    /// travel; without a button_rclick action the pad's full pull stands in (SmsRClick). The legacy Z is an alias of L here.</summary>
    private bool SmsCanSquat()
    {
        if (!_fluddReady || _fluddDashing || SmsFluddCurrent.RocketType == 1 || _fluddNozzle == SmsNozzle.Turbo)
            return false;
        return SmsRClick() || SmsSquatLHeld();
    }

    private static bool SmsSquatLHeld() => Input.IsActionPressed("button_l") || Input.IsActionPressed("button_z") || Input.IsActionPressed("key_z");

    /// <summary>squating() / squatStandup() for one physics frame. True: the frame is his (the caller ends it). False: the stand-up
    /// was cut by A (JUMP) or the stick (RUN) and he is idle -- the ground logic runs on this frame.</summary>
    private bool SmsSquatFrame(double delta)
    {
        int n = SmsUnits.TicksFor(delta, ref _smsTickAccum);
        // waitProcess(): no velocity, on the floor
        velocity.X = 0f;
        velocity.Z = 0f;
        velocity.Y = -2f;
        bool aFrame = Input.IsActionJustPressed("button_a") || Input.IsActionJustPressed("key_space");
        bool stick = _smsIntendedMag > 0f;
        if (_smsSquatEndTicks > 0)
        {
            // SQUAT_STANDUP: mInput 0x2 (A) -> JUMP, 0x1 (the stick) -> RUN, both cutting ma_sqend; else its last frame -> WAIT
            if (aFrame || stick)
            {
                SmsSquatLeave("stand-up cut");
                return false;
            }
            _smsSquatEndTicks -= n;
            if (_smsSquatEndTicks <= 0)
                SmsSquatLeave("stood up");
            return true;
        }
        bool rHeld = SmsRClick();
        bool lHeld = SmsSquatLHeld();
        if (!rHeld && !lHeld)
        {
            // !(mInput & 0x4000) && !(mInput & 0x200): neither R nor L -> SQUAT_STANDUP, ma_sqend (19 frames)
            _smsSquatEndTicks = SmsParams.Squat.EndTicks;
            SmsSquatClip(_smsSquatEndReady ? "ma_sqend" : "ma_wait", 1f);
            if (SmsDebugPrint)
                GD.Print($"[SMS squat] stand-up: ma_sqend {SmsParams.Squat.EndTicks} ticks, gun angle {_fluddGunAngle:F0} BAM");
            return true;
        }
        if (SmsFluddCurrent.RocketType == 1)
        {
            // the nozzle became the hover / rocket in the squat: squating() would go to ROCKET once it emits; the nozzle code owns that
            SmsSquatLeave("hover / rocket nozzle");
            return false;
        }
        if (aFrame && rHeld && _fluddNozzle == SmsNozzle.Spray)
        {
            // mInput 0x2 with MEANING_R and the spray nozzle: BACK_JUMP (rumble MotorHipDrop)
            _smsSquatEndTicks = 0;
            StartBackflip();
            return true;
        }
        Vector3 face = SmsMath.DirFromYaw(_smsFaceYaw);
        if (lHeld)
        {
            // getSideWalkValues(): side = mIntendedMag x sin(intendedYaw - face) x PumpingSlideSp, units a TICK along his left (the
            // status handler runs per tick and adds it to mPosition itself); SWLKL when the stick is to his left, SWLKR to his right,
            // at |side| x PumpingSlideAnmSp; SQWAT at rate 1 when the stick rests
            float diff = stick && direction.LengthSquared() > 1e-6f ? SmsMath.WrapAngle(SmsMath.YawFromDir(direction.Normalized()) - _smsFaceYaw) : 0f;
            float side = stick ? _smsIntendedMag * MathF.Sin(diff) * SmsParams.Squat.SlideSp : 0f;
            if (side == 0f)
                SmsSquatClip("ma_sqwat", 1f);
            else
            {
                SmsSquatClip(diff > 0f ? "ma_swlkl" : "ma_swlkr", MathF.Abs(side) * SmsParams.Squat.SlideAnmSp);
                Vector3 left = Vector3.Up.Cross(face).Normalized();
                float mps = side * SmsUnits.TicksPerSecond / SmsUnits.UnitsPerMetre;
                velocity.X = left.X * mps;
                velocity.Z = left.Z * mps;
            }
        }
        else
        {
            // R held: |stick H| through the SquatRotMid curve (5 % of the rate to 70 % deflection, then up to all of it) x
            // -WaitingRotSp (220 BAM) a tick, truncated to a whole BAM as the game's s16 cast does: stick right = a right turn
            float absH = MathF.Abs(_smsStickH);
            float mid = SmsParams.Squat.RotMidAnalog, midVal = SmsParams.Squat.RotMidValue;
            float rotAmt = absH < mid ? midVal * (absH / mid) : midVal + (1f - midVal) * ((absH - mid) / (1f - mid));
            if (_smsStickH < 0f)
                rotAmt = -rotAmt;
            float stepBam = MathF.Truncate(rotAmt * -SmsParams.Mario.WaitingRotSp);
            if (stepBam != 0f)
            {
                for (int i = 0; i < n; i++)
                    _smsFaceYaw = SmsMath.WrapAngle(_smsFaceYaw + stepBam * SmsUnits.BamToRad);
                face = SmsMath.DirFromYaw(_smsFaceYaw);
                lastFacingDirection = face;
                _smsLatchedFacing = face;
                armature.Rotation = armature.Rotation with { Y = BaseYawFromDir(face) };
            }
            SmsSquatClip("ma_sqwat", 1f);
        }
        return true;
    }

    private void SmsSquatLeave(string why)
    {
        _smsSquatEndTicks = 0;
        _smsSquatClipNow = "";
        if (animTree != null && animTree.Active)
            animTree.Set(RUN_TIMESCALE_PATH, 1f);
        stateOfMario = MarioState.idle;
        SetMarioState(stateOfMario);
        if (SmsDebugPrint)
            GD.Print($"[SMS squat] off ({why})");
    }

    /// <summary>The squat's clip on the BaseSM (ma_sqwat is a scene state; ma_sqend / ma_swlkl / ma_swlkr are added at start-up) at the
    /// game's rate through the tree's RunTimeScale.</summary>
    private void SmsSquatClip(string clip, float rate)
    {
        if (animTree == null || !animTree.Active || _sm == null)
            return;
        if (clip != _smsSquatClipNow)
        {
            _smsSquatClipNow = clip;
            _sm.Travel(clip);
        }
        animTree.Set(RUN_TIMESCALE_PATH, MathF.Max(rate, 0.01f));
    }

    /// <summary>ma_sqend, ma_swlkl and ma_swlkr as BaseSM states (the scene has only ma_sqwat): the stand-up auto-advances to ma_wait at
    /// its end; the sidesteps loop. Travel() teleports to a state with no path, as it does for ma_runblend.</summary>
    private void SmsSetupSquatStates()
    {
        _smsSquatEndReady = false;
        if (animTree == null || animPlayer == null || animTree.TreeRoot is not AnimationNodeBlendTree tree || tree.GetNode("BaseSM") is not AnimationNodeStateMachine sm)
            return;
        if (animPlayer.HasAnimation("ma_sqend") && sm.HasNode("ma_wait"))
        {
            if (!sm.HasNode("ma_sqend"))
            {
                sm.AddNode("ma_sqend", new AnimationNodeAnimation { Animation = "ma_sqend" }, new Vector2(2000f, 500f));
                sm.AddTransition("ma_sqend", "ma_wait", new AnimationNodeStateMachineTransition
                {
                    AdvanceMode = AnimationNodeStateMachineTransition.AdvanceModeEnum.Auto,
                    SwitchMode = AnimationNodeStateMachineTransition.SwitchModeEnum.AtEnd,
                });
            }
            _smsSquatEndReady = true;
        }
        int y = 600;
        foreach (string c in new[] { "ma_swlkl", "ma_swlkr" })
        {
            if (!animPlayer.HasAnimation(c))
                continue;
            animPlayer.GetAnimation(c).LoopMode = Animation.LoopModeEnum.Linear; // setAnimation() every tick keeps them going
            if (!sm.HasNode(c))
                sm.AddNode(c, new AnimationNodeAnimation { Animation = c }, new Vector2(2000f, y));
            y += 100;
        }
        if (SmsDebugPrint)
            GD.Print($"[SMS squat] BaseSM states: ma_sqend {(_smsSquatEndReady ? "yes" : "NO")}, sidesteps {(sm.HasNode("ma_swlkl") && sm.HasNode("ma_swlkr") ? "yes" : "NO")}");
    }

    /// <summary>MarioHeadCtrl (MarioDraw.cpp 457): Rz(gun angle / 2) on jnt_head while the angle is negative -- the head looks up: 11.25
    /// deg with the turbo out, up to 35 deg at the spray squat's pull-back. An SmsBoneRotZ on Mario's skeleton, first in the modifier
    /// order like the swim pump.</summary>
    private void SmsSetupHeadGunRot()
    {
        if (skeleton == null || skeleton.FindBone("jnt_head") < 0)
            return;
        _smsHeadGunRot = new SmsBoneRotZ { Name = "SmsHeadGunAngle", BoneNames = new[] { "jnt_head" }, Angles = new float[1] };
        skeleton.AddChild(_smsHeadGunRot);
        skeleton.MoveChild(_smsHeadGunRot, 0);
    }

    /// <summary>calcGunAngle() (WaterGun.cpp 216) for this tick. In MARIO_STATUS_SQUAT the target is the angle itself plus the stick's
    /// vertical x RButtonMult (10000: any push pins the target at a limit and the chase does the moving; a resting stick holds the
    /// aim); elsewhere -LAngleBase. Clamped [LAngleMin, LAngleMax], chased at LAngleChase. Above 0 the chest bends forward by the
    /// angle (the spray goes down, to 44 deg); below 0 only the head looks up. The L camera's branch (the aim = the camera pitch) is
    /// the Y cam pass.</summary>
    private void SmsFluddCalcGunAngle(SmsParams.Fludd.Nozzle np)
    {
        if (SmsYCamOn)
        {
            // calcGunAngle()'s first branch: in the L camera the angle IS the camera pitch (the rig's mCurrentTarget.mPitch) -- no clamp, no chase
            _fluddGunAngle = YCamPitchBam;
            return;
        }
        float target = UseSmsPhysics && stateOfMario == MarioState.crouch && _smsSquatEndTicks == 0
            ? _fluddGunAngle + _smsStickV * np.RButtonMult
            : -np.LAngleBase;
        target = Mathf.Clamp(target, np.LAngleMin, np.LAngleMax);
        _fluddGunAngle += (target - _fluddGunAngle) * np.LAngleChase;
    }

    /// <summary>Where the turbo's jet leaves right now: its pitch from level and its heading against the face (-1 = straight back).</summary>
    private string SmsFluddJetDbg()
    {
        if (!SmsFluddMuzzle(0, out _, out Vector3 d))
            return "no muzzle";
        Vector3 face = _smsFaceValid ? SmsMath.DirFromYaw(_smsFaceYaw) : SmsFacingOrVelocityDir();
        Vector3 flat = new Vector3(d.X, 0f, d.Z);
        float along = flat.LengthSquared() > 1e-6f ? flat.Normalized().Dot(face) : 0f;
        return $"{Mathf.RadToDeg(Mathf.Asin(Mathf.Clamp(d.Y, -1f, 1f))):+0.0} deg from level, {along:F2} along the face (neck {_fluddGunAngle:F0} BAM)";
    }

    private void SmsFluddDashOff(string why)
    {
        _fluddDashing = false;
        if (SmsDebugPrint)
            GD.Print($"[SMS turbo] dash off ({why}), water {_fluddWater}");
    }

    /// <summary>mIntendedMag = mDashSpeed, and a stick at rest aims where he faces: the dash replaces the stick for everything
    /// downstream (the run's acceleration, its state, the swim's paddle).</summary>
    private void SmsFluddDashOverride(ref Vector3 inputDirWorld, ref float stickStrength)
    {
        if (!_fluddReady || _fluddDashSpeed <= 0f)
            return;
        float strength = Mathf.Clamp(_fluddDashSpeed / 32f, 0f, 1f);
        Vector3 dir;
        if (inputDirWorld.LengthSquared() > 1e-6f)
            dir = new Vector3(inputDirWorld.X, 0f, inputDirWorld.Z).Normalized();
        else
        {
            // mIntendedYaw = mFaceAngle.y: a resting stick aims where he LOOKS -- the armature's yaw this frame, whatever last turned
            // it (the SMS run, an air steer, a legacy pivot or landing turn), not a cached face. Latched as the face, and as the
            // legacy facing SmsGroundTick re-latches from while he stands, so the walk that follows keeps the line: the cached
            // face and the model's look could differ after a turn, and the run's first ticks then swung him round (the stutter).
            dir = SmsModelFacing();
            if (!_smsFaceValid || SmsMath.DirFromYaw(_smsFaceYaw).Dot(dir) < 0.9999f)
                SmsLatchFace(dir, 1);
            lastFacingDirection = dir;
        }
        inputDirWorld = dir * strength;
        stickStrength = strength;
        walkingStrength = strength;
        _smsIntendedMag = _fluddDashSpeed;
    }

    /// <summary>running(): FLUDD_EMITTING, A, fwd > DashMax - 1 -> changePlayerJumping(BROAD_JUMP): vy 70, fwd 60 (jump.prm shipped;
    /// the code defaults 30 / 80 are not the game), ANIM_BROAD_JUMP, lands into RUN (ours: the usual landing window).</summary>
    private void SmsFluddBroadJump(string why)
    {
        _fluddBroadJump = true;
        isJumping = true;
        initalJumpHold = true;
        jumpHoldTime = 0f;
        jumpBuffer = 0;
        landingEnteredThisContact = false;
        StopWaistIKHard();
        _jumpChainStartDir = GetMoveDirOrFallback();
        stateOfMario = MarioState.singleJump;
        SmsLaunch(SmsAir.Launch.BroadJump);
        SetMarioState(MarioState.singleJump); // ma_broad_jump while _fluddBroadJump
        if (SmsDebugPrint)
            GD.Print($"[SMS turbo] broad jump ({why}): vy {SmsParams.Jump.BroadJumpForceY:F0}, fwd {SmsParams.Jump.BroadJumpForce:F0} ({SmsUnits.SpeedToMps(SmsParams.Jump.BroadJumpForce):F1} m/s)");
    }

    /// <summary>checkSwimJump() with FLUDD_EMITTING on the surface: mPosition.y = surface + 1, BROAD_JUMP.</summary>
    private void SmsFluddSurfJump(float surface)
    {
        Vector3 face = SmsMath.DirFromYaw(_smsFaceYaw);
        float mps = SmsUnits.SpeedToMps(_smsSwimFwd);
        GlobalPosition += Vector3.Up * (surface + SmsUnits.UnitsToMetres(1f) - SmsFeetY());
        velocity.X = face.X * mps;
        velocity.Z = face.Z * mps;
        velocity.Y = 0f;
        lastFacingDirection = face;
        _smsSwimAnim = "";
        animPlayer.SpeedScale = 1f;
        SmsFluddBroadJump("the surf, A near the surface");
    }

    /// <summary>The surf into a wall (swimming's jumpProcess case 2 with the flag): on the surface JUMP_BACK_DOWN with fwd x -0.8
    /// and vy 50 -- he is thrown back out of the water; under water SWIM_P_DAMAGE.</summary>
    private void SmsFluddSurfWall(Vector3 wallNormalXZ)
    {
        if (SmsIsUnderWater())
        {
            SmsSwimSet(SmsSwim.PDamage); // the port's rule zeroes fwd in P_DAMAGE
            SmsFluddDashOff("the surf hit a wall under water");
            return;
        }
        float fwd = _smsSwimFwd;
        Vector3 face = SmsMath.DirFromYaw(_smsFaceYaw);
        _smsSwimAnim = "";
        animPlayer.SpeedScale = 1f;
        SmsFluddDashOff("the surf hit a wall");
        SmsEnterBonk(-face, SmsUnits.SpeedToMps(50f), "the surf into a wall", fwd); // JUMP_BACK_DOWN, vy 50
        float back = SmsUnits.SpeedToMps(0.8f * fwd); // mForwardVel = 0.8 x -fwd: 64 backwards, not the knockdown's 16
        velocity.X = -face.X * back;
        velocity.Z = -face.Z * back;
    }

    /// <summary>doRunningAnimation(): ANIM_TURBO_DASH at fwd >= DashMax - 1, ANIM_RUN2 again below it. The clip is not a tree state
    /// in the scene: one is added to BaseSM at start-up and travelled to (no path: a teleport).</summary>
    private void SmsFluddDashAnim(float fwd)
    {
        bool want = _fluddDashing && fwd >= SmsParams.Mario.DashMax - 1f && _fluddTurboAnimReady && _sm != null && animTree != null && animTree.Active;
        if (want)
        {
            if ((string)_sm.GetCurrentNode() != "ma_turbo_dash")
                _sm.Travel("ma_turbo_dash");
            _fluddDashAnimOn = true;
        }
        else if (_fluddDashAnimOn)
        {
            _fluddDashAnimOn = false;
            SetMarioState(stateOfMario); // ma_run2 (or whatever the state plays)
        }
    }

    // ---------------------------------------------------------------------------------------------------------------- the hands
    /// <summary>gMarioAnimeData's hand column (MarioDraw.cpp 39..375, unk5) for every clip that is not the body's own hands. TMario::setAnimation
    /// calls changeHand(hand) on a clip change (MarioDraw.cpp 1068) and changeHand (907) flags three hand meshes; the flag it sets is J3D's
    /// SKIP bit (J3DJoint::entryIn draws a shape whose bit is CLEAR -- the decomp's J3DShpFlag_Visible name is inverted), so hand 0 shows the
    /// body's shapes 5 / 6 (M_hand1_L / R: the OPEN hands -- wait, walk, the soft step, the landings, the double jump, the wall jump), hand 1
    /// ma_hnd2l / r (the GRIP: hanging, ladders, fences, holding and throwing, the squat, the turn, jmped, the slow RUN1), hand 2 ma_hnd3l / r
    /// (the FIST: the hip drop's hipsr / hipat / hiped, the single and triple jumps, RUN2 -- doRunningAnimation sets RUN2 for every run above
    /// the soft step with RUN1 only blended in, so a run's hands are fists -- the rolls, the kicks, the steps, the turbo dash); ma_hnd4r is
    /// never shown. His scene's RightHandClosed / LeftHandClosed are ma_hnd3 (Closed = 2), RightHandSlightyOpen / LeftHandSlightyOpen ma_hnd2
    /// (SlightlyOpen = 1); the body mesh's hand surfaces are hand 0 (Open). Rows the game gives two hands (land 0x56 / 0xD6: 0 / 1;
    /// jump_rolling 0xC1 / 0xF7: 2 / 0; ride_shell: 0 / 1) take the first. His own states (ma_pivot, ma_sit, ma_sleep_*, ma_tree_stand,
    /// ma_carry_p) are not the game's: hand 0 unless he carries.</summary>
    private static readonly System.Collections.Generic.Dictionary<string, int> SmsHandTable = new()
    {
        ["ma_hgup"] = 1, ["ma_tree_climb"] = 1, ["ma_tree_catch"] = 1, ["ma_tree_wait"] = 1, ["ma_hgdwn"] = 1, ["ma_hang"] = 1,
        ["ma_hgjmp"] = 1, ["ma_ladder_hang_catch"] = 1, ["ma_run1"] = 1, ["ma_jmped"] = 1, ["ma_ladder_hang_move_l"] = 1, ["ma_ladder_hang_move_r"] = 1,
        ["ma_throw"] = 1, ["ma_raise"] = 1, ["ma_put"] = 1, ["ma_slped"] = 1, ["ma_slpla"] = 1, ["ma_slip"] = 1,
        ["ma_sqend"] = 1, ["ma_sqsta"] = 1, ["ma_sqwat"] = 1, ["ma_turn"] = 1, ["ma_trned"] = 1, ["ma_ladder_hang_wait_l"] = 1,
        ["ma_ladder_hang_wait_r"] = 1, ["ma_hmov_l"] = 1, ["ma_hmov_r"] = 1, ["ma_rope_hmovr"] = 1, ["ma_rope_hmovl"] = 1, ["ma_door_kick"] = 1,
        ["ma_hold"] = 1, ["ma_hold_wait"] = 1, ["ma_hold_back"] = 1, ["ma_hold_move_r"] = 1, ["ma_hold_move_l"] = 1, ["ma_hold_drag"] = 1,
        ["ma_hold_to_hang"] = 1, ["ma_hold_hang"] = 1, ["ma_hang_to_hold"] = 1, ["ma_hold_return"] = 1, ["ma_fence_catch"] = 1, ["ma_fence_jcatch"] = 1,
        ["ma_fence_wait"] = 1, ["ma_fence_move_l"] = 1, ["ma_fence_move_r"] = 1, ["ma_fence_move_up"] = 1, ["ma_fence_move_down"] = 1, ["ma_fence_punch"] = 1,
        ["ma_ladder_hang_kick"] = 1, ["ma_ladder_roll_up"] = 1, ["ma_ladder_roll_down"] = 1,
        ["ma_hiped"] = 2, ["ma_hipsr"] = 2, ["ma_hipat"] = 2, ["ma_jump"] = 2, ["ma_roll"] = 2, ["ma_run2"] = 2,
        ["ma_tjmp2"] = 2, ["ma_tjmp1"] = 2, ["ma_jump_rolling"] = 2, ["ma_step1"] = 2, ["ma_step2"] = 2, ["ma_step3"] = 2,
        ["ma_jkick"] = 2, ["ma_dgrun"] = 2, ["ma_turbo_dash"] = 2, ["ma_giant_rolling"] = 2, ["ma_monteman_wait"] = 2, ["ma_demo_gate_out_appear_get"] = 2
    };

    private static readonly System.Text.RegularExpressions.Regex SmsClipSuffix = new(@" \d+$");

    /// <summary>The clip he is showing: BaseSM's state while the tree runs (his duplicate states -- "ma_tjmp1 2" -- folded onto their clip),
    /// the AnimationPlayer's clip while the tree is off.</summary>
    private string SmsCurrentClip()
    {
        string clip = animTree != null && animTree.Active && _sm != null ? (string)_sm.GetCurrentNode() : animPlayer?.CurrentAnimation ?? "";
        return SmsClipSuffix.Replace(clip, "");
    }

    /// <summary>changeHand for the clip of the moment: the table's hand; a carried object the grip (hold_*: the carry blend rides the base
    /// clip here); the run blend RUN2's fist (doRunningAnimation: setAnimation(ANIM_RUN2, rate), RUN1 is the blend partner).</summary>
    private HandPose SmsHandPose()
    {
        if (_smsHandCap) return HandPose.WithHat;   // 121/122: the return pose, the cap in the right hand (TMario::calcAnim: hnd4r while the frame < 158)
        string clip = SmsCurrentClip();
        int hand;
        if (heldBody != null)
            hand = 1;
        else if (!SmsHandTable.TryGetValue(clip, out hand))
            hand = clip == "ma_runblend" ? 2 : 0;
        return hand == 2 ? HandPose.Closed : hand == 1 ? HandPose.SlightlyOpen : HandPose.Open;
    }

    /// <summary>ma_hipsr (the hip drop's start) is in the library but not in BaseSM: added as a state (Travel with no path = a teleport),
    /// so the start plays with the tree ON and the upper body -- the pump / carry blend -- stays live through the 60-tick hover, as the
    /// game's hipsr allows (gMarioAnimeData 0x3C: upper 0x44). The tree resource is only changed in memory. Without it the legacy
    /// AnimationPlayer path is used.</summary>
    private void SmsSetupHipsrState()
    {
        if (!UseSmsPhysics || animTree == null || animTree.TreeRoot is not AnimationNodeBlendTree tree || tree.GetNode("BaseSM") is not AnimationNodeStateMachine sm)
            return;
        if (!sm.HasNode("ma_hipsr") && animPlayer.HasAnimation("ma_hipsr"))
            sm.AddNode("ma_hipsr", new AnimationNodeAnimation { Animation = "ma_hipsr" }, new Vector2(2000f, -120f));
        _smsHipsrInTree = sm.HasNode("ma_hipsr");
        if (SmsDebugPrint)
            GD.Print($"[SMS gp] ma_hipsr {(_smsHipsrInTree ? "in BaseSM: the hip drop's start plays through the tree" : "MISSING from the library: the start plays on the AnimationPlayer")}");
    }

    /// <summary>ma_turbo_dash and ma_broad_jump are in the library but not in BaseSM: add them as states (travel / start teleport
    /// to them). The tree resource is only changed in memory.</summary>
    private void SmsFluddSetupTurboAnims()
    {
        if (animTree == null || animTree.TreeRoot is not AnimationNodeBlendTree tree || tree.GetNode("BaseSM") is not AnimationNodeStateMachine sm)
        {
            if (SmsDebugPrint) GD.Print("[SMS fludd] no BaseSM state machine: the turbo dash / broad jump clips will not play");
            return;
        }
        Vector2 at = new Vector2(2000f, 0f);
        foreach (string clip in new[] { "ma_turbo_dash", "ma_broad_jump" })
        {
            if (!animPlayer.HasAnimation(clip) || sm.HasNode(clip))
                continue;
            sm.AddNode(clip, new AnimationNodeAnimation { Animation = clip }, at);
            at += new Vector2(0f, 120f);
        }
        if (animPlayer.HasAnimation("ma_turbo_dash"))
            ForceLoop("ma_turbo_dash");
        _fluddTurboAnimReady = sm.HasNode("ma_turbo_dash");
        if (SmsDebugPrint)
            GD.Print($"[SMS fludd] turbo clips: ma_turbo_dash {(sm.HasNode("ma_turbo_dash") ? "in BaseSM" : "MISSING")}, ma_broad_jump {(sm.HasNode("ma_broad_jump") ? "in BaseSM" : "MISSING")}");
    }

    // ---------------------------------------------------------------------------------------------------------------
    // The waist lean: considerWaist() (MarioDraw.cpp 1461) chased every tick, MarioWaistCtrl (470) applied on jnt_chest while the
    // body animation is RUN1 / RUN2. Replaces the SkeletonIK3D lean under SMS physics.
    // ---------------------------------------------------------------------------------------------------------------

    /// <summary>considerWaist() for one game frame (a tick): the pitch target WaistPitch x fwd and the roll target WaistRoll x
    /// (the frame's yaw change, BAM) x fwd, each clamped and chased at the set's rate. The pitch takes the water-gun set while the
    /// upper body pumps or holds the pump (fabricatedIsPumping) or he carries something (isHolding); the roll only while pumping.</summary>
    private void SmsWaistTick(float fwd, float dYawBam)
    {
        bool pumping = SmsPumpingStyle();
        bool holding = heldBody != null;
        float pitchTarget, pitchMax, pitchRate;
        if (pumping || holding)
        {
            pitchTarget = SmsParams.Waist.GunPitch * fwd; pitchMax = SmsParams.Waist.GunPitchMax; pitchRate = SmsParams.Waist.GunRate;
        }
        else
        {
            pitchTarget = SmsParams.Waist.FreePitch * fwd; pitchMax = SmsParams.Waist.FreePitchMax; pitchRate = SmsParams.Waist.FreeRate;
        }
        pitchTarget = Mathf.Clamp(pitchTarget, -pitchMax, pitchMax);
        _smsWaistPitch += pitchRate * (pitchTarget - _smsWaistPitch);

        float rollTarget, rollMax, rollRate;
        if (pumping)
        {
            rollTarget = SmsParams.Waist.GunRoll * dYawBam * fwd; rollMax = SmsParams.Waist.GunRollMax; rollRate = SmsParams.Waist.GunRate;
        }
        else
        {
            rollTarget = SmsParams.Waist.FreeRoll * dYawBam * fwd; rollMax = SmsParams.Waist.FreeRollMax; rollRate = SmsParams.Waist.FreeRate;
        }
        rollTarget = Mathf.Clamp(rollTarget, -rollMax, rollMax);
        _smsWaistRoll += rollRate * (rollTarget - _smsWaistRoll);
    }

    /// <summary>One physics frame of considerWaist(): as many ticks as the frame holds (1/120 s each), with the frame's forward speed
    /// and the previous frame's yaw change split over them (unk9C: the face latched at the top of the frame).</summary>
    private void SmsWaistFrame(double delta)
    {
        if (!_smsWaistPrevYawValid)
        {
            _smsWaistPrevYaw = _smsFaceYaw;
            _smsWaistPrevYawValid = true;
        }
        float dYawBam = _smsFaceValid ? SmsMath.WrapAngle(_smsFaceYaw - _smsWaistPrevYaw) / SmsUnits.BamToRad : 0f;
        _smsWaistPrevYaw = _smsFaceYaw;
        _smsWaistDbgLastDYaw = dYawBam;
        int n = Math.Max(1, (int)Math.Round(delta * 120.0));
        _smsLevelTicks += n;
        _smsFrameTicks = n;
        _smsWaistDbgMaxDYaw = MathF.Max(_smsWaistDbgMaxDYaw, MathF.Abs(dYawBam) / n);
        float fwd = SmsUnits.MpsToSpeed(new Vector2(velocity.X, velocity.Z).Length()); // mForwardVel, in every status
        for (int i = 0; i < n; i++)
            SmsWaistTick(fwd, dYawBam / n);
        SmsWaistApply();
    }

    /// <summary>" (shoulders 12 deg into the turn)" / "away from" for the waist prints: the twist's sign against this frame's yaw change
    /// (a left turn is a positive yaw change; the game's roll has the same sign). Empty while he runs straight or the twist is small.</summary>
    private string SmsWaistTwistDbg()
    {
        float rollDeg = _smsWaistRoll * SmsUnits.BamToRad * 180f / Mathf.Pi;
        if (!_smsFaceValid || MathF.Abs(rollDeg) < 2f || MathF.Abs(_smsWaistDbgLastDYaw) < 1f)
            return "";
        bool into = MathF.Sign(rollDeg) == MathF.Sign(_smsWaistDbgLastDYaw);
        return $" (banks {MathF.Abs(rollDeg):0} deg {(into ? "into" : "AWAY from")} the turn)";
    }

    /// <summary>MarioWaistCtrl: the chest turned by the lean only while the body animation is RUN1 / RUN2 -- the port's ma_run1 (walking,
    /// running) and ma_run2 (sprinting, the rollout run); not the dash (ma_turbo_dash), the sneak, the wait, any jump.</summary>
    /// <summary>What the rig showed at the last animation update: the chest bone's forward tilt (its local X is the spine), the
    /// shoulders' forward tilt (the lean lands on them), the head's look elevation and its yaw off the body's facing (jnt_head's
    /// local X is the face; the model faces +Z in the armature's frame).</summary>
    private string SmsPostureDbg()
    {
        if (skeleton == null || armature == null)
            return "";
        int head = skeleton.FindBone("jnt_head"), chest = skeleton.FindBone("jnt_chest"), sldr = skeleton.FindBone("jnt_sldr_L");
        if (head < 0 || chest < 0)
            return "";
        Basis skel = skeleton.GlobalTransform.Basis;
        Vector3 bodyFwd = -armature.GlobalTransform.Basis.Z.Normalized(); // the model faces the armature's -Z (pass 54)
        Vector3 headFwd = (skel * skeleton.GetBoneGlobalPose(head).Basis.X).Normalized();
        Vector3 chestUp = (skel * skeleton.GetBoneGlobalPose(chest).Basis.X).Normalized();
        float chestTilt = Mathf.RadToDeg(Mathf.Atan2(chestUp.Dot(bodyFwd), chestUp.Y));
        string sh = "";
        if (sldr >= 0)
        {
            // the shoulder joint's offset from the chest joint, tilted from vertical toward the front
            Vector3 d = skel * (skeleton.GetBoneGlobalPose(sldr).Origin - skeleton.GetBoneGlobalPose(chest).Origin);
            sh = $", shoulders {Mathf.RadToDeg(Mathf.Atan2(d.Dot(bodyFwd), d.Y)):+0;-0} deg forward";
        }
        float headElev = Mathf.RadToDeg(Mathf.Asin(Mathf.Clamp(headFwd.Y, -1f, 1f)));
        Vector3 hf = new Vector3(headFwd.X, 0f, headFwd.Z);
        float headYaw = hf.LengthSquared() > 1e-6f ? Mathf.RadToDeg(Mathf.Atan2(bodyFwd.Cross(hf.Normalized()).Y, bodyFwd.Dot(hf.Normalized()))) : 0f;
        return $"; posture: chest {chestTilt:+0;-0} deg forward{sh}, head looking {headElev:+0;-0} deg ({headYaw:+0;-0} deg off the face, + = his left)";
    }

    /// <summary>gMarioAnimeData bit 2 by clip name: the matrix effects are off for hanging, climbing, ladders, ropes, fences, the squat,
    /// doors and demos; on for everything else (run1, run2, wait, jump, land, sstep, turbo_dash, turn, the swim clips ...).</summary>
    private static bool SmsAnimeHasMtxEffect(string clip)
    {
        if (string.IsNullOrEmpty(clip))
            return false;
        foreach (string off in new[] { "ma_hg", "ma_hang", "ma_tree", "ma_ladder", "ma_door", "ma_sq", "ma_demo", "ma_hmov", "ma_rope", "ma_spin_p", "ma_fence" })
            if (clip.StartsWith(off))
                return false;
        return true;
    }

    /// <summary>gMarioAnimeData bit 4 by clip name: the handle swing is off only for the squat, the rope, the spin and the shine demo.</summary>
    private static bool SmsAnimeHasHandleSwing(string clip)
    {
        if (string.IsNullOrEmpty(clip))
            return false;
        foreach (string off in new[] { "ma_sq", "ma_demo", "ma_rope", "ma_spin_p" })
            if (clip.StartsWith(off))
                return false;
        return true;
    }

    /// <summary>The water gun's TMultiMtxEffect (WaterGun.cpp 1283). Entry 1, SWING_RZ on jnt_G_handle, is the grips' pendulum. Entry 0,
    /// TIME_LAG on the tank root, is never enabled in the game (only entry 1's flag is ever set, MarioDraw.cpp 1801 / 1827 / 1830) and is
    /// not ported. The pendulum's parameters are TMtxSwingRZ's compiled-in defaults: see SmsParams.MtxEffect.</summary>
    private void SmsFluddSetupHandleSwing()
    {
        if (_fluddTankSkel == null || _fluddTankSkel.FindBone("jnt_G_handle") < 0)
        {
            GD.PushWarning("[SMS fludd] the tank has no jnt_G_handle bone: no handle swing");
            return;
        }
        // the scene's node (Fludd.tscn: Tank/Node/Skeleton3D/HandleSwing, its exports the tuning); no stand-in (pass 37)
        var fluddRoot = SmsFluddModel.FindChild<SmsFludd>(_fluddAttach);
        _fluddHandleSwing = fluddRoot?.HandleSwing ?? SmsFluddModel.FindChild<SmsSwingRZ>(_fluddTankSkel);
        if (_fluddHandleSwing == null)
        {
            GD.PushError("[SMS fludd] Fludd.tscn has no HandleSwing (SmsSwingRZ under the tank's Skeleton3D): the grips do not swing -- add the node to the scene (AccUnits / LUnits / Brake are its exports)");
            return;
        }
        _fluddHandleSwing.UnitsPerMetre = SmsUnits.UnitsPerMetre;
        if (SmsDebugPrint)
            GD.Print($"[SMS jiggle] FLUDD handle swing (TMtxSwingRZ, from the scene) on {_fluddHandleSwing.BoneName} -> {string.Join(", ", System.Array.ConvertAll(_fluddTankSkel.GetBoneChildren(_fluddTankSkel.FindBone("jnt_G_handle")), b => _fluddTankSkel.GetBoneName(b)))}: rope {_fluddHandleSwing.LUnits} u, acc {_fluddHandleSwing.AccUnits}, brake {_fluddHandleSwing.Brake} (retail runs the compiled-in defaults acc 0 / brake 0.9 -- no MtxEffect7.prm ships; (0, -4, 0) / 0.7 are the disc's MtxEffect10 / 12, a logged deviation); the tank root's time lag is never enabled in the game and is not ported");
    }

    /// <summary>The game blends RUN1 (the walk cycle) and RUN2 (the run) continuously by the run's rate (doRunningAnimation:
    /// mMotionBlendRatio = 1 - (rate - MotBlendWalkSp) / (MotBlendRunSp - MotBlendWalkSp)), both clips at the same frame. Godot's
    /// state machine has one clip per state, so the pair goes in as one state: a blend tree of the two AnimationNodeAnimations into
    /// a Blend2 (0 = ma_run1, 1 = ma_run2), driven through SMS_RUN_MIX_PATH. Both clips are 60 frames, as the BCKs.</summary>
    private void SmsSetupRunBlend()
    {
        _smsRunBlendReady = false;
        if (animTree == null || animTree.TreeRoot is not AnimationNodeBlendTree tree || tree.GetNode("BaseSM") is not AnimationNodeStateMachine sm)
            return;
        if (!animPlayer.HasAnimation("ma_run1") || !animPlayer.HasAnimation("ma_run2"))
            return;
        if (!sm.HasNode("ma_runblend"))
        {
            var bt = new AnimationNodeBlendTree();
            bt.AddNode("walk", new AnimationNodeAnimation { Animation = "ma_run1" }, new Vector2(0f, 0f));
            bt.AddNode("run", new AnimationNodeAnimation { Animation = "ma_run2" }, new Vector2(0f, 160f));
            bt.AddNode("mix", new AnimationNodeBlend2(), new Vector2(320f, 80f));
            bt.ConnectNode("mix", 0, "walk");
            bt.ConnectNode("mix", 1, "run");
            bt.ConnectNode("output", 0, "mix");
            sm.AddNode("ma_runblend", bt, new Vector2(2000f, 300f));
        }
        animTree.Set(SMS_RUN_MIX_PATH, 0.5f);
        Variant back = animTree.Get(SMS_RUN_MIX_PATH);
        _smsRunBlendReady = back.VariantType == Variant.Type.Float && Mathf.IsEqualApprox((float)back, 0.5f);
        if (_smsRunBlendReady)
            animTree.Set(SMS_RUN_MIX_PATH, 1f);
        if (SmsDebugPrint)
            GD.Print(_smsRunBlendReady
                ? $"[SMS run] ma_runblend in BaseSM: ma_run1 x ma_run2 by the rate (walk below rate {SmsParams.Run.MotBlendWalkSp}, run above {SmsParams.Run.MotBlendRunSp}); rate = {SmsParams.Run.RunAnmSpeedMult} x min(intended, fwd) + {SmsParams.Run.RunAnmSpeedBase} (60 fps clips: Godot speed = the game's rate); SSTEP below {SmsParams.Run.Walk2Soft}, back above {SmsParams.Run.Soft2Walk}, at {SmsParams.Run.SoftStepAnmMult} x sp"
                : $"[SMS run] ma_runblend NOT wired ({SMS_RUN_MIX_PATH} did not read back): the stick picks ma_run1 / ma_run2 as before");
    }

    /// <summary>doRunningAnimation() (MarioRun.cpp 116) for this frame: sp = min(mIntendedMag, mForwardVel), never below 4. At the dash
    /// (mForwardVel >= DashMax - 1) TURBO_DASH at rate sp x RunAnmSpeedMult + RunAnmSpeedBase; below Walk2Soft SSTEP at max(sp, 0.1)
    /// x SoftStepAnmMult (back to the run above Soft2Walk); else RUN2 at that rate -- scaled in water by (1 - depth / SwimDepth x
    /// (1 - InWaterBrake)) x InWaterAnmBrake -- blended with RUN1 by (rate - MotBlendWalkSp) / (MotBlendRunSp - MotBlendWalkSp).
    /// setAnimation gives the frame control rate x 0.5 BCK frames a tick = 60 x rate frames a second, and the glb's clips are the
    /// BCKs at 60 fps, so the Godot time scale IS the game's rate.</summary>
    private void SmsRunAnimTick()
    {
        float fwd = SmsUnits.MpsToSpeed(new Vector2(velocity.X, velocity.Z).Length());
        float sp = MathF.Min(_smsIntendedMag, fwd);
        if (sp < 4f)
            sp = 4f;
        bool dash = _fluddDashAnimOn && _fluddTurboAnimReady;
        if (!dash)
        {
            // DELIBERATE DEVIATION (SmsParams.Fludd.ChargeSoftStep): the game tiptoes (SSTEP) while min(mDashSpeed, fwd) < Walk2Soft --
            // the first 26 ticks of a charge from a stand; Jaysonn wants "his forward walk" there, so the charge holds the run blend.
            _smsGaitBand = !SmsParams.Fludd.ChargeSoftStep && SmsTurboCharging() ? 1 : SmsRun.GaitBand(sp, _smsGaitBand);
        }
        float rate;
        if (dash)
        {
            // the game: sp = min(mIntendedMag, fwd) = mDashSpeed, capped at 32 -> 2.76, the run's tempo at 2.5x the ground speed.
            // DELIBERATE DEVIATION (SmsParams.Fludd.DashAnimByForwardVel): paced by mForwardVel, 80 -> 5.4
            rate = (SmsParams.Fludd.DashAnimByForwardVel ? fwd : sp) * SmsParams.Run.RunAnmSpeedMult + SmsParams.Run.RunAnmSpeedBase;
            _smsGaitClip = "ma_turbo_dash";
            _smsRunMix = 1f;
        }
        else if (_smsGaitBand == 0)
        {
            rate = MathF.Max(sp, 0.1f) * SmsParams.Run.SoftStepAnmMult;
            _smsGaitClip = "ma_sstep";
            _smsRunMix = 0f;
        }
        else
        {
            rate = sp * SmsParams.Run.RunAnmSpeedMult + SmsParams.Run.RunAnmSpeedBase;
            if (_smsInWater && IsOnFloor())
            {
                float depthRatio = Mathf.Clamp(SmsUnits.MetresToUnits(_smsWaterSurfaceY - SmsFeetY()) / SmsParams.Swim.SwimDepth, 0f, 1f);
                rate *= (1f - depthRatio * (1f - SmsParams.Swim.InWaterBrake)) * SmsParams.Swim.InWaterAnmBrake;
            }
            _smsGaitClip = "ma_runblend";
            _smsRunMix = Mathf.Clamp((rate - SmsParams.Run.MotBlendWalkSp) / (SmsParams.Run.MotBlendRunSp - SmsParams.Run.MotBlendWalkSp), 0f, 1f);
        }
        _smsRunRate = rate;
        if (animTree != null && animTree.Active)
        {
            animTree.Set(RUN_TIMESCALE_PATH, rate);
            animTree.Set(SMS_RUN_MIX_PATH, _smsRunMix);
        }
        else
            animPlayer.SpeedScale = rate;
    }

    /// <summary>The clip doRunningAnimation() picks now (SetMarioState's travel target for the gait states under SMS).</summary>
    private string SmsGaitClip()
    {
        SmsRunAnimTick();
        return _smsGaitClip;
    }

    private string SmsRunAnimDbg()
    {
        if (!UseSmsPhysics || !_smsRunBlendReady)
            return "";
        return $"; anim {_smsGaitClip} rate {_smsRunRate:0.00}{(_smsGaitClip == "ma_runblend" ? $" (run2 {_smsRunMix * 100f:0}%)" : "")}";
    }

    private string SmsTimeLagDbg()
    {
        if (_smsTimeLag == null || _smsTimeLag.Entries.Length < 3)
            return "";
        var c = _smsTimeLag.Entries[0]; var r = _smsTimeLag.Entries[1];
        string handles = _fluddHandleSwing == null ? "" : $", handles {(_fluddHandleSwing.Enabled ? "" : "(off) ")}{MathF.Abs(_fluddHandleSwing.DbgAngleDeg):0} deg {(_fluddHandleSwing.DbgAngleDeg >= 0f ? "back" : "forward")}";
        return $"; lag {(_smsTimeLag.Enabled ? "on" : "off")}: chest {c.DbgLagUnits:0.0} u / {c.DbgLagDeg:0.0} deg, arm {r.DbgLagDeg:0.0} deg{handles}";
    }

    private void SmsWaistApply()
    {
        if (_smsWaist == null)
            return;
        string node = animTree != null && animTree.Active && _sm != null ? (string)_sm.GetCurrentNode() : "";
        bool apply = node == "ma_run1" || node == "ma_run2" || node == "ma_runblend";
        // MarioWaistCtrl's first branch (MarioDraw.cpp 486): in the squat family (status bit 0x8000) a gun angle above 0 -- the R squat's
        // forward aim -- bends the whole upper body forward by that angle in place of the run lean (Rz on chn_chest: the spray, which
        // leaves forward over his head, goes down with it); a negative angle bends nothing (the head looks up instead)
        // MarioWaistCtrl's first branch (MarioDraw.cpp 476): the L camera looking down (its pitch above 0) bends the upper body forward
        // by the pitch, FLUDD or not (Rz(pitch) x Rx(-unk100), unk100 = 0; canBendBody() only fails in hurt statuses, which end the
        // mode)
        float aimBam = SmsYCamOn ? YCamPitchBam : _fluddGunAngle;
        bool squatAim = UseSmsPhysics && aimBam > 0f && (SmsYCamOn || (stateOfMario == MarioState.crouch && _fluddReady));
        if (squatAim)
            apply = true;
        _smsWaist.Apply = apply;
        _smsWaist.Pitch = (squatAim ? aimBam : _smsWaistPitch) * SmsUnits.BamToRad;
        // The game's sign, applied as the game does: a left turn is a positive yaw change, so a positive roll, and Rx(roll) about
        // jnt_chest's local X -- up the spine in the rig AND in ma_mdl1.bmd (JNT1: chn_chest (0, 90, 0), jnt_chest (0, 0, 90) -> X up,
        // Y forward, Z lateral) -- turns the chest counterclockwise seen from above: INTO the turn, the torso leading the feet.
        // 0e545b1 negated this after "he leans out": what he saw is the geometry, not the sign -- Rz(pitch) x Rx(roll) twists first
        // and pitches the twisted torso forward, so the shoulder that came forward (the outside one) dips by asin(sin p x sin r).
        // The flip turned his chest and head AWAY from the turn ("steering feels off", 2026-09-27). Reverted.
        // The game's sign. The callback sits on chn_chest (X = his back, Y up, Z his left), so Rx(roll) is a BANK about the front-back
        // axis: a positive roll (a left turn) tips the upper body toward Z, his left, into the turn. The 16ccd6d negation went with the
        // jnt_chest reading (where Rx was a spine twist and the geometry dropped the outside shoulder); it is gone.
        _smsWaist.Roll = squatAim ? 0f : _smsWaistRoll * SmsUnits.BamToRad;
        if (_smsTimeLag != null)
        {
            // TMario::addCallBack: the matrix effects write while gMarioAnimeData[anim].unk6 & 2 (the locomotion clips; off for hanging,
            // climbing, ladders, ropes, fences, the squat, doors, demos), the upper body is IDLE, and the level is 0x4B0 ticks old
            _smsTimeLag.Enabled = UseSmsPhysics && _fluddUpper == SmsUpper.Idle && _smsLevelTicks >= SmsParams.MtxEffect.EnableAfterTicks
                && SmsAnimeHasMtxEffect(node.Length > 0 ? node : (animPlayer != null ? animPlayer.CurrentAnimation : ""));
            // The game runs the callback on every move tick, in lockstep with the movement. Stepping it per RENDER frame against a
            // world target that only moves on PHYSICS frames popped the head and shoulders by the 5-unit clamp on every frame the two
            // did not line up (Jaysonn, 2026-09-28 00:28: "one spot then back to normal every other frame"). Step here, in the
            // physics frame, with this frame's tick count; the modifier pass only applies the stored bone-space offset.
            _smsTimeLag.Step(_smsFrameTicks);
        }
        if (_fluddHandleSwing != null)
        {
            // addCallBack's second block: the handle swing writes while gMarioAnimeData[anim].unk6 & 4 (everything but the squat, the
            // rope, the spin and the shine demo), the upper body is IDLE and he has the FLUDD -- no level-age wait for this one
            _fluddHandleSwing.Enabled = UseSmsPhysics && _fluddReady && _fluddUpper == SmsUpper.Idle
                && SmsAnimeHasHandleSwing(node.Length > 0 ? node : (animPlayer != null ? animPlayer.CurrentAnimation : ""));
            _fluddHandleSwing.Step(_smsFrameTicks); // as the time lag: stepped here, applied in the modifier pass
        }
        if (SmsDebugPrint)
        {
            if (apply != _smsWaistDbgOn)
            {
                _smsWaistDbgOn = apply;
                _smsWaistDbgTicks = 0;
                GD.Print($"[SMS waist] {(apply ? "on" : "off")} ({(node.Length > 0 ? node : "no tree node")}): pitch {_smsWaistPitch * SmsUnits.BamToRad * 180f / Mathf.Pi:+0.0;-0.0} deg, roll {_smsWaistRoll * SmsUnits.BamToRad * 180f / Mathf.Pi:+0.0;-0.0} deg{SmsWaistTwistDbg()}, {(SmsPumpingStyle() ? "the water-gun set" : "the free set")}{SmsPostureDbg()}");
            }
            else if (apply && ++_smsWaistDbgTicks >= 60)
            {
                _smsWaistDbgTicks = 0;
                float camYaw = springArmPivot != null ? springArmPivot.Rotation.Y : 0f;
                float camDrift = _smsWaistDbgCamValid ? Mathf.RadToDeg(SmsMath.WrapAngle(camYaw - _smsWaistDbgCamYaw)) : 0f;
                _smsWaistDbgCamYaw = camYaw; _smsWaistDbgCamValid = true;
                GD.Print($"[SMS waist] pitch {_smsWaistPitch * SmsUnits.BamToRad * 180f / Mathf.Pi:+0.0;-0.0} deg, roll {_smsWaistRoll * SmsUnits.BamToRad * 180f / Mathf.Pi:+0.0;-0.0} deg{SmsWaistTwistDbg()} at {SmsUnits.MpsToSpeed(new Vector2(velocity.X, velocity.Z).Length()):F1} u/tick ({(SmsPumpingStyle() ? "pumping" : "free")}); this second: yaw change up to {_smsWaistDbgMaxDYaw:F0} BAM a tick ({_smsWaistDbgMaxDYaw * SmsUnits.BamToRad * 180f / Mathf.Pi:F2} deg), camera yaw drift {camDrift:+0.0;-0.0} deg{SmsPostureDbg()}{SmsTimeLagDbg()}{SmsRunAnimDbg()}");
                _smsWaistDbgMaxDYaw = 0f;
            }
        }
    }

    private void SmsWaistSetup()
    {
        if (skeleton == null)
            return;
        _smsWaist = new SmsWaistLean { Name = "SmsWaistLean" };
        skeleton.AddChild(_smsWaist);
        // Ordered LAST at the end of _Ready (SmsWaistOrderLast): the legacy JiggleBones on jnt_head / jnt_sldr_L / jnt_sldr_R write
        // `rest position + shift` every frame, so a lean that ran before them kept only its rotation -- the head tilted in place
        // on an upright body ("his head is just leaning", 2026-09-27 04:05) while the game swings it 25 units forward about the hips.
        if (SmsDebugPrint && skeleton.FindBone("jnt_chest") >= 0)
        {
            // the game's roll is a twist about the chest's local X (up the spine in the BMD): report where the rig's X points.
            // NOTE: _Ready assigns the `armature` field AFTER this runs -- resolve the node here (63ebb3c read the field, threw a
            // NullReferenceException inside _Ready and skipped the rest of start-up: no animPlayer, no tree, no pack).
            Node3D arm = armature ?? GetNodeOrNull<Node3D>("Armature");
            Basis armInv = arm != null ? arm.GlobalTransform.Basis.Inverse() : Basis.Identity;
            Vector3 xw = (skeleton.GlobalTransform.Basis * skeleton.GetBoneGlobalRest(skeleton.FindBone("jnt_chest")).Basis.X).Normalized();
            Vector3 yw = (armInv * skeleton.GlobalTransform.Basis * skeleton.GetBoneGlobalRest(skeleton.FindBone("jnt_chest")).Basis.Y).Normalized();
            GD.Print($"[SMS waist] jnt_chest local Y in the armature's frame: ({yw.X:F2}, {yw.Y:F2}, {yw.Z:F2}) -> {(yw.Z > 0.5f ? "+Z = the model's FRONT (the rig keeps the BMD's axes: the head binds at z -3 behind the chest joint, the left foot at +x): a positive pitch tilts him FORWARD" : yw.Z < -0.5f ? "-Z = his BACK: a positive pitch would tilt him BACKWARD" : "SIDEWAYS?")}");
            GD.Print($"[SMS waist] jnt_chest local X in world: ({xw.X:F2}, {xw.Y:F2}, {xw.Z:F2}) -> {(xw.Y > 0.5f ? "UP: a positive roll turns the shoulders counterclockwise seen from above (to his left) -- the game's sign, into a left turn" : xw.Y < -0.5f ? "DOWN: a positive roll turns the shoulders clockwise seen from above (to his right)" : "NOT along the spine: the roll would not be a twist")}");
        }
        if (SmsDebugPrint)
            GD.Print("[SMS waist] head lock off under SMS: MarioHeadCtrl is the identity in a run; ma_run2's head track holds the head within 4 deg while the chest swings 35 deg a stride");
        if (SmsDebugPrint)
            GD.Print($"[SMS waist] MarioWaistCtrl sits on chn_chest (parent of jnt_chest: {(skeleton.FindBone("jnt_chest") >= 0 ? skeleton.GetBoneName(skeleton.GetBoneParent(skeleton.FindBone("jnt_chest"))) : "?")}): the whole upper body pitches forward by speed and BANKS into turns about the front-back axis; the shipped MtxEffect14/16/22 files and the pack's tilt formula put the decomp's chn/jnt names the other way round");
        // the scene's node (assets/Sms/BodyLag.tscn instanced under Armature/Skeleton3D: its Bones the MtxEffect14 / 16 / 22 fields,
        // editable); no stand-in (pass 37): without it the body has no time lag, and one error says so
        _smsTimeLag = SmsFluddModel.FindChild<SmsTimeLag>(skeleton);
        if (_smsTimeLag == null)
            GD.PushError("[SMS jiggle] Player.tscn has no BodyLag under Armature/Skeleton3D: no body time lag -- instance res://assets/Sms/BodyLag.tscn there");
        else
        {
            _smsTimeLag.UnitsPerMetre = SmsUnits.UnitsPerMetre;
            skeleton.MoveChild(_smsTimeLag, -1); // after SmsWaistLean: the game's chn_chest callback runs before the chest's
        }
        if (SmsDebugPrint && _smsTimeLag != null)
        {
            string bones = string.Join("; ", System.Array.ConvertAll(_smsTimeLag.Bones, b => b == null ? "?" : $"{b.BoneName} pos {b.PosAccel}/{b.PosBrake} limit {b.PosLimitUnits} u, quat {b.QuatAccel}/{b.QuatBrake}"));
            GD.Print($"[SMS jiggle] TMtxTimeLag (from the scene): {bones}; on after {SmsParams.MtxEffect.EnableAfterTicks} ticks, locomotion clips, upper body idle; the legacy head / arm JiggleBones are off under SMS");
        }
        if (SmsDebugPrint)
            GD.Print($"[SMS waist] considerWaist on jnt_chest {(skeleton.FindBone("jnt_chest") >= 0 ? "yes" : "NO")}: free {SmsParams.Waist.FreePitch} x fwd (cap {SmsParams.Waist.FreePitchMax}) / roll {SmsParams.Waist.FreeRoll} (cap {SmsParams.Waist.FreeRollMax}) at {SmsParams.Waist.FreeRate}; pumping {SmsParams.Waist.GunPitch} x fwd (cap {SmsParams.Waist.GunPitchMax}) / roll cap {SmsParams.Waist.GunRollMax} at {SmsParams.Waist.GunRate}; the waist IK is retired under SMS");
    }

    /// <summary>The game's callback is the last thing that touches jnt_chest's children before skinning; here the JiggleBones
    /// (jnt_head, jnt_sldr_L / R) run in the modifier stage too and overwrite those bones' positions with `rest + shift`, so the
    /// lean goes last and rotates whatever they left.</summary>
    private void SmsWaistOrderLast()
    {
        if (skeleton == null || _smsWaist == null)
            return;
        skeleton.MoveChild(_smsWaist, skeleton.GetChildCount() - 1);
        if (_smsTimeLag != null)
            skeleton.MoveChild(_smsTimeLag, skeleton.GetChildCount() - 1); // tree order: chn_chest's lean before jnt_chest's lag
        if (SmsDebugPrint)
        {
            var mods = new System.Collections.Generic.List<string>();
            foreach (Node c in skeleton.GetChildren())
                if (c is SkeletonModifier3D)
                    mods.Add(c.Name);
            GD.Print($"[SMS waist] skeleton modifier order: {string.Join(" -> ", mods)} (the lean last: the jiggles reset jnt_head / jnt_sldr positions to rest + shift)");
        }
    }

    private void SmsFluddOnRespawn()
    {
        if (!_fluddReady)
            return;
        _fluddWater = SmsFluddCurrent.AmountMax;
        _fluddTrigState = 0; _fluddTrigLeft = 0; _fluddTrigFill = 0f; _fluddTrigAccum = 0f;
        _fluddBombState = 0; _fluddBombLeft = 0; _fluddBombFill = 0f; _fluddBombAccum = 0f;
        _fluddSprayRamp = 0; _fluddSprayStrength = 0f; _fluddEmitAccum = 0f;
        _fluddDashSpeed = 0f; _fluddDashing = false; _fluddDashAnimOn = false; _fluddBroadJump = false;
        _smsWaistPitch = 0f; _smsWaistRoll = 0f; _smsWaistPrevYawValid = false;
        _smsTimeLag?.Reset();
        _fluddHandleSwing?.Reset();
        _fluddDrops?.Clear();
        SmsFluddPoseWater();
    }

    /// <summary>The port's death (ma_die, R respawns); the game's loserExec.</summary>
    /// <summary>mPosition for the effects bound to it (the true bottom of the capsule).</summary>
    public Vector3 SmsFeetWorld() => SmsFeet();

    /// <summary>TMario::checkActionThing3 (Mario.hpp 1214) as the director reads it before a pause (MarDirectorDirect.cpp 810): not in a
    /// jumping status; and the director must be in play -- not the Miss, a death, the shine demo or a talk.</summary>
    public bool SmsCanPause()
    {
        if (_smsGameOver || stateOfMario == MarioState.dead || stateOfMario == MarioState.shineGet || stateOfMario == MarioState.talking || _smsTalking)
            return false;
        if (TryGetAirProfile(stateOfMario, out _) || !IsOnFloor())
            return false; // MARIO_STATUS_FLAG_JUMPING
        return true;
    }

    /// <summary>
    /// The director's Miss state (MarDirectorDirect.cpp 798-822, 769-787, 408-430). The tick MARIO_FLAG_GAME_OVER is seen it goes
    /// GAME_OVER_PENDING; the next tick STATE_UNK7 begins: the lives flag (0x20001) down one, the console's TOO BAD! (startAppearMiss), the
    /// miss BGM, and the fader's request -- the death wipe (10, Hx_Test2) 2.2 s on, the iris (2) 2.0 s on for a hell death, or with no
    /// life left the game-over wipe (0xD) 2.0 s on. Once the fader is fully out and the BGM has ended (or 1200 of its frames have passed)
    /// the stage moves: lives left -> the miss flag (0x30002) and decideNextStageOfMiss + moveStage, the same stage from its start with no
    /// intro and a plain 0.4 s fade in (Level.cs); none left -> the save / title flow (GameOverScene; empty: this stage again, lives
    /// reset). Mario keeps flying his FIRE_DOWN or lying in his pose meanwhile, as in the game.
    /// </summary>
    private void SmsMissTick()
    {
        if (!_smsGameOver || _smsMissTicks == int.MinValue)
            return;
        if (_smsMissTicks < 0)
        {
            _smsMissTicks = 0; // DIRECTOR_FLAG_GAME_OVER_PENDING: acted on next tick
            return;
        }
        if (_smsMissTicks == 0)
        {
            _lives--; // TFlagManager::decFlag(0x20001, 1)
            if (GameData.Instance != null)
                GameData.Instance.Lives = _lives;
            _smsConsoleStr?.StartAppearMiss();
            if (MissJingle != null && MissJingle.Stream != null)
                MissJingle.Play();
            if (_smsFader != null)
            {
                if (_lives >= 0)
                    _smsFader.StartWipe(SmsFader.Wipe.Arcs, 2.2f); // startWipe(10, 0.0f, 2.2f): Hx_Test2 -- the four curved bands
                else
                    _smsFader.StartWipe(SmsFader.Wipe.FadeOut, 2.0f, 1.0f); // startWipe(0xD, 0.0f, 2.0f): Hx_GameOver draws a texture the port lacks -- a plain fade
            }
            if (SmsDebugPrint)
                GD.Print($"[SMS miss] TOO BAD! lives {_lives} ({(_lives >= 0 ? "the stage reloads after the wipe" : "game over")}), the wipe in {(_lives >= 0 ? 2.2f : 2.0f):F1} s");
            _smsMissTicks = 1;
            return;
        }
        _smsMissTicks++;
        bool faded = _smsFader != null ? _smsFader.IsFullyFadedOut : _smsMissTicks > 120 * 4; // no fader: four seconds
        bool bgmDone = MissJingle == null || !MissJingle.Playing || _smsMissTicks >= 1200 * 4; // MSBgm::getHandle(2) == 0 || 1200 frames
        if (!(faded && bgmDone))
            return;
        _smsMissTicks = int.MinValue;
        if (_lives >= 0)
        {
            if (GameData.Instance != null)
                GameData.Instance.CameFromMiss = true; // TFlagManager 0x30002: the next load is a miss's
            if (SmsDebugPrint)
                GD.Print("[SMS miss] moveStage: the stage from its start");
            GetTree().ReloadCurrentScene(); // decideNextStageOfMiss + moveStage
            return;
        }
        if (GameData.Instance != null)
            GameData.Instance.Lives = -1; // a new game's lives next time
        if (SmsDebugPrint)
            GD.Print($"[SMS miss] game over -> {(GameOverScene != "" ? GameOverScene : "this stage, lives reset")}");
        if (GameOverScene != "")
            GetTree().ChangeSceneToFile(GameOverScene);
        else
            GetTree().ReloadCurrentScene();
    }

    /// <summary>
    /// loserExec() (MarioCollision.cpp 202): MARIO_FLAG_GAME_OVER, HP 0, MARIO_STATUS_DOWN_LOSER. downLoser() (MarioAutodemo.cpp 148) drops
    /// him straight down in ANIM_LAND -- setPlayerVelocity(0) each tick, the fall keeps its vy -- until jumpProcess() lands, then LOSER_DOWN:
    /// loserDown() (MarioRun.cpp 1474), ANIM_DIE and the voice, the slide out at 0.9 a tick. On the ground the landing is immediate. The
    /// game's director fades the stage out two ticks after the flag; the port has no stage reload, so the pose holds until R.
    /// </summary>
    private void EnterDead()
    {
        _smsGameOver = true;
        stateOfMario = MarioState.dead;
        _smsDownAnim = "";
        SleepStatus(true); // Close eyes
        velocity = new Vector3(0f, velocity.Y, 0f); // downLoser(): setPlayerVelocity(0.0f)
        if (!IsOnFloor())
        {
            _smsLoserFalling = true;
            SmsDownPlay("ma_land", 1f); // setAnimation(ANIM_LAND, 1.0f) while he drops
            return;
        }
        SmsLoserDown();
    }

    /// <summary>LOSER_DOWN (loserDown(), MarioRun.cpp 1474): ANIM_DIE on the ground; the reaction voices are not ported.</summary>
    private void SmsLoserDown()
    {
        _smsLoserFalling = false;
        _smsGameOver = true;
        stateOfMario = MarioState.dead;
        velocity = Vector3.Zero;
        SleepStatus(true);
        if (animTree != null)
        {
            animPlayer.Stop(false);
            animTree.Active = true;
        }
        if (_sm != null)
            _sm.Travel("ma_die");
    }

    private void SmsDownEnter(bool airborne, float fwd)
    {
        _smsDownKind = SmsDownKind.Knockdown;
        _smsDownAir = airborne;
        _smsDownFwd = fwd;
        if (airborne)
        {
            SmsDownPlay(_smsDownFore ? "ma_jfdwn" : "ma_bkdwn", 1f); // jumpDownCommon(): vy left as it was, +-16 from the next tick
        }
        else
        {
            velocity.Y = 0f;
            SmsDownGroundAnim();
        }
        SmsDownApplyVelocity();
    }

    /// <summary>
    /// The ground knockdown clip for the type and direction, with downingCommon()'s frame limit as the fraction of the clip
    /// during which he still slides (the port's clips are 60 fps: bdwn 158 frames, sdwnf 58; the other four limits exceed
    /// their clips, so those slide to the end).
    /// </summary>
    private void SmsDownGroundAnim()
    {
        string anim;
        float limitFrames;
        switch (_smsDownType)
        {
            case 0: anim = _smsDownFore ? "ma_sffdn" : "ma_sfbdn"; limitFrames = _smsDownFore ? 100f : 200f; break; // safeForeDown / safeBackDown
            case 1: anim = _smsDownFore ? "ma_shfdn" : "ma_sdown"; limitFrames = _smsDownFore ? 80f : 88f; break;   // shortForeDown / shortBackDown
            default: anim = _smsDownFore ? "ma_sdwnf" : "ma_bdwn"; limitFrames = _smsDownFore ? 42f : 86f; break;   // foreDown / backDown
        }
        float frames = animPlayer.HasAnimation(anim) ? (float)animPlayer.GetAnimation(anim).Length * 60f : 60f;
        SmsDownPlay(anim, Mathf.Clamp(limitFrames / MathF.Max(frames, 1f), 0f, 1f));
        // every ground knockdown status emits PARTICLE_MS_DMG_C at mPosition on its first tick (backDown .. catchDown, MarioRun.cpp
        // 1399-1470) -- the second burst of a hit taken on the ground, the landing burst of an air knockdown; the rumble is not ported.
        // The hit variant (fewer, shorter: pass 36); the bonk's own landing (TickBonk) keeps the full burst
        SpawnHitStars(ComputeFeetPosition());
    }

    private void SmsDownPlay(string anim, float slideUntil)
    {
        _smsDownAnim = anim;
        _smsDownSlideUntil = slideUntil;
        if (animTree != null)
            animTree.Active = false; // driven directly, like the shimmy: SetMarioState(idle) at the end brings the tree back
        animPlayer.SpeedScale = 1f;
        if (animPlayer.HasAnimation(anim))
            animPlayer.Play(anim);
    }

    private void SmsDownApplyVelocity()
    {
        Vector3 face = SmsMath.DirFromYaw(_smsFaceYaw);
        float mps = SmsUnits.SpeedToMps(_smsDownFwd);
        velocity.X = face.X * mps;
        velocity.Z = face.Z * mps;
    }

    /// <summary>
    /// The knockdown, one physics frame. In the air (jumpDownCommon): +-16 along the face every tick, gravity, a wall
    /// mirrors the face (playerRefrection) and ANIM_BKDWN, the floor hands over to the ground status of the family. On the
    /// ground (downingCommon): the clip plays once; he slides at fwd *= 0.96 a tick until the clip's limit, then +-0.1; an
    /// edge drops him into JUMP_SHORT_*_DOWN by the sign of fwd; the clip's end is WAIT. No inputs in either.
    /// </summary>
    private void SmsTickHurt(double delta, Vector3 stickDir)
    {
        switch (_smsDownKind)
        {
            case SmsDownKind.Fire: SmsTickFireDown(delta, stickDir); return;
            case SmsDownKind.FireEnd: SmsTickFireEnd(stickDir); return;
            case SmsDownKind.Electric: SmsTickElectric(delta); return;
            case SmsDownKind.Thrown: SmsTickThrown(delta, stickDir); return;
            case SmsDownKind.ThrownEnd: SmsTickThrownEnd(stickDir); return;
        }
        if (_smsDownAir)
        {
            if (IsOnFloor() && velocity.Y <= 0.01f)
            {
                // jumpProcess() 1: landed. The ground status of the same family; the last +-16 decays from here.
                _smsDownAir = false;
                _smsDownFwd = _smsDownFore ? SMS_DOWN_AIR_SPEED : -SMS_DOWN_AIR_SPEED;
                velocity.Y = 0f;
                SmsDownGroundAnim();
                SmsDownApplyVelocity();
                if (SmsDebugPrint)
                    GD.Print($"[SMS damage] landed: {_smsDownAnim}, slides for {_smsDownSlideUntil * 100f:F0}% of it");
                return;
            }
            SmsHurtWallMirror(true); // jumpProcess() 2: playerRefrection(0) mirrors the face across the wall, vy <= 0, ANIM_BKDWN; the +-16 along the mirrored face carries him away from it
            SmsAirTick(delta, Vector3.Zero); // jumpProcess(0): gravity only (hurt does not steer), the true-vy handoff
            _smsDownFwd = _smsDownFore ? SMS_DOWN_AIR_SPEED : -SMS_DOWN_AIR_SPEED;
            SmsDownApplyVelocity();
            return;
        }

        if (!IsOnFloor())
        {
            // walkProcess() 0: off an edge -> JUMP_SHORT_FORE/BACK_DOWN by the sign of fwd (the type drops to SHORT)
            _smsDownAir = true;
            _smsDownType = Math.Min(_smsDownType, 1);
            _smsDownFore = _smsDownFwd >= 0f;
            SmsDownPlay(_smsDownFore ? "ma_jfdwn" : "ma_bkdwn", 1f);
            SmsAirTick(delta, Vector3.Zero);
            _smsDownFwd = _smsDownFore ? SMS_DOWN_AIR_SPEED : -SMS_DOWN_AIR_SPEED;
            SmsDownApplyVelocity();
            if (SmsDebugPrint)
                GD.Print("[SMS damage] off the edge while down: JUMP_SHORT_" + (_smsDownFore ? "FORE" : "BACK") + "_DOWN");
            return;
        }

        int n = SmsUnits.TicksFor(delta, ref _smsTickAccum);
        bool playing = animPlayer.IsPlaying() && animPlayer.CurrentAnimation == _smsDownAnim;
        float t = playing && animPlayer.CurrentAnimationLength > 0.0
            ? (float)(animPlayer.CurrentAnimationPosition / animPlayer.CurrentAnimationLength)
            : 1f;
        if (t < _smsDownSlideUntil)
        {
            // slopeProcess() adds 0 on normal ground; the slide decays 4% a tick and stops under 1 unit
            for (int i = 0; i < n; i++)
            {
                _smsDownFwd *= 0.96f;
                if (_smsDownFwd * _smsDownFwd < 1f)
                    _smsDownFwd = 0f;
            }
        }
        else
        {
            _smsDownFwd = _smsDownFwd >= 0f ? 0.1f : -0.1f;
        }
        velocity.Y = 0f;
        SmsDownApplyVelocity();
        if (!playing)
        {
            // isLast1AnimeFrame(): WAIT
            _smsDownAnim = "";
            SleepStatus(false); // eyes open again (and the sleep timers start fresh)
            stateOfMario = MarioState.idle;
            SetMarioState(MarioState.idle); // the tree comes back on here
            if (SmsDebugPrint)
                GD.Print("[SMS damage] up");
        }
    }

    /// <summary>jumpProcess() 2 while down: playerRefrection(0) mirrors the face across the wall he is moving into and kills a rising vy;
    /// the knockdown switches to ANIM_BKDWN (<paramref name="bkdwn"/>), the fire keeps ma_firejmp. True when a wall was hit.</summary>
    private bool SmsHurtWallMirror(bool bkdwn)
    {
        if (!IsOnWall())
            return false;
        Vector3 wallN = GetWallNormal();
        wallN.Y = 0f;
        if (wallN.LengthSquared() <= 1e-6f || new Vector3(velocity.X, 0f, velocity.Z).Dot(wallN) >= 0f)
            return false;
        wallN = wallN.Normalized();
        Vector3 face = SmsMath.DirFromYaw(_smsFaceYaw);
        Vector3 mirrored = (face - 2f * face.Dot(wallN) * wallN).Normalized();
        SmsLatchFace(mirrored, 1);
        lastFacingDirection = mirrored;
        armature.Rotation = new Vector3(0f, YawFromDir(mirrored), 0f);
        if (velocity.Y > 0f)
            velocity.Y = 0f;
        if (bkdwn && _smsDownAnim != "ma_bkdwn")
            SmsDownPlay("ma_bkdwn", 1f);
        if (SmsDebugPrint)
            GD.Print(bkdwn ? "[SMS damage] wall: face mirrored, ma_bkdwn" : "[SMS fire] wall: face mirrored (playerRefrection)");
        return true;
    }

    /// <summary>The knockdown's end (isLast1AnimeFrame -> WAIT) and the fire's / the shock's: eyes open, idle, the tree back on.</summary>
    private void SmsHurtStandUp(string message)
    {
        _smsDownAnim = "";
        _smsDownAir = false;
        _smsDownKind = SmsDownKind.Knockdown;
        SleepStatus(false); // eyes open again (and the sleep timers start fresh)
        stateOfMario = MarioState.idle;
        SetMarioState(MarioState.idle); // the tree comes back on here
        if (SmsDebugPrint)
            GD.Print(message);
    }

    // ---------------------------------------------------------------------------------------------------------------
    // Fire and electricity (pass 50): the pollution layer's hazards (checkGraffito, MarioMove.cpp 953 -- the game's goop map, sampled at
    // the floor point under him every tick) and the statuses they put him in. The effects are scenes under Mario (pass 51): the burn's
    // cloud (particle 6, ms_firedmg_a: Fx/FireDamage.tscn), the shock's sparks every tick (ms_m_biri_a / b / c: Fx/ShockSparks.tscn) and
    // its closing puff (ms_moe_fire_off: Fx/ShockPuff.tscn). Not ported: the model's tremble (TTrembleModelEffect: every vertex kicked
    // +-5 units and springing back, 600 frames), the shock's second draw pass (drawLogic, the blue shimmer), the voices, the rumbles.
    // ---------------------------------------------------------------------------------------------------------------

    /// <summary>
    /// checkGraffito(): the pollution under his feet, once a tick after the move. The game samples its goop map at the floor point
    /// (five points 32 units apart for the fire, the centre for the electricity) and calls the hazard when every sample is polluted;
    /// the port's tagged floor body is polluted all over, so the body under the feet is the sample (none in the air). MARIO_FLAG_DIRTY
    /// is set after the dispatch, so the electric grace reads the previous tick's flag, as in the game.
    /// </summary>
    private void SmsCheckGraffito()
    {
        int n = SmsUnits.TicksFor(GetPhysicsProcessDeltaTime(), ref _smsGraffitoAccum);
        SmsPollutionMap.EnsureImplicitLayers(GetTree());
        Vector3 feet = new Vector3(GlobalPosition.X, SmsFeetY(), GlobalPosition.Z); // mPosition
        SmsPollutionMap.MarioPos = feet;
        _smsGround4cm = IsOnFloor() || SmsFloorWithin(4f);
        bool dirty = SmsPollutionSample(feet); // isDirty: the layers' paint under the sampling ring (pass 65)
        for (int i = 0; i < n; i++)
        {
            _smsMoveTick++;
            SmsPolluteTick(feet);
            if (dirty && stateOfMario != MarioState.dead)
            {
                switch (_smsPollution)
                {
                    case SmsPollution.Electric: SmsGraffitoElec(); break;
                    case SmsPollution.Fire: case SmsPollution.FireRegrow: SmsGraffitoFire(); break;
                    case SmsPollution.Slip: SmsGraffitoSlip(); break;
                    case SmsPollution.GlassWall:
                        // checkGraffito 1080: mPosition.x / z = mPrevPosition -- the painted spot is a wall he cannot cross
                        GlobalPosition = new Vector3(_smsTickStartPos.X, GlobalPosition.Y, _smsTickStartPos.Z);
                        break;
                    default: break; // SINK / INSTAKILL / SAFE: nothing here (checkSink below)
                }
            }
            _smsDirty = dirty; // onFlag / offFlag(MARIO_FLAG_DIRTY)
            SmsFootPrintTick();
            SmsThinkDirty();
            SmsCheckSink();
        }
        if (stateOfMario != MarioState.oilRun && stateOfMario != MarioState.oilSlip && _smsOilAnimRate != 0f)
        {
            animPlayer.SpeedScale = 1f; // the skid's clip rate, left behind by an exit the frame did not see (a walk-off)
            _smsOilAnimRate = 0f;
        }
        SmsSinkDraw();
        // pass 95: SMS_EmitSinkInPollutionEffect (EffectUtil.cpp 56) -- checkGraffito 1102: the goop ripple ring at mPosition while isTouchGround4cm
        // && isDirty (ANY paint); checkSink 1221: ring + the goop balls while he sinks. The game fires an unbound emitter every 20 move ticks; the
        // scene's two emitters run at that steady rate while asked for (SmsGoopRipple.Set), and the rings stay where they were born.
        if (_smsGoopRipple != null)
        {
            bool sinking = _smsSinkTimer > 0f && _smsPollution == SmsPollution.Sink && _smsDirty;
            bool ring = (dirty && _smsGround4cm && stateOfMario != MarioState.dead) || sinking;
            if (ring) _smsGoopRipple.Set(feet, IsOnFloor() ? GetFloorNormal() : Vector3.Up, true, sinking);
            else _smsGoopRipple.Off();
        }
    }

    // ---------------------------------------------------------------------------------------------------------------
    // GOOP (pass 64): the pollution types beyond fire / electric. checkGraffito (MarioMove.cpp 953) -> thinkDirty (1129) -> checkSink
    // (1183), once a tick after the move. The game's goop is a painted map read as a boolean under his feet ("isDirty": every point of a
    // 3 x 3 or 5-point ring 32 units apart painted); the port's floor body carries the type (metadata sms_pollution) and counts as
    // painted all over -- no paint map, so nothing is spread (pollute) or stamped (footprints), and FLUDD cannot clean it.
    // ---------------------------------------------------------------------------------------------------------------
    private float _smsOilBrake;          // mOilBrake: 0.98 (OIL_RUN) / 1.0 (OIL_SLIP, OIL_SLOPE) on the paint, 0 once the skid timer runs out
    private int _smsDirtyTimer;          // mDirtyTimer: the skid's life off the paint (reset to 10 / 60 every tick on it)
    private int _smsFogTimer;            // mStandingOnGraffitoTimer: 600 -> 0 on SLIP paint; yellow above 240, pink below, 1 HP at 360
    private float _smsDirtyAmount;       // mDirty 0..150 (thinkDirty): the goop on him -- the melt / fling (107) and the goop skin (111, addDirty) read it
    public float SmsDirtyAmount => _smsDirtyAmount;
    private float _smsSinkTimer;         // mSinkTimer: ticks sunk in SINK goop, held at 144 while HP > 0
    private float _smsOilFwd;            // mForwardVel in OIL_SLIP
    private float _smsOilAnimRate;       // the OIL_RUN clip rate the port put on the AnimationPlayer (0 = none)
    private bool _smsOilSlopeSlide;      // OIL_SLOPE: the surface slip is running slipBackCommon for the goop slope
    private Vector3 _smsTickStartPos;    // mPrevPosition: his position before this tick's move (the glass-wall revert)
    private uint _smsMoveTick;           // gpMarDirector->mMoveTickCount: the sink's damage cadence
    private SmsGoopRipple _smsGoopRipple; // pass 95: SMS_EmitSinkInPollutionEffect's ring (+ balls while sinking) at his feet
    private float _smsSinkDrawY;         // the sink offset on the armature now (metres)
    private int _smsFootPrintTimer;      // mFootPrintTimer: 520 the tick he stands on paint / mud, down a grounded tick; footprints and the jump stamp while above 260 (pass 65)
    private bool _smsGround4cm;          // isTouchGround4cm() this frame

    /// <summary>checkGraffito's isDirty (MarioMove.cpp 962-1046) against the goop layers: SLIP / INSTAKILL / SAFE want all nine points of a 3 x 3
    /// ring 32 units apart at his height painted; SINK / FIRE / GLASS_WALL / UNK7 the five points of a cross at the floor's height; ELECTRIC the
    /// one point under him. The type is the layer's whose XZ extent holds him (getPollutionType). A layer's isPolluted wants the point within
    /// 80 units of its surface, so a hop over goop is still dirty and a bridge over it is not.</summary>
    private bool SmsPollutionSample(Vector3 feet)
    {
        _smsPollution = SmsPollutionMap.GetPollutionType(feet);
        if (_smsPollution == SmsPollution.None)
            return false;
        float step = SmsUnits.UnitsToMetres(32f);
        switch (_smsPollution)
        {
            case SmsPollution.Slip:
            case SmsPollution.Instakill:
            case SmsPollution.Safe:
                for (int dz = -1; dz <= 1; dz++)
                    for (int dx = -1; dx <= 1; dx++)
                        if (!SmsPollutionMap.IsPolluted(new Vector3(feet.X + dx * step, feet.Y, feet.Z + dz * step)))
                            return false;
                return true;
            case SmsPollution.Sink:
            case SmsPollution.Fire:
            case SmsPollution.GlassWall:
            case SmsPollution.FireRegrow:
            {
                if (!SmsFloorYBelow(2000f, out float floorY))
                    return false; // mGroundPlane->isIllegalData(): nothing under him
                Vector3 p = new Vector3(feet.X, floorY, feet.Z); // mFloorPosition
                return SmsPollutionMap.IsPolluted(p + new Vector3(0f, 0f, -step)) && SmsPollutionMap.IsPolluted(p + new Vector3(step, 0f, 0f))
                    && SmsPollutionMap.IsPolluted(p) && SmsPollutionMap.IsPolluted(p + new Vector3(-step, 0f, 0f))
                    && SmsPollutionMap.IsPolluted(p + new Vector3(0f, 0f, step));
            }
            case SmsPollution.Electric:
            {
                if (!SmsFloorYBelow(2000f, out float floorY))
                    return false;
                return SmsPollutionMap.IsPolluted(new Vector3(feet.X, floorY, feet.Z));
            }
            default:
                return false;
        }
    }

    /// <summary>oilRun / oilSlip / oilSlope paint under him every move tick: pollute(mPolSizeRun 70) in OIL_RUN, pollute(mPolSizeSlip 130) in
    /// OIL_SLIP and OIL_SLOPE (MarioRun.cpp 1262 / 1324 / 1360) -- the goop he carries along the floor.</summary>
    private void SmsPolluteTick(Vector3 feet)
    {
        if (stateOfMario == MarioState.oilRun)
            SmsPollutionMap.Pollute(feet, SmsParams.Dirty.PolSizeRun);
        else if (stateOfMario == MarioState.oilSlip || (stateOfMario == MarioState.slipping && _smsOilSlopeSlide))
            SmsPollutionMap.Pollute(feet, SmsParams.Dirty.PolSizeSlip);
    }

    /// <summary>checkGraffito's tail (MarioMove.cpp 1104-1118): on the ground within 4 cm the footprint timer runs down; through its upper half
    /// (the first 125 ticks off the paint: mFootPrintTimerMax 250 as /Mario/Mario.prm ships it) he leaves footprints -- MAP_POLLUTION_MS_M_ASHIOS
    /// (pass 107: SmsEmitDirtyFootPrint) when the ground plane is legal and he is in no water -- and a jump stamps goop.</summary>
    private void SmsFootPrintTick()
    {
        if (!_smsGround4cm || _smsFootPrintTimer <= 0)
            return;
        _smsFootPrintTimer -= 1;
        if (_smsFootPrintTimer <= SmsParams.Graffito.FootPrintTimerMax / 2)
            return;
        if (!IsOnFloor() || _smsInWater)                                 // !mGroundPlane->isLegal(); MARIO_FLAG_IN_ANY_WATER
            return;
        SmsEmitDirtyFootPrint();
    }

    /// <summary>emitDirtyFootPrint = emitFootPrintWithEffect(MAP_POLLUTION_MS_M_ASHIOS, -1) (MarioParticle.cpp 599-664): in MARIO_STATUS_RUN only (the
    /// gait; OIL_RUN is its own status), as the motion frame ctrl passes 38 the LEFT foot joint's translation, 8 the RIGHT (checkPass: crossed since
    /// the last tick -- SMS frames are 60ths of a second, the gait clip loops), calcGroundMtx(it) (MarioMove.cpp 1799): the ground under the joint,
    /// X his right along the plane, Y up, Z his forward along it, 18 u up; the print emitted bound to a COPY of that frame 11 u down it (the
    /// jpa's trs) -- SmsGoopMario.SpawnFootPrint. printId -1: no map stamp here (that is the jump's).</summary>
    private void SmsEmitDirtyFootPrint()
    {
        if (_smsGoopFx == null || _sm == null || skeleton == null)
            return;
        bool run = stateOfMario is MarioState.walking or MarioState.running or MarioState.sprinting;
        string node = _sm.GetCurrentNode().ToString();
        if (!run || node != _smsGaitClip)
        {
            _smsGaitPosPrev = -1.0;
            return;
        }
        double len = _sm.GetCurrentLength(), pos = _sm.GetCurrentPlayPosition();
        double prev = _smsGaitPosPrev;
        _smsGaitPosPrev = pos;
        if (prev < 0.0 || len <= 0.0001 || pos == prev)
            return;
        // the state machine's play position keeps counting past the loop: fold both into the clip (the frame ctrl wraps at the clip's end)
        double p0 = Mathf.PosMod(prev, len), p1 = Mathf.PosMod(pos, len);
        if (pos - prev >= len)                                           // a whole loop (or more) between two reads: every footfall passed
            p0 = p1 - len * 0.999;
        SmsFootPrintPass(p0, p1, 38.0 / 60.0, "jnt_foot_L");
        SmsFootPrintPass(p0, p1, 8.0 / 60.0, "jnt_foot_R");
    }

    private void SmsFootPrintPass(double prev, double pos, double at, string joint)
    {
        bool passed = prev <= pos ? (prev < at && at <= pos) : (at > prev || at <= pos);  // the clip wrapped: the pass is in either leg
        if (!passed)
            return;
        int bone = skeleton.FindBone(joint);
        Vector3 foot = bone >= 0 ? (skeleton.GlobalTransform * skeleton.GetBoneGlobalPose(bone)).Origin : GlobalPosition;
        // calcGroundMtx: checkGround from the joint down (the joint hangs over the sole); the plane's tangents from his face angle
        var q = PhysicsRayQueryParameters3D.Create(foot + Vector3.Up * 0.05f, foot - Vector3.Up * SmsUnits.UnitsToMetres(150f), CollisionMask,
            new Godot.Collections.Array<Rid> { GetRid() });
        var hit = GetWorld3D().DirectSpaceState.IntersectRay(q);
        if (hit.Count == 0)
            return;
        Vector3 ground = (Vector3)hit["position"];
        Vector3 n = ((Vector3)hit["normal"]).Normalized();
        if (n.LengthSquared() < 0.5f) n = Vector3.Up;
        Vector3 face = _smsFaceValid ? SmsMath.DirFromYaw(_smsFaceYaw) : SmsFacingOrVelocityDir();
        Vector3 fwd = face - n * face.Dot(n);
        if (fwd.LengthSquared() < 1e-6f)
            return;
        fwd = fwd.Normalized();
        Vector3 right = n.Cross(fwd).Normalized();                       // X x Y = Z: the game's frame is right-handed (its X column = (cos, dy, -sin))
        _smsGoopFx.SpawnFootPrint(new Transform3D(new Basis(right, n, fwd), ground));
        if (SmsDebugPrint)
            GD.Print($"[SMS goop] footprint {joint} at {ground} (timer {_smsFootPrintTimer}, dirty {_smsDirtyAmount:F0})");
    }

    /// <summary>The sink lerps: (Max - Min)(1 - t) + Min with t = depth / SinkTime (flat 0.3 / 0.5 as shipped).</summary>
    private float SmsSinkScale(float min, float max) => (max - min) * (1f - _smsSinkTimer / SmsParams.Graffito.SinkTime) + min;

    /// <summary>checkGraffitoSlip() (MarioMove.cpp 862), the grounded branch -- every tick he stands on SLIP paint: the brake and the skid
    /// timer for the status he is in, the status he goes to (a steep floor: OIL_SLOPE; a dive or belly slide or an OIL_SLIP: OIL_SLIP; anything
    /// but CATCH_LOST: OIL_RUN), then the fog's clock: 600 while not yet dirty, down a tick, 1 HP (floorDamageExec) as it passes 360, back
    /// to 600 at 0. (The airborne branch -- OIL_SLIP / OIL_SLOPE off the ground keep a 0.998 brake -- is not reached in the port: isDirty
    /// is off the floor; the walk-off makes the fall.)</summary>
    private void SmsGraffitoSlip()
    {
        bool slipState = stateOfMario == MarioState.oilSlip || (stateOfMario == MarioState.slipping && _smsOilSlopeSlide);
        if (!_smsGround4cm)
        {
            // the airborne branch (MarioMove.cpp 918): a hop over the paint in OIL_SLIP / OIL_SLOPE keeps a 0.998 brake and the 60-tick skid timer
            if (slipState)
            {
                _smsOilBrake = SmsParams.Dirty.BrakeSlipNoPollute;
                _smsDirtyTimer = SmsParams.Dirty.DirtyTimeSlip;
            }
            return;
        }
        _smsFootPrintTimer = SmsParams.Graffito.FootPrintTimerMax; // mFootPrintTimer = mFootPrintTimerMax: the footprint window opens (and the jump stamp's)
        if (slipState)
        {
            _smsOilBrake = SmsParams.Dirty.BrakeStartValSlip;
            _smsDirtyTimer = SmsParams.Dirty.DirtyTimeSlip;
        }
        if (stateOfMario == MarioState.oilRun)
        {
            _smsOilBrake = SmsParams.Dirty.BrakeStartValRun;
            _smsDirtyTimer = SmsParams.Dirty.DirtyTimeRun;
        }
        Vector3 floorN = SmsFloorNormal4cm(); // mFloorTriangle->getNormal(): Godot's GetFloorNormal() is zero on the ray-grounded first tick (a spawn)
        if (floorN.Y <= SmsParams.Dirty.SlopeAngle)
        {
            _smsOilBrake = SmsParams.Dirty.BrakeStartValSlip;
            _smsDirtyTimer = SmsParams.Dirty.DirtyTimeSlip;
            SmsOilSlopeEnter(floorN); // OIL_SLOPE (+ MSD_SE_MV28_SPRISE_SMALL_01, not ported)
        }
        else if (slipState || stateOfMario is MarioState.diving or MarioState.singleJumpDive or MarioState.doubleJumpDive or MarioState.tripleJumpDive
                 or MarioState.bellySlidingFromDive)
        {
            _smsOilBrake = SmsParams.Dirty.BrakeStartValSlip;
            _smsDirtyTimer = SmsParams.Dirty.DirtyTimeSlip;
            if (stateOfMario != MarioState.oilSlip)
                SmsOilEnter(MarioState.oilSlip); // JUMP_CATCH / CATCH / OIL_SLOPE -> OIL_SLIP
        }
        else if (stateOfMario != MarioState.gettingUpFromSliding && SmsOilRunCanEnter())
        {
            _smsOilBrake = SmsParams.Dirty.BrakeStartValRun;
            _smsDirtyTimer = SmsParams.Dirty.DirtyTimeRun;
            if (stateOfMario != MarioState.oilRun)
                SmsOilEnter(MarioState.oilRun); // (PULLING -> OIL_PULLING: no pulling in the port)
        }
        if (!_smsDirty)
            _smsFogTimer = SmsParams.Dirty.FogTimeYellow + SmsParams.Dirty.FogTimeRed;
        _smsFogTimer -= 1;
        if (_smsFogTimer != 0)
        {
            if (_smsFogTimer == SmsParams.Dirty.FogTimeRed)
                SmsGoopFloorDamage("the goop's fog gone red");
        }
        else
            _smsFogTimer = SmsParams.Dirty.FogTimeYellow + SmsParams.Dirty.FogTimeRed;
    }

    /// <summary>checkGraffitoSlip's "else if (mStatus != CATCH_LOST)": the game turns ANY other status into OIL_RUN (changePlayerStatus refuses
    /// only from a loser). The port limits it to his ground statuses -- the knockdowns, the deaths, the pinned and demo states keep theirs.</summary>
    private bool SmsOilRunCanEnter()
    {
        switch (stateOfMario)
        {
            case MarioState.idle: case MarioState.pivot: case MarioState.sneak: case MarioState.walking: case MarioState.running:
            case MarioState.sprinting: case MarioState.landing: case MarioState.singleJumpLanding: case MarioState.doubleJumpLanding:
            case MarioState.tripleJumpLanding: case MarioState.rolloutRun: case MarioState.carrying: case MarioState.crouch:
            case MarioState.wallPush: case MarioState.wallShuffle: case MarioState.pickupFail: case MarioState.oilRun:
                return true;
            case MarioState.slipping:
                return !_smsOilSlopeSlide; // SLIP (the surface slip) -> OIL_RUN; the goop slope's own slide stays
            default:
                return false;
        }
    }

    /// <summary>changePlayerStatus(OIL_RUN / OIL_SLIP): the slide speed is kept. OIL_SLIP takes the tree down for its skid clip; OIL_RUN's clip
    /// block in SmsOilFrame takes it down each frame it runs, so the standing WAIT <-> OIL_RUN flip (every frame on the paint) keeps the idle
    /// clip playing, as the game's waiting() does (pass 67).</summary>
    private void SmsOilEnter(MarioState s)
    {
        MarioState was = stateOfMario;
        isJumping = false;
        isSpining(false);
        if (_smsSurfaceSlip)
            SmsExitSurfaceSlip($"the goop: {s}");
        stateOfMario = s;
        if (s == MarioState.oilSlip && animTree != null)
            animTree.Active = false;
        Vector3 face = _smsFaceValid ? SmsMath.DirFromYaw(_smsFaceYaw) : SmsFacingOrVelocityDir();
        Vector3 v = new Vector3(SmsUnits.MpsToSpeed(velocity.X), 0f, SmsUnits.MpsToSpeed(velocity.Z));
        _smsOilFwd = v.Dot(new Vector3(face.X, 0f, face.Z).Normalized()); // catching()'s mForwardVel carries into oilSlip
        if (s == MarioState.oilSlip)
        {
            animPlayer.SpeedScale = 1f;
            _smsOilAnimRate = 0f;
            animPlayer.Play("ma_slpbk"); // the belly slide's clip (CATCH), as the port's bellySlidingFromDive
        }
        if (SmsDebugPrint && !(s == MarioState.oilRun && was == MarioState.idle)) // (standing in goop is the game's WAIT <-> OIL_RUN every tick: not worth a line)
            GD.Print($"[SMS goop] {s} from {was} on '{_smsSurfaceNode}': brake {_smsOilBrake}, skid timer {_smsDirtyTimer}, fwd {_smsOilFwd:F1}");
    }

    /// <summary>OIL_SLOPE: oilSlope() is the skid timer + slipBackCommon(CATCH_LOST, LANDING) -- the surface slip's slide down the floor. The
    /// port starts its surface slip on the goop slope and marks it; checkGraffitoSlip re-asserts it every tick he is still on the paint.</summary>
    private void SmsOilSlopeEnter(Vector3 floorN)
    {
        if (stateOfMario == MarioState.slipping && _smsSurfaceSlip && _smsOilSlopeSlide)
            return;
        if (stateOfMario == MarioState.oilRun || stateOfMario == MarioState.oilSlip)
            SmsOilExit();
        SmsEnterSurfaceSlip(floorN);
        _smsOilSlopeSlide = true;
        if (SmsDebugPrint)
            GD.Print($"[SMS goop] OIL_SLOPE on '{_smsSurfaceNode}' (floor normal.y {floorN.Y:F3} <= {SmsParams.Dirty.SlopeAngle}): the slide down the goop");
    }

    private void SmsOilExit()
    {
        _smsOilBrake = 0f;
        _smsDirtyTimer = 0;
        if (_smsOilAnimRate != 0f)
        {
            animPlayer.SpeedScale = 1f;
            _smsOilAnimRate = 0f;
        }
    }

    /// <summary>oilRun() / oilSlip() (MarioRun.cpp 1238 / 1306), owning the ground frame in OIL_RUN / OIL_SLIP. OIL_RUN: A jumps (speed 0 first),
    /// B dives (JUMP_CATCH, vy 20), nearly still -> WAIT and the frame goes on as WAIT (the re-dispatch); the face turns to the stick at 256 BAM a tick, mVel += mag x face x 0.01, the skid
    /// timer down (0 -> the brake is 0), mVel x the brake; the clip is RUN2 at 0.5 x mag x 0.25 (WAIT at 0.5 with no stick). OIL_SLIP: A jumps;
    /// the face turns at 150; the timer down (0 -> brake 0 and CATCH); mForwardVel += mag x cos(face - stick) x 0.0001, x the brake, along the
    /// face; under 1 -> CATCH_LOST. The paint spreading (pollute 70 / 130 units) and the slip sounds (0x1001 / 0x1141) are not ported.</summary>
    private bool SmsOilFrame(double delta)
    {
        if (stateOfMario != MarioState.oilRun && stateOfMario != MarioState.oilSlip)
            return false;
        bool stick = direction.LengthSquared() > 1e-6f && _smsIntendedMag > 0f;
        float intendedYaw = stick ? SmsMath.YawFromDir(direction.Normalized()) : _smsFaceYaw;
        float mag = stick ? _smsIntendedMag : 0f;
        Vector3 v = new Vector3(SmsUnits.MpsToSpeed(velocity.X), 0f, SmsUnits.MpsToSpeed(velocity.Z));
        if (Input.IsActionJustPressed("button_a") || Input.IsActionJustPressed("key_space"))
        {
            // mInput & 2: setPlayerVelocity(0) and the jump -- a goop jump leaves with no run speed
            SmsOilExit();
            velocity.X = 0f;
            velocity.Z = 0f;
            jumpChainStage = 0;
            jumpChainTimer = 0;
            isJumping = true;
            stateOfMario = MarioState.singleJump;
            SmsLaunch(SmsAir.Launch.Jump);
            SetMarioState(stateOfMario);
            return true;
        }
        if (stateOfMario == MarioState.oilRun && Input.IsActionJustPressed("button_b") && heldBody == null)
        {
            // mInput & 0x8000: mVel.y = 20, JUMP_CATCH(1) -- the dive off the goop
            Vector3 dir = v.LengthSquared() > 1e-6f ? v.Normalized() : SmsMath.DirFromYaw(_smsFaceYaw);
            SmsOilExit();
            stateOfMario = MarioState.diving;
            SetMarioState(stateOfMario);
            SmsSetDiveVelocity(dir, fromGround: true);
            return true;
        }
        if (stateOfMario == MarioState.oilRun && v.X > -1f && v.X < 1f && v.Z > -1f && v.Z < 1f)
        {
            // oilRun() (MarioRun.cpp 1249): nearly still -> setPlayerVelocity(0), changePlayerStatus(WAIT). The game's stateMachine()
            // (MarioMove.cpp 1772) loops while a status changes, so WAIT runs in the SAME tick: waitingCommonEvents turns a pushed stick
            // into RUN, doRunning gives the first 1.1, and checkGraffitoSlip makes it OIL_RUN again at the tick's end -- now moving. The
            // port ended the frame here, so from a standstill every frame went OIL_RUN -> WAIT -> OIL_RUN with the stick never reaching
            // doRunning: he stood softlocked on the paint until a jump (pass 67). Returning false hands the rest of the frame to the
            // ground code = the game's loop. (Checked once a frame, before the ticks, so the ground code gets the frame's ticks once.)
            velocity.X = 0f;
            velocity.Z = 0f;
            SmsOilExit();
            stateOfMario = MarioState.idle; // WAIT (checkGraffitoSlip puts him back in OIL_RUN at the frame's end while he stands on the paint)
            SetMarioState(stateOfMario);
            return false;
        }
        int n = SmsUnits.TicksFor(delta, ref _smsTickAccum);
        for (int i = 0; i < n; i++)
        {
            if (stateOfMario == MarioState.oilRun)
            {
                _smsFaceYaw = SmsMath.ConvergeAngle(_smsFaceYaw, intendedYaw, SmsParams.Dirty.SlipRotate * SmsUnits.BamToRad);
                _smsFaceValid = true;
                Vector3 face = SmsMath.DirFromYaw(_smsFaceYaw);
                v.X += mag * face.X * SmsParams.Dirty.SlipRunSp;
                v.Z += mag * face.Z * SmsParams.Dirty.SlipRunSp;
                _smsDirtyTimer--;
                if (_smsDirtyTimer <= 0)
                {
                    _smsDirtyTimer = 0;
                    _smsOilBrake = 0f;
                }
                v.X *= _smsOilBrake;
                v.Z *= _smsOilBrake;
            }
            else
            {
                _smsFaceYaw = SmsMath.ConvergeAngle(_smsFaceYaw, intendedYaw, SmsParams.Dirty.SlipCatchRotate * SmsUnits.BamToRad);
                _smsFaceValid = true;
                _smsDirtyTimer--;
                bool toCatch = false;
                if (_smsDirtyTimer <= 0)
                {
                    _smsDirtyTimer = 0;
                    _smsOilBrake = 0f;
                    toCatch = true; // changePlayerStatus(CATCH): the plain belly slide carries on (it stops as its own rules say)
                }
                _smsOilFwd += mag * Mathf.Cos(_smsFaceYaw - intendedYaw) * SmsParams.Dirty.SlipCatchSp;
                _smsOilFwd *= _smsOilBrake;
                Vector3 face = SmsMath.DirFromYaw(_smsFaceYaw);
                v = new Vector3(face.X, 0f, face.Z) * _smsOilFwd;
                if (_smsOilFwd > -1f && _smsOilFwd < 1f)
                {
                    v = Vector3.Zero;
                    SmsOilExit();
                    stateOfMario = MarioState.gettingUpFromSliding; // CATCH_LOST
                    SetMarioState(stateOfMario);
                    break;
                }
                if (toCatch)
                {
                    SmsOilExit();
                    stateOfMario = MarioState.bellySlidingFromDive;
                    SetMarioState(stateOfMario);
                    break;
                }
            }
        }
        velocity.X = SmsUnits.SpeedToMps(v.X);
        velocity.Z = SmsUnits.SpeedToMps(v.Z);
        Vector3 f = SmsMath.DirFromYaw(_smsFaceYaw);
        lastFacingDirection = f;
        armature.Rotation = new Vector3(0f, YawFromDir(f), 0f);
        if (stateOfMario == MarioState.oilRun)
        {
            // ANIM_RUN2 at 0.5 x mag x mSlipAnmSpeed (the legs pedal, up to 4.0); no stick: ANIM_SQWAT at 0.5 with the squat button held (mInput & L,
            // MarioRun.cpp 1282; pass 110), else ANIM_WAIT at 0.5
            string clip = mag > 0f ? "ma_run2" : (SmsSquatLHeld() && animPlayer.HasAnimation("ma_sqwat") ? "ma_sqwat" : "ma_wait");
            float rate = mag > 0f ? 0.5f * mag * SmsParams.Dirty.SlipAnmSpeed : 0.5f;
            if (animTree != null)
                animTree.Active = false;
            if (animPlayer.CurrentAnimation != clip)
                animPlayer.Play(clip);
            animPlayer.SpeedScale = rate;
            _smsOilAnimRate = rate;
        }
        return true;
    }

    /// <summary>thinkDirty() (MarioMove.cpp 1129): the goop on him, 0..150 -- up on paint by the status (0.15 running, 1.5 catching / skidding,
    /// 0.5 slipping), down in water (0.3 a tick), in a spin jump (0.5), the tick he leaves water (0.2, not tracked). The melt and the fling (pass
    /// 107) read it; the layer dirtying him dresses his goop particles (pass 108, SmsGoopMario.GoopFromLayer).</summary>
    private void SmsThinkDirty()
    {
        if (_smsDirty)
        {
            _smsGoopFx?.SetGoopLayer(SmsPollutionMap.PollutedLayerAt(SmsPollutionMap.MarioPos));   // pass 108: the layer under his feet (set by SmsCheckGraffito this frame)
            if (stateOfMario is MarioState.walking or MarioState.running or MarioState.sprinting or MarioState.oilRun)
                _smsDirtyAmount += SmsParams.Dirty.IncRunning;
            if (stateOfMario == MarioState.bellySlidingFromDive || stateOfMario == MarioState.oilSlip || (stateOfMario == MarioState.slipping && _smsOilSlopeSlide))
                _smsDirtyAmount += SmsParams.Dirty.IncCatching;
            if (stateOfMario == MarioState.slipping && !_smsOilSlopeSlide)
                _smsDirtyAmount += SmsParams.Dirty.IncSlipping;
        }
        if (_smsInWater)                                                 // MARIO_FLAG_IN_ANY_WATER (MarioMove.cpp 1128): wading counts, not only the swim
        {
            // meltInWaterEffect (MarioParticle.cpp 671) within 200 u of the surface: MAP_POLLUTION_MS_M_TOKEOS bound to unk220 (his x / z at the water
            // surface, his yaw -- MarioMove.cpp 2057), rate mDirty x MeltInWaterMax / 255, setGlobalScale 0.6 in shallow water (pass 107)
            bool nearSurface = SmsUnits.MetresToUnits(_smsWaterSurfaceY - SmsFeetY()) < 200f;
            if (_smsDirtyAmount > 0f && nearSurface && _smsGoopFx != null)
            {
                bool shallow = stateOfMario != MarioState.swimming && IsOnFloor();   // MARIO_FLAG_IN_SHALLOW_WATER: wading
                var surface = new Transform3D(new Basis(Vector3.Up, _smsFaceValid ? _smsFaceYaw : 0f), new Vector3(GlobalPosition.X, _smsWaterSurfaceY, GlobalPosition.Z));
                _smsGoopFx.MeltSet(surface, _smsDirtyAmount * SmsParams.Dirty.MeltInWaterMax / 255f, shallow);
            }
            else
                _smsGoopFx?.MeltOff();
            _smsDirtyAmount -= SmsParams.Dirty.DecSwimming;
            _smsFootPrintTimer = 0; // the water takes the footprints
        }
        else
            _smsGoopFx?.MeltOff();
        if (stateOfMario == MarioState.SpinJump)
        {
            _smsDirtyAmount -= SmsParams.Dirty.DecRotJump;
            _smsFootPrintTimer = 0;
        }
        _smsDirtyAmount = Mathf.Clamp(_smsDirtyAmount, 0f, SmsParams.Dirty.DirtyMax); // dirtyLimitCheck()
    }

    /// <summary>checkSink() (MarioMove.cpp 1183): not invincible, the floor within 100 units. On SINK paint: the depth up a tick, held at 144
    /// while HP > 0, 1 HP every 90 move ticks (floorDamageExec 1 / type 3), the drown (loserExec + SINK_LOSER) past 240 -- so the mud costs HP
    /// until he has none, then takes him. INSTAKILL paint: speed 0, loserExec, SINK_LOSER at once. Off either: the depth is 0.</summary>
    private void SmsCheckSink()
    {
        if (_smsInvincibleTicks > 0 || stateOfMario == MarioState.dead)
            return;
        if (!SmsFloorWithin(100f))
        {
            _smsSinkTimer = 0f;
            return;
        }
        if (_smsPollution == SmsPollution.Sink && _smsDirty)
        {
            _smsSinkTimer += 1f;
            _smsFootPrintTimer = SmsParams.Graffito.FootPrintTimerMax; // checkSink: the mud leaves footprints too
            float hold = SmsParams.Graffito.SinkTime * SmsParams.Graffito.SinkDmgDepth;
            if (_health > 0 && _smsSinkTimer > hold)
                _smsSinkTimer = hold;
            if (_smsMoveTick % (uint)SmsParams.Graffito.SinkDmgTime == 0)
                SmsGoopFloorDamage("the mud");
            // MSD_SE_MA_SINK_IN_MUD, the sinking splash, MSD_SE_MV10A_CRY_SHORT_01: not ported
            if (_smsSinkTimer > SmsParams.Graffito.SinkTime)
            {
                if (SmsDebugPrint) GD.Print("[SMS goop] sunk: loserExec -> SINK_LOSER");
                velocity = Vector3.Zero;
                EnterDead(); // SINK_LOSER (ma_sink_down is not wired: the port's loser pose)
            }
            return;
        }
        if (_smsPollution == SmsPollution.Instakill && _smsDirty)
        {
            if (SmsDebugPrint) GD.Print("[SMS goop] instakill paint: loserExec -> SINK_LOSER");
            velocity = Vector3.Zero;
            EnterDead();
            return;
        }
        _smsSinkTimer = 0f;
    }

    /// <summary>floorDamageExec(1, 3, 0, mMotorReturn) (MarioCollision.cpp 235): damageExec with the floor actor 1 unit ahead -- 1 HP, type 3 (no
    /// knockdown; the upper damage run while running), min speed 16, 60 ticks invincible.</summary>
    private void SmsGoopFloorDamage(string why)
    {
        Vector3 face = _smsFaceValid ? SmsMath.DirFromYaw(_smsFaceYaw) : SmsFacingOrVelocityDir();
        if (SmsDebugPrint) GD.Print($"[SMS goop] floorDamageExec: {why} -> HP {_health} - 1");
        SmsDamageExec(GlobalPosition + face * SmsUnits.UnitsToMetres(1f), new SmsDamageProfile(1, 3, 16f, 60));
    }

    /// <summary>MarioDraw.cpp 1760: isSinking() -> the model drawn (depth / SinkTime) x SinkHeight lower. The port offsets the armature while
    /// sinking and puts it back the tick the depth is 0.</summary>
    private void SmsSinkDraw()
    {
        if (armature == null)
            return;
        float want = _smsSinkTimer > 0f ? SmsUnits.UnitsToMetres(_smsSinkTimer / SmsParams.Graffito.SinkTime * SmsParams.Graffito.SinkHeight) : 0f;
        if (Mathf.IsEqualApprox(want, _smsSinkDrawY))
            return;
        Vector3 p = armature.Position;
        armature.Position = new Vector3(p.X, p.Y + _smsSinkDrawY - want, p.Z);
        _smsSinkDrawY = want;
    }

    /// <summary>
    /// checkGraffitoFire() (MarioMove.cpp 830): on a hot floor within FireHeight (graffito.prm 5 units of the floor under him) and not
    /// invincible. Already burning (FIRE_DOWN / FIRE_JUMP_END), the face turns 180 first, so he goes back the way he came.
    /// makeGraffitoDamage(dmggraffitofire): damageExec() with the floor as the attacker, 1 unit in front of him -- the face stays, the
    /// stars 50 units in front, the camera shake, 1 HP, the tank's spill (0), 50 ticks invincible -- and the knockdown status it sets is
    /// replaced by FIRE_DOWN(1) with his forward speed restored (unk55C is 50 in MarioInit.cpp: the restore always runs). What he holds
    /// is dropped. The cloud (particle 6, ms_firedmg_a) plays from FIRE_DOWN's entry; MSD_SE_MA_DAMAGE_FIRE is the FireDamageSound slot.
    /// </summary>
    private void SmsGraffitoFire()
    {
        if (_smsInvincibleTicks > 0 || _health <= 0 || stateOfMario == MarioState.dead || stateOfMario == MarioState.swimming)
            return;
        if (!SmsFloorWithin(SmsParams.Graffito.FireHeight))
            return; // mPosition.y - mFloorPosition.y > mFireHeight: the fire goop burns on its floor, not the air over it (a jump clears it)
        bool burning = stateOfMario == MarioState.hurt && (_smsDownKind == SmsDownKind.Fire || _smsDownKind == SmsDownKind.FireEnd);
        Vector3 face = _smsFaceValid ? SmsMath.DirFromYaw(_smsFaceYaw) : SmsFacingOrVelocityDir();
        float fwd = burning ? _smsDownFwd : SmsUnits.MpsToSpeed(new Vector3(velocity.X, 0f, velocity.Z).Dot(face)); // mForwardVel, saved
        if (burning)
            face = -face; // mFaceAngle.y += 0x8000: the same fwd along the turned face sends him back the way he came
        SmsDamageProfile p = SmsDamageProfile.GraffitoFire;
        if (heldBody != null)
            Anim_DetachPickup(); // changePlayerDropping() + dropObject()
        _smsInvincibleTicks = Math.Max(p.InvincibleTicks, SmsParams.Graffito.FireInvincibleTime); // both 50 as shipped
        SmsFluddDamage(p.WaterEmit);
        _health = Math.Max(_health - p.Damage, 0); // decHP()
        SpawnHitStars(ComputeFeetPosition() + face * SmsUnits.UnitsToMetres(50f)); // calcDamagePos: 50 units toward the floor actor = in front
        _smsCameraShake?.Start(SmsCameraShake.Kind.Damage); // damageExec: every type but 3 shakes
        if (FireDamageSound != null && FireDamageSound.Stream != null)
            FireDamageSound.Play();
        if (SmsDebugPrint)
            GD.Print($"[SMS fire] hot floor '{_smsSurfaceNode}': -{p.Damage} HP -> {_health}/{StartingHealth}{(burning ? ", already burning: face turned 180" : "")}; invincible {_smsInvincibleTicks} ticks");
        if (_health <= 0)
            _smsGameOver = true; // decHP() -> loserExec(): MARIO_FLAG_GAME_OVER and DOWN_LOSER -- which the FIRE_DOWN below replaces (changePlayerStatus refuses only from LOSER_DOWN): the jump flies at 0 HP and its landing is the loser pose (SmsTickFireDown)
        SmsFireDownEnter(SmsParams.Jump.GraffitoFireStatusArg, fwd, face, "the hot floor"); // the game passes 1 (fwd kept); 0 = his backward kick (SmsParams.Jump.GraffitoFireStatusArg)
    }

    /// <summary>
    /// changePlayerStatus(MARIO_STATUS_FIRE_DOWN, arg) (MarioMove.cpp 539): arg 1 (every live source) launches at FireDownForce with fwd
    /// kept; arg 0 adds the -FireBackVelocity kick; arg 2 launches nothing. ma_firejmp at 1.0, the eyes squeezed shut (ma_fjpend_tx).
    /// <paramref name="fwd"/> is signed along <paramref name="face"/> (a hit from the front leaves it negative: backwards, facing the attacker).
    /// </summary>
    private void SmsFireDownEnter(int arg, float fwd, Vector3 face, string from)
    {
        ledgePinned = false;
        _smsHangMovingAnim = false;
        _smsLongFallAnim = false;
        _smsFallCancel = false;
        isJumping = false;
        jumpBuffer = 0;
        SmsLatchFace(face, 1);
        lastFacingDirection = face;
        armature.Rotation = new Vector3(0f, YawFromDir(face), 0f);
        StopWaistIKHard();
        SetEyeTexture(hurtEyeTexture ?? sleepingEyeTexture);
        stateOfMario = MarioState.hurt;
        _smsDownKind = SmsDownKind.Fire;
        _smsDownAir = true;
        _smsDownFore = false;
        _smsFireBounces = 0;
        _smsFireTicks = 0;
        _smsDownFwd = fwd;
        if (arg != 2)
        {
            _smsFireVy = SmsParams.Jump.FireDownForce;
            velocity.Y = SmsUnits.SpeedToMps(_smsFireVy);
            _smsTrueVyValid = false;
            _smsNoLandFrames = 3; // floor snapping still reports the ground for a frame or two after the launch
            if (arg == 0)
                _smsDownFwd = -SmsParams.Jump.FireBackVelocity;
        }
        else
        {
            _smsFireVy = SmsUnits.MpsToSpeed(velocity.Y);
        }
        SmsDownApplyVelocity();
        SmsDownPlay("ma_firejmp", 1f);
        if (_smsFireFx != null)
        {
            // emitAndBindToPosPtr(6, &mPosition, 0): the cloud's emitter rides at his feet, its puffs stay where they were born
            _smsFireFx.GlobalPosition = ComputeFeetPosition();
            _smsFireFx.Play();
        }
        if (SmsDebugPrint)
            GD.Print($"[SMS fire] FIRE_DOWN({arg}) from {from}: vy {_smsFireVy:F0} ({SmsUnits.SpeedToMps(_smsFireVy):F1} m/s), fwd {_smsDownFwd:F1} along the face, ma_firejmp, the cloud {(_smsFireFx != null ? "from the scene" : "MISSING")}");
    }

    /// <summary>
    /// fireDowning() (MarioJump.cpp 698), one physics frame. Tick 1 the fire cry (not ported). The stick: fwd += 0.03125 x mag x
    /// FireDownControl along it and the face turns by its sine -- the shipped jump.prm has FireDownControl 0, so the stick steers
    /// nothing; what it still does is trim a fwd over 32 by 2 a tick. The stick at rest: fwd converges to 0 by 0.35 a tick. Then
    /// jumpProcess(0): gravity, a wall mirrors the face (playerRefrection), the floor -- under two bounces and falling: vy = 0.4 x -vy, fwd
    /// halves; else the reaction voice (not ported) and FIRE_JUMP_END. setAnimation(ANIM_FIREJMP) every tick: the clip keeps going.
    /// </summary>
    private void SmsTickFireDown(double delta, Vector3 stickDir)
    {
        if (IsOnFloor() && velocity.Y <= 0.01f && _smsNoLandFrames <= 0)
        {
            if (_smsGameOver)
            {
                SmsLoserDown(); // loserExec() had set DOWN_LOSER before the FIRE_DOWN replaced it: the game's director fades the stage out meanwhile; here the landing takes the loser pose
                return;
            }
            if (_smsFireBounces < 2 && _smsFireVy < 0f)
            {
                _smsFireVy = 0.4f * -_smsFireVy;
                _smsDownFwd *= 0.5f; // setPlayerVelocity(0.5 x fwd)
                _smsFireBounces++;
                velocity.Y = SmsUnits.SpeedToMps(_smsFireVy);
                _smsTrueVyValid = false;
                _smsNoLandFrames = 3;
                SmsDownApplyVelocity();
                if (SmsDebugPrint)
                    GD.Print($"[SMS fire] bounce {_smsFireBounces}: vy {_smsFireVy:F1} ({SmsUnits.SpeedToMps(_smsFireVy):F1} m/s), fwd {_smsDownFwd:F1}");
                return;
            }
            SmsFireJumpEndEnter();
            return;
        }
        SmsHurtWallMirror(false); // jumpProcess() 2
        int n = SmsUnits.TicksFor(delta, ref _smsTickAccum);
        bool stick = stickDir.LengthSquared() > 1e-6f && _smsIntendedMag > 0f; // mInput & 1
        Vector3 faceDir = SmsMath.DirFromYaw(_smsFaceYaw);
        float d = stick ? faceDir.SignedAngleTo(new Vector3(stickDir.X, 0f, stickDir.Z).Normalized(), Vector3.Up) : 0f;
        float yaw = _smsFaceYaw;
        float fwd = _smsDownFwd;
        float vyMps = (_smsTrueVyValid && Mathf.Abs(velocity.Y - _smsMoveVyMps) < 1e-3f) ? _smsTrueVy : velocity.Y;
        float vy = SmsUnits.MpsToSpeed(vyMps);
        float sumMv = 0f;
        for (int i = 0; i < n; i++)
        {
            _smsFireTicks++;
            if (!stick)
            {
                fwd = SmsMath.Converge(fwd, 0f, 0.35f); // FConverge(fwd, 0, 0.35, 0.35)
            }
            else
            {
                float velInc = 0.03125f * _smsIntendedMag * SmsParams.Jump.FireDownControl; // 0 as shipped
                fwd += velInc * MathF.Cos(d);
                yaw += 1024f * (velInc * MathF.Sin(d)) * SmsUnits.BamToRad;
                if (fwd < 0f)
                {
                    yaw += MathF.PI; // mFaceAngle.y += 0x8000
                    fwd = -fwd;
                }
                if (fwd > 32f)
                    fwd -= 2f;
            }
            SmsAir.GravityOnlyTick(ref vy, out float mv);
            sumMv += mv;
        }
        if (yaw != _smsFaceYaw)
        {
            Vector3 nf = SmsMath.DirFromYaw(yaw);
            SmsLatchFace(nf, 1);
            lastFacingDirection = nf;
            armature.Rotation = new Vector3(0f, YawFromDir(nf), 0f);
        }
        velocity.Y = SmsUnits.SpeedToMps(sumMv / n);
        _smsMoveVyMps = velocity.Y;
        _smsTrueVy = SmsUnits.SpeedToMps(vy);
        _smsTrueVyValid = true;
        _smsFireVy = vy;
        _smsDownFwd = fwd;
        SmsDownApplyVelocity();
        if (!animPlayer.IsPlaying() || animPlayer.CurrentAnimation != "ma_firejmp")
            SmsDownPlay("ma_firejmp", 1f);
    }

    /// <summary>FIRE_JUMP_END (fireJumpEnd, MarioWait.cpp 504): jumpEndCommon(ANIM_FJPEND, WAIT) -- waitProcess() stands him still on the
    /// floor, ma_fjpend plays once, its last frame is WAIT; jumpEndEvents() first: A is a jump, the stick is RUN (checkAllMotions).</summary>
    private void SmsFireJumpEndEnter()
    {
        _smsDownKind = SmsDownKind.FireEnd;
        _smsDownAir = false;
        _smsDownFwd = 0f;
        velocity = Vector3.Zero;
        SmsDownPlay("ma_fjpend", 1f);
        if (SmsDebugPrint)
            GD.Print($"[SMS fire] landed after {_smsFireBounces} bounce(s), {_smsFireTicks} ticks burning: FIRE_JUMP_END, ma_fjpend (the reaction voice is not ported)");
    }

    private void SmsTickFireEnd(Vector3 stickDir)
    {
        velocity = Vector3.Zero; // waitProcess(): setPlayerVelocity(0), on the floor
        bool aPressed = Input.IsActionJustPressed("button_a") || Input.IsActionJustPressed("key_space"); // mInput & 2
        bool stick = stickDir.LengthSquared() > 1e-6f && _smsIntendedMag > 0f;                          // mInput & 1
        if (aPressed || stick)
        {
            // jumpEndEvents(): A -> changePlayerTriJump (the jump buffer carries this frame's press to the idle path), the stick ->
            // checkAllMotions (RUN on the next frame)
            SmsHurtStandUp(aPressed ? "[SMS fire] A during ma_fjpend: up, the jump follows" : "[SMS fire] the stick during ma_fjpend: up, RUN follows");
            return;
        }
        if (!IsOnFloor())
        {
            SmsHurtStandUp("[SMS fire] the floor went while ma_fjpend played: up"); // waitProcess() snaps him to the floor below; the main path's fall does here
            return;
        }
        if (!(animPlayer.IsPlaying() && animPlayer.CurrentAnimation == "ma_fjpend"))
            SmsHurtStandUp("[SMS fire] up"); // isLast1AnimeFrame(): WAIT
    }

    // ---------------------------------------------------------------------------------------------------------------
    // THROWN_DOWN / THROWN_END (pass 94): an NPC's TNpcThrow (SMS_SendMessageToMario(HIT_MESSAGE_THROWN) + SMS_ThrowMario)
    /// <summary>receiveMessage(HIT_MESSAGE_THROWN) (MarioReceiveMsg.cpp 123): changePlayerStatus(THROWN_DOWN, 0, false), then TMario::throwMario
    /// (MarioMove.cpp 711): the vector normalised (a zero vector = straight up), mFaceAngle.y = matan(z, x) + 0x8000 -- he FACES BACK along the
    /// flight, at the thrower -- mForwardVel = -speed x |xz| (negative: he moves along the vector, backwards), mVel.y = speed x y. ANIM_THROWN
    /// loops until the second bounce (thrownDowning). Speed in units a tick; the sound (MA_HANEAGARI) is not ported.</summary>
    public void SmsThrowMario(Vector3 dir, float speedUnitsPerTick, SmsNpc thrower)
    {
        if (stateOfMario == MarioState.dead || _smsGameOver)
            return;
        if (_smsTalking)
            SmsTalkEnd(); // the director has let him go by the throw's tick (the talk closed 40 ticks before); a fade still running is cut here
        Vector3 v = dir;
        if (v.LengthSquared() <= 1e-12f)
            v = Vector3.Up;
        v = v.Normalized();
        Vector3 flat = new Vector3(v.X, 0f, v.Z);
        float xz = flat.Length();
        Vector3 face = xz > 1e-6f ? -flat / xz : (_smsFaceValid ? SmsMath.DirFromYaw(_smsFaceYaw) : SmsFacingOrVelocityDir());
        float fwd = -speedUnitsPerTick * xz;
        float vy = v.Y * speedUnitsPerTick;
        // whatever he was doing is over (as the knockdown does)
        ledgePinned = false;
        _smsHangMovingAnim = false;
        _smsLongFallAnim = false;
        _smsFallCancel = false;
        isJumping = false;
        jumpBuffer = 0;
        if (heldBody != null)
            Anim_DetachPickup(); // a thrown Mario flails (ANIM_THROWN): what he held goes (dropObject)
        SmsLatchFace(face, 1);
        lastFacingDirection = face;
        armature.Rotation = new Vector3(0f, YawFromDir(face), 0f);
        StopWaistIKHard();
        stateOfMario = MarioState.hurt;
        _smsDownKind = SmsDownKind.Thrown;
        _smsDownAir = true;
        _smsDownFore = false;
        _smsDownType = 2;
        _smsDownFwd = fwd;
        _smsThrownVy = vy;
        _smsThrownBounces = 0;
        _smsThrownTicks = 0;
        velocity.Y = 0f;                       // the ticks integrate the vy from here (the game sets mVel.y and the same movement steps it vel/4 a tick)
        _smsMoveVyMps = 0f;
        _smsTrueVy = SmsUnits.SpeedToMps(vy);
        _smsTrueVyValid = true;
        _smsNoLandFrames = 3; // floor contact is the ground he is leaving for a frame or two
        SmsDownApplyVelocity();
        SmsDownPlay("ma_thrown", 1f);
        if (SmsDebugPrint)
            GD.Print($"[SMS thrown] by {thrower?.Name}: vector {v}, {speedUnitsPerTick} u/tick -> fwd {fwd:F1} (backwards, facing the thrower), vy {vy:F1} ({SmsUnits.SpeedToMps(vy):F1} m/s)");
    }

    /// <summary>thrownDowning() (MarioJump.cpp 738), one physics frame: per tick the stick adds 0.03125 x mag x cos(stick - face) x ThrownAccel to
    /// the forward speed and 0.03125 x mag x sin x ThrownSlide to the face angle (a u16: under one BAM a tick it truncates to nothing, as the
    /// shipped 0.1 does), fwd x= ThrownBrake (1.0), the velocity along the face; jumpProcess(0): landed -> twice a bounce of 0.4 x -vy at half
    /// the speed, the third landing THROWN_END; a wall -> playerRefrection(0) (the face mirrored). ANIM_THROWN every frame.</summary>
    private void SmsTickThrown(double delta, Vector3 stickDir)
    {
        if (IsOnFloor() && velocity.Y <= 0.01f && _smsNoLandFrames <= 0)
        {
            if (_smsThrownBounces < 2 && _smsThrownVy < 0f)
            {
                _smsThrownVy = 0.4f * -_smsThrownVy;
                _smsDownFwd *= 0.5f; // setPlayerVelocity(0.5 x fwd)
                _smsThrownBounces++;
                velocity.Y = SmsUnits.SpeedToMps(_smsThrownVy);
                _smsTrueVyValid = false;
                _smsNoLandFrames = 3;
                SmsDownApplyVelocity();
                if (SmsDebugPrint)
                    GD.Print($"[SMS thrown] bounce {_smsThrownBounces}: vy {_smsThrownVy:F1} ({SmsUnits.SpeedToMps(_smsThrownVy):F1} m/s), fwd {_smsDownFwd:F1}");
                return;
            }
            SmsThrownEndEnter();
            return;
        }
        SmsHurtWallMirror(false); // jumpProcess() 2: playerRefrection(0)
        int n = SmsUnits.TicksFor(delta, ref _smsTickAccum);
        bool stick = stickDir.LengthSquared() > 1e-6f && _smsIntendedMag > 0f;
        Vector3 faceDir = SmsMath.DirFromYaw(_smsFaceYaw);
        float d = stick ? faceDir.SignedAngleTo(new Vector3(stickDir.X, 0f, stickDir.Z).Normalized(), Vector3.Up) : 0f; // mIntendedYaw - mFaceAngle.y
        float yaw = _smsFaceYaw;
        float fwd = _smsDownFwd;
        float vyMps = (_smsTrueVyValid && Mathf.Abs(velocity.Y - _smsMoveVyMps) < 1e-3f) ? _smsTrueVy : velocity.Y;
        float vy = SmsUnits.MpsToSpeed(vyMps);
        float sumMv = 0f;
        for (int i = 0; i < n; i++)
        {
            _smsThrownTicks++;
            float velInc = 0.03125f * (stick ? _smsIntendedMag : 0f);
            fwd += velInc * MathF.Cos(d) * SmsParams.Jump.ThrownAccel;
            int slideBam = (int)(velInc * MathF.Sin(d) * SmsParams.Jump.ThrownSlide); // mFaceAngle.y is a u16: the fraction is lost
            if (slideBam != 0)
                yaw += slideBam * SmsUnits.BamToRad;
            fwd *= SmsParams.Jump.ThrownBrake;
            SmsAir.GravityOnlyTick(ref vy, out float mv);
            sumMv += mv;
        }
        if (yaw != _smsFaceYaw)
        {
            Vector3 nf = SmsMath.DirFromYaw(yaw);
            SmsLatchFace(nf, 1);
            lastFacingDirection = nf;
            armature.Rotation = new Vector3(0f, YawFromDir(nf), 0f);
        }
        velocity.Y = SmsUnits.SpeedToMps(sumMv / n);
        _smsMoveVyMps = velocity.Y;
        _smsTrueVy = SmsUnits.SpeedToMps(vy);
        _smsTrueVyValid = true;
        _smsThrownVy = vy;
        _smsDownFwd = fwd;
        SmsDownApplyVelocity();
        if (!animPlayer.IsPlaying() || animPlayer.CurrentAnimation != "ma_thrown")
            SmsDownPlay("ma_thrown", 1f);
    }

    /// <summary>THROWN_END (squatStandup, MarioWait.cpp 395): on the floor, waitProcess() -- he stands, the last speed dies -- with ANIM_THROWN_END
    /// once; a pushed stick (mInput & 1) is RUN at once; the clip's last frame is WAIT.</summary>
    private void SmsThrownEndEnter()
    {
        _smsDownKind = SmsDownKind.ThrownEnd;
        _smsDownAir = false;
        _smsDownFwd = 0f;
        velocity = Vector3.Zero;
        SmsDownPlay("ma_thrown_end", 1f);
        if (SmsDebugPrint)
            GD.Print($"[SMS thrown] landed after {_smsThrownBounces} bounce(s), {_smsThrownTicks} ticks in the air: THROWN_END, ma_thrown_end");
    }

    private void SmsTickThrownEnd(Vector3 stickDir)
    {
        velocity = Vector3.Zero; // waitProcess(): setPlayerVelocity(0), on the floor
        bool stick = stickDir.LengthSquared() > 1e-6f && _smsIntendedMag > 0f; // mInput & 1
        if (stick)
        {
            SmsHurtStandUp("[SMS thrown] the stick during ma_thrown_end: up, RUN follows");
            return;
        }
        if (!IsOnFloor())
        {
            SmsHurtStandUp("[SMS thrown] the floor went while ma_thrown_end played: up");
            return;
        }
        if (!(animPlayer.IsPlaying() && animPlayer.CurrentAnimation == "ma_thrown_end"))
            SmsHurtStandUp("[SMS thrown] up"); // isLast1AnimeFrame(): WAIT
    }

    /// <summary>The grounded families: MARIO_STATUS_TYPE_WAITING (WAIT, SQUAT, the *_END recoveries, SLEEPY / SLEEP) and
    /// MARIO_STATUS_TYPE_RUNNING (RUN, TURN, BRAKE, the SLIPs, the JUMP_SLIP landings, ROTATE_L / R, CATCH), as the port has them.</summary>
    private bool SmsWaitingOrRunningType(MarioState s)
    {
        if (!IsOnFloor())
            return false;
        switch (s)
        {
            case MarioState.idle:
            case MarioState.pivot:
            case MarioState.sneak:
            case MarioState.walking:
            case MarioState.running:
            case MarioState.sprinting:
            case MarioState.crouch:
            case MarioState.landing:
            case MarioState.singleJumpLanding:
            case MarioState.doubleJumpLanding:
            case MarioState.tripleJumpLanding:
            case MarioState.rolloutRun:
            case MarioState.wallPush:
            case MarioState.wallShuffle:
            case MarioState.carrying:
            case MarioState.groundSpin:
            case MarioState.sideFlipTurning:
            case MarioState.gettingUpFromSliding:
            case MarioState.bellySlidingFromDive:
                return true;
            case MarioState.slipping:
                return _smsSurfaceSlip; // the game's SLIP_FORE / SLIP_BACK, not the legacy steep-band slide
            default:
                return false;
        }
    }

    /// <summary>
    /// checkGraffitoElec() (MarioMove.cpp 924): on electric goop. Not standing on goop the tick before: the grace timer is set to
    /// GraffitoNoDmgTime (10); while it runs it only counts down. Then, not invincible, standing or running (a WAITING or RUNNING type
    /// status -- never in the air) and no goop footprints (none in the port): ELECTRIC_DAMAGE, with MSD_SE_MA_DAMAGE_ELEC and
    /// MSD_SE_EF_LIGHTNING (the ElectricDamageSound slot).
    /// </summary>
    private void SmsGraffitoElec()
    {
        if (!_smsDirty)
            _smsGraffitoTimer = SmsParams.Mario.GraffitoNoDmgTime;
        if (_smsGraffitoTimer != 0)
        {
            _smsGraffitoTimer--;
            return;
        }
        if (_smsInvincibleTicks > 0 || _health <= 0 || stateOfMario == MarioState.dead)
            return;
        if (!SmsWaitingOrRunningType(stateOfMario))
            return;
        SmsElectricDamageEnter($"electric goop '{_smsSurfaceNode}'");
        if (ElectricDamageSound != null && ElectricDamageSound.Stream != null)
            ElectricDamageSound.Play();
    }

    /// <summary>An electric attacker's hit (MarioReceiveMsg.cpp 419-448: the electro-koopas' message 9, not while invincible):
    /// elecEffect() and MARIO_STATUS_ELECTRIC_DAMAGE. For the enemies to call.</summary>
    public void TakeShock()
    {
        if (!UseSmsPhysics || _smsInvincibleTicks > 0 || _health <= 0 || stateOfMario == MarioState.dead || stateOfMario == MarioState.swimming)
            return;
        if (stateOfMario == MarioState.hurt)
            return; // port-side, as for the knockdowns: not while he is down or already shocked
        SmsElectricDamageEnter("an electric hit");
    }

    /// <summary>changePlayerStatus(MARIO_STATUS_ELECTRIC_DAMAGE, 0): a DEMO-type status -- control locked, nothing moves him. The exec
    /// (electricDamage) does the rest on its first tick.</summary>
    private void SmsElectricDamageEnter(string from)
    {
        if (heldBody != null)
            Anim_DetachPickup();
        ledgePinned = false;
        _smsHangMovingAnim = false;
        _smsLongFallAnim = false;
        _smsFallCancel = false;
        isJumping = false;
        jumpBuffer = 0;
        StopWaistIKHard();
        Vector3 face = _smsFaceValid ? SmsMath.DirFromYaw(_smsFaceYaw) : SmsFacingOrVelocityDir();
        SmsLatchFace(face, 1);
        velocity = Vector3.Zero;
        stateOfMario = MarioState.hurt;
        _smsDownKind = SmsDownKind.Electric;
        _smsDownAir = false;
        _smsDownFwd = 0f;
        _smsElecTicks = 0;
        _smsDownAnim = "";
        if (_smsShockSparks != null)
            _smsShockSparks.Active = true; // elecEffect() every tick: the three emitters live while the ticks come (bind 1)
        if (_smsBodyOverlay != null)
            _smsBodyOverlay.Negative = true; // drawSpecial(): drawLogic() every frame of ELECTRIC_DAMAGE -- the body drawn as its negative
        if (SmsDebugPrint)
            GD.Print($"[SMS elec] ELECTRIC_DAMAGE from {from}: locked for 120 ticks, ma_shock, the sparks {(_smsShockSparks != null ? "from the scene" : "MISSING")}");
    }

    /// <summary>
    /// electricDamage() (MarioAutodemo.cpp 437), one physics frame. The first tick: the shock voice (not ported), ma_shock at 1.0, decHP
    /// (dmggraffitoelec: 1), the rumble (not ported); every tick the sparks and the timer; past 0x78 = 120 ticks: the frame
    /// counter reset, the reaction voice, tremble(5, 2, 0.99, 600) (not ported) and the closing puff, damageExec(the floor, 0 HP, type 3,
    /// ..., 0x3C) = 60 ticks invincible, then WAIT. The HP going means loserExec: ELEC_DOWN, the death in the electric pose.
    /// </summary>
    private void SmsTickElectric(double delta)
    {
        velocity = Vector3.Zero; // a DEMO status: no process moves him
        if (_smsElecTicks == 0)
        {
            SmsDownPlay("ma_shock", 1f);
            SetEyeTexture(hurtEyeTexture ?? sleepingEyeTexture); // ma_shock_tx
            _health = Math.Max(_health - SmsDamageProfile.GraffitoElec.Damage, 0); // decHP(mDmgParamsGraffitoElec.mDamage)
            if (SmsDebugPrint)
                GD.Print($"[SMS elec] -{SmsDamageProfile.GraffitoElec.Damage} HP -> {_health}/{StartingHealth}");
            if (_health <= 0)
            {
                SmsElecDownDeath();
                return;
            }
        }
        int n = SmsUnits.TicksFor(delta, ref _smsTickAccum);
        for (int i = 0; i < n; i++)
        {
            _smsElecTicks++; // elecEffect() every tick: the sparks run; mStatusTimer++
            if (_smsElecTicks > 120)
            {
                if (_smsShockSparks != null)
                    _smsShockSparks.Active = false; // the calls stop: the emitters are invalidated, the live sparks finish
                if (_smsBodyOverlay != null)
                    _smsBodyOverlay.Negative = false; // drawSpecial(): the status leaves ELECTRIC_DAMAGE, the logic pass stops
                _smsShockPuff?.Play(); // elecEndEffect(): ms_moe_fire_off at the centre + 30
                _smsInvincibleTicks = 0x3C; // damageExec(&mFloorHitActor, 0, 3, ..., 0x3C): 0 HP, no knockdown, 60 ticks invincible
                SmsHurtStandUp($"[SMS elec] {_smsElecTicks} ticks: WAIT, invincible 60 ticks, the puff {(_smsShockPuff != null ? "from the scene" : "MISSING")} (the tremble and the reaction voice are not ported)");
                return;
            }
        }
        if (!animPlayer.IsPlaying() || animPlayer.CurrentAnimation != "ma_shock")
            SmsDownPlay("ma_shock", 1f);
    }

    /// <summary>loserExec() during ELECTRIC_DAMAGE (MarioCollision.cpp 225): MARIO_STATUS_ELEC_DOWN -- the death in the electric pose
    /// (elecDowning: ma_shock_down, holding) instead of DOWN_LOSER's ma_die. R respawns as ever.</summary>
    private void SmsElecDownDeath()
    {
        if (_smsShockSparks != null)
            _smsShockSparks.Active = false; // elecEffect() is no longer called; elecEndEffect() never is
        if (_smsBodyOverlay != null)
            _smsBodyOverlay.Negative = false; // drawSpecial(): ELEC_DOWN is not ELECTRIC_DAMAGE -- no logic pass
        stateOfMario = MarioState.dead;
        velocity = Vector3.Zero;
        _smsDownAnim = "";
        _smsDownKind = SmsDownKind.Knockdown;
        if (animTree != null)
            animTree.Active = false;
        animPlayer.SpeedScale = 1f;
        if (animPlayer.HasAnimation("ma_shock_down"))
            animPlayer.Play("ma_shock_down");
        if (SmsDebugPrint)
            GD.Print("[SMS elec] the shock took the last HP: ELEC_DOWN (ma_shock_down)");
    }

    // =====================================================================================
    //  SMS FENCES (FENCE_CATCH / FENCE_JUMP_CATCH / FENCE_MOVE / FENCE_PUNCH, MarioSpecial.cpp 1294-1535) and the ROOF HANG (HANG_ROOF /
    //  WAIT_ROOF / MOVE_ROOF / KICK_ROOF, MarioSpecial.cpp 199-410). Pass 52. One surface attribute does both in the game
    //  (BG_TYPE_CLIMBABLE_FENCE 0x10A, TBGCheckData::isFence): met as a WALL plane it is climbed, met as a ROOF plane it is hung under.
    //  Here the collision body (or a parent up to three levels up) carries metadata sms_fence (any value) or the group sms_fence; the
    //  game's checkWallPlane(pos, yOff, radius) probes (a wall within radius of a point ahead of him, at yOff) are rays along the face
    //  from a little behind him to that reach. Positions are the FEET (the game's mPosition); the body is pinned to the plane each
    //  frame (no MoveAndSlide velocity, no floor snap). The game's objects (the Boo net 0x4000006A: a punch flips him to the far side, a
    //  kick rolls him onto the net; moving fences) are not ported: a plain static fence. Not ported either: the rumbles, the voices, the
    //  wall-kick dust of the jump-off, the fence camera kind.
    // =====================================================================================
    private static bool SmsIsFenceBody(Node start)
    {
        Node n = start;
        for (int depth = 0; n != null && depth < 3; depth++, n = n.GetParent())
            if (n.HasMeta("sms_fence") || n.IsInGroup("sms_fence"))
                return true;
        return false;
    }

    /// <summary>The body of this frame's wall contact (the slide collision whose normal is a wall's), or null.</summary>
    /// <summary>A collider that is a body or an area, not the map: the game's wall checks (checkWallPlane, checkGroundAtJumping) see only
    /// the BG; anything else is a hit actor Mario shoves or bounces. Null (no collider known) is NOT a non-map body.</summary>
    private static bool SmsIsNonMapBody(Node n) => n is RigidBody3D || n is CharacterBody3D || n is Area3D;

    private Node SmsWallColliderNode()
    {
        float cosMax = MathF.Cos(FloorMaxAngle);
        for (int i = 0; i < GetSlideCollisionCount(); i++)
        {
            KinematicCollision3D c = GetSlideCollision(i);
            Vector3 cn = c.GetNormal();
            if (cn.Y < cosMax - 1e-3f && cn.Y > -0.5f)
                return c.GetCollider() as Node;
        }
        return null;
    }

    /// <summary>checkWallPlane(pos + front along the face, yOff, radius): the fence wall the probe would find -- a ray at feet + yOff from 5
    /// units behind him to front + radius along <paramref name="face"/>. The body, or null when there is no fence there.</summary>
    private Node SmsFenceProbe(Vector3 feet, Vector3 face, float frontUnits, float yOffUnits, float radiusUnits, out Vector3 point, out Vector3 normal)
    {
        point = feet;
        normal = -face;
        Vector3 at = feet + Vector3.Up * SmsUnits.UnitsToMetres(yOffUnits);
        Vector3 from = at - face * SmsUnits.UnitsToMetres(5f);
        Vector3 to = at + face * SmsUnits.UnitsToMetres(frontUnits + radiusUnits);
        if (!SmsRay(from, to, out var h))
            return null;
        Node body = h["collider"].AsGodotObject() as Node;
        if (!SmsIsFenceBody(body))
            return null;
        point = (Vector3)h["position"];
        normal = (Vector3)h["normal"];
        return body;
    }

    private float SmsFeetOffset() => GlobalPosition.Y - SmsFeetY();
    private Vector3 SmsFeet() => new Vector3(GlobalPosition.X, SmsFeetY(), GlobalPosition.Z); // the game's mPosition: the ground point under him

    /// <summary>Pressed on the plane: the feet at <paramref name="feet"/>'s height, the body a capsule radius off the plane through
    /// <paramref name="planePoint"/> along <paramref name="n"/> (the game adds 25 units into the wall every tick and the wall pushes him out).</summary>
    private void SmsFencePin(Vector3 feet, Vector3 planePoint, Vector3 n)
    {
        Vector3 nxz = new Vector3(n.X, 0f, n.Z);
        if (nxz.LengthSquared() < 1e-6f)
            nxz = _smsFenceNormal;
        nxz = nxz.Normalized();
        // the point of the plane at his XZ: slide the probe's hit point along the plane to his position
        Vector3 d = feet - planePoint;
        Vector3 onPlane = feet - nxz * d.Dot(nxz);
        Vector3 xz = onPlane + nxz * (capRadiusWorld + 0.02f);
        GlobalPosition = new Vector3(xz.X, feet.Y + SmsFeetOffset(), xz.Z);
        velocity = Vector3.Zero;
        Velocity = Vector3.Zero;
        _smsTrueVyValid = false;
    }

    /// <summary>setAnimation(clip, rate): the clip, driven directly. A clip already set is left running; a looping one (the waits, the
    /// moves) is started again when it ends, a one-shot (the catches, the punch, the kick) is left finished for SmsFenceClipDone().</summary>
    private void SmsFencePlay(string anim, float rate, bool loop = true)
    {
        if (animTree != null)
            animTree.Active = false; // the fence and ladder clips are library-only: driven directly, the tree comes back with the next SetMarioState
        animPlayer.SpeedScale = MathF.Max(rate, 0f);
        if (_smsFenceAnim != anim || (loop && !animPlayer.IsPlaying()))
        {
            _smsFenceAnim = anim;
            if (animPlayer.HasAnimation(anim))
                animPlayer.Play(anim);
        }
    }

    private bool SmsFenceClipDone() => !(animPlayer.IsPlaying() && animPlayer.CurrentAnimation == _smsFenceAnim);

    /// <summary>changePlayerStatus(FENCE_CATCH | FENCE_JUMP_CATCH): the face into the wall (matan(n.z, n.x) + 0x8000), pressed on it,
    /// velocity 0, the catch clip. The grab sound is the FenceCatchSound slot.</summary>
    private void SmsFenceCatchEnter(bool jump, Vector3 wallNormalXZ, Node body, string from)
    {
        Vector3 n = new Vector3(wallNormalXZ.X, 0f, wallNormalXZ.Z);
        if (n.LengthSquared() < 1e-6f)
            return;
        n = n.Normalized();
        if (heldBody != null)
            Anim_DetachPickup();
        Vector3 face = -n;
        _smsFenceNormal = n;
        _smsFenceBody = body;
        ledgePinned = false;
        _smsHangMovingAnim = false;
        _smsLongFallAnim = false;
        _smsFallCancel = false;
        _fluddDashAnimOn = false;
        isJumping = false;
        jumpBuffer = 0;
        StopWaistIKHard();
        SmsLatchFace(face, 1);
        lastFacingDirection = face;
        armature.Rotation = new Vector3(0f, YawFromDir(face), 0f);
        Vector3 feet = SmsFeet();
        Node probe = SmsFenceProbe(feet, face, 25f, 50f, 80f, out Vector3 pt, out Vector3 pn);
        SmsFencePin(feet, probe != null ? pt : feet + face * capRadiusWorld, probe != null ? pn : n);
        stateOfMario = MarioState.fence;
        _smsFence = jump ? SmsFence.JumpCatch : SmsFence.Catch;
        _smsFenceAnim = "";
        SmsFencePlay(jump ? "ma_fence_jcatch" : "ma_fence_catch", 1f, false);
        if (FenceCatchSound != null && FenceCatchSound.Stream != null)
            FenceCatchSound.Play();
        if (SmsDebugPrint)
            GD.Print($"[SMS fence] {(jump ? "FENCE_JUMP_CATCH" : "FENCE_CATCH")} from {from} on '{body?.Name}', normal ({n.X:F2}, {n.Z:F2})");
    }

    /// <summary>checkSwimToHangFence() (MarioSwim.cpp 126): the stick pushed, the wall he swims into a fence, his face within 60 deg of
    /// into it (|face - wallAngle| > 0x5555): 100 units up and FENCE_CATCH.</summary>
    private bool SmsFenceTryCatchSwim(Vector3 wallNormal)
    {
        if (_smsIntendedMag <= 0f)
            return false;
        Node body = SmsWallColliderNode();
        if (!SmsIsFenceBody(body))
            return false;
        Vector3 n = new Vector3(wallNormal.X, 0f, wallNormal.Z);
        if (n.LengthSquared() < 1e-6f)
            return false;
        n = n.Normalized();
        Vector3 face = _smsFaceValid ? SmsMath.DirFromYaw(_smsFaceYaw) : SmsFacingOrVelocityDir();
        if (face.Dot(-n) < MathF.Cos(MathF.PI / 3f)) // diff from the wall's angle beyond 0x5555 = within 60 deg of facing into it
            return false;
        GlobalPosition += Vector3.Up * SmsUnits.UnitsToMetres(100f);
        _smsInWater = false;
        SmsFenceCatchEnter(false, n, body, "the swim");
        return true;
    }

    /// <summary>The fence ended (fenceFootCheck / fenceMove's probe) or the floor met his feet: he turns around (+0x8000), velocity 0, and
    /// falls -- LAND_SAFE_DOWN (passive) from the catch, LANDING (the steerable fall) from the rest.</summary>
    private void SmsFenceLetGo(bool landSafeDown, string why)
    {
        Vector3 away = _smsFenceNormal;
        _smsFenceAnim = "";
        animPlayer.SpeedScale = 1f;
        velocity = Vector3.Zero;
        _smsTrueVyValid = false;
        lastFacingDirection = away;
        SmsLatchFace(away, 2);
        armature.Rotation = new Vector3(0f, YawFromDir(away), 0f);
        _smsHangDropFall = landSafeDown;
        stateOfMario = MarioState.ledgeFall;
        SetMarioState(stateOfMario);
        if (SmsDebugPrint)
            GD.Print($"[SMS fence] let go ({why}): turned around, {(landSafeDown ? "LAND_SAFE_DOWN" : "LANDING")}");
    }

    /// <summary>startJumpWall() + changePlayerStatus(WALL_JUMP): the face turned away, vy 62 (1 if the roof is within reach), 24 out, the
    /// wall-kick state; MSD_SE_MA_FENCE_PUNCH is the FencePunchSound slot.</summary>
    private void SmsFenceJumpOff(string from)
    {
        Vector3 outDir = _smsFenceNormal;
        _smsWallKickDust?.Play(SmsFeetWorld(), SmsMath.YawFromDir(new Vector3(-outDir.X, 0f, -outDir.Z))); // startJumpWall(): the kick's dust off the fence too
        _smsFenceAnim = "";
        animPlayer.SpeedScale = 1f;
        if (FencePunchSound != null && FencePunchSound.Stream != null)
            FencePunchSound.Play();
        float vy = 62f;
        Vector3 feet = SmsFeet();
        if (SmsRay(feet + Vector3.Up * SmsUnits.UnitsToMetres(80f), feet + Vector3.Up * SmsUnits.UnitsToMetres(160f + 62f), out _))
            vy = 1f; // mVel.y + 160 + y >= roofY: the roof is in the way
        LockAirTakeoffDir(outDir);
        float kickOut = SmsUnits.SpeedToMps(24f);
        velocity.X = outDir.X * kickOut;
        velocity.Z = outDir.Z * kickOut;
        velocity.Y = SmsUnits.SpeedToMps(vy);
        GlobalPosition += outDir * 0.05f; // off the plane he was pressed on
        SmsLatchFace(outDir, 2);
        _smsTrueVyValid = false;
        _smsNoLandFrames = 3;
        _smsFallCancel = SmsAir.FallCancelEligible(SmsAir.Launch.WallJump);
        stateOfMario = MarioState.wallJump;
        wallJumpAnimPlayed = true;
        wallJumpAnimFrozen = false;
        SetMarioState(MarioState.wallJump);
        lastFacingDirection = outDir;
        armature.Rotation = new Vector3(0f, WallJumpYawFromDir(outDir), 0f);
        lastWallNormal = outDir;
        wallKickDir = outDir;
        wallKickLock = 0;
        wallRegrabCooldown = 0;
        wallJumpHoldActive = true;
        wallJumpHoldTime = 0f;
        isJumping = true;
        initalJumpHold = true;
        jumpHoldTime = 0f;
        if (SmsDebugPrint)
            GD.Print($"[SMS fence] A ({from}): startJumpWall -- WALL_JUMP vy {vy:F0}, 24 away from the fence");
    }

    /// <summary>The game's stick as fenceMove() reads it: mStickHS16 = 128 x the pad library's axis, 0 within +-7, else 6 taken off.</summary>
    private static float SmsFenceStickCounts(float axis)
    {
        float s16 = MathF.Truncate(128f * axis);
        if (s16 > 7f) return s16 - 6f;
        if (s16 < -7f) return s16 + 6f;
        return 0f;
    }

    /// <summary>jumpProcess(1) case 3 on the fence: hangonCheck() -- the fence wall is there at feet + 30 and gone at feet + 150, the top
    /// (the ground 60 units inside the plane, looked up from feet + 160) is over 100 above the feet: ASCEND (ANIM_HGUP), the climb-up onto it.</summary>
    private bool SmsFenceTryTop(Vector3 feet, Vector3 face)
    {
        if (SmsFenceProbe(feet, face, 25f, SmsParams.Hanging.WallHighUnits, 20f, out _, out _) != null)
            return false; // the fence still reaches past his hands
        if (SmsFenceProbe(feet, face, 25f, SmsParams.Hanging.WallLowUnits, 20f, out Vector3 pt, out Vector3 pn) == null)
            return false;
        Vector3 inside = new Vector3(feet.X, 0f, feet.Z) + face * SmsUnits.UnitsToMetres(60f);
        Vector3 from = new Vector3(inside.X, feet.Y + SmsUnits.UnitsToMetres(160f), inside.Z);
        if (!SmsRay(from, from + Vector3.Down * SmsUnits.UnitsToMetres(160f), out var g))
            return false;
        float topY = ((Vector3)g["position"]).Y;
        if (topY - feet.Y <= SmsUnits.UnitsToMetres(100f))
            return false;
        Vector3 roofFrom = new Vector3(inside.X, topY + 0.02f, inside.Z);
        if (SmsRay(roofFrom, roofFrom + Vector3.Up * SmsUnits.UnitsToMetres(SmsParams.Hanging.HeadroomUnits), out _))
            return false; // no room over the top
        // changePlayerDropping(ASCEND): the ascend from a hang -- the port's hang anchor at the top, then its vault (ma_hgup / the hop)
        Vector3 nxz = new Vector3(_smsFenceNormal.X, 0f, _smsFenceNormal.Z).Normalized();
        _smsFenceAnim = "";
        animPlayer.SpeedScale = 1f;
        SmsEnterLedgeHang(pt, nxz, topY, g["collider"].AsGodotObject());
        _smsHangMovingAnim = false;
        stateOfMario = MarioState.ledgeClimb; // ASCEND = the hang's climb-up (ANIM_HGUP): onto the top
        SetMarioState(stateOfMario);
        ledgeClimbT = 0f;
        if (SmsDebugPrint)
            GD.Print($"[SMS fence] the top is {SmsUnits.MetresToUnits(topY - feet.Y):F0} units above the feet: ASCEND (ma_hgup, the climb-up onto it)");
        return true;
    }

    /// <summary>One physics frame of FENCE_CATCH / FENCE_JUMP_CATCH / FENCE_MOVE / FENCE_PUNCH (fenceCatch / fenceJumpCatch / fenceMove /
    /// fencePunch, MarioSpecial.cpp 1294-1535).</summary>
    private void SmsTickFence(double delta, Vector2 lstick, float camYaw, Vector3 stickDir)
    {
        int n = SmsUnits.TicksFor(delta, ref _smsTickAccum);
        Vector3 face = SmsMath.DirFromYaw(_smsFaceYaw);
        Vector3 feet = SmsFeet();
        bool aPressed = Input.IsActionJustPressed("button_a") || Input.IsActionJustPressed("key_space");
        bool bPressed = Input.IsActionJustPressed("button_b");
        bool stick = stickDir.LengthSquared() > 1e-6f && _smsIntendedMag > 0f; // mInput & 1
        switch (_smsFence)
        {
            case SmsFence.Catch:
            case SmsFence.JumpCatch:
            {
                // fenceFootCheck(): the wall 40 ahead (radius 20) at feet + 50 -- gone: turn around, LAND_SAFE_DOWN
                Node w = SmsFenceProbe(feet, face, 40f, 50f, 20f, out Vector3 pt, out Vector3 pn);
                if (w == null)
                {
                    SmsFenceLetGo(true, "fenceFootCheck: no fence 40 units ahead");
                    return;
                }
                SmsFencePin(feet, pt, pn);
                if (SmsFenceClipDone())
                {
                    // the +-5 settle onto the plane is the pin's business here
                    _smsFence = SmsFence.Move;
                    SmsFencePlay("ma_fence_wait", 1f);
                    if (SmsDebugPrint)
                        GD.Print("[SMS fence] caught: FENCE_MOVE (ma_fence_wait)");
                }
                return;
            }
            case SmsFence.Punch:
            {
                if (aPressed)
                {
                    SmsFenceJumpOff("during the punch");
                    return;
                }
                Node w = SmsFenceProbe(feet, face, 25f, 50f, 80f, out Vector3 pt, out Vector3 pn);
                if (w == null)
                {
                    SmsFenceLetGo(false, "fencePunch: the fence is gone");
                    return;
                }
                SmsFencePin(feet, pt, pn);
                // setAttackRadius(250) / Height(200): the hit lands at clip frame 5 (checkPass(5)) -- the body's method, if it has one
                if (!_smsFencePunchHit && animPlayer.CurrentAnimation == "ma_fence_punch" && animPlayer.CurrentAnimationPosition * 60.0 >= 5.0)
                {
                    _smsFencePunchHit = true;
                    if (_smsFenceBody != null && _smsFenceBody.HasMethod("sms_fence_punched"))
                        _smsFenceBody.Call("sms_fence_punched", this);
                    if (SmsDebugPrint)
                        GD.Print($"[SMS fence] punch lands (frame 5): radius 250, height 200{(_smsFenceBody != null && _smsFenceBody.HasMethod("sms_fence_punched") ? ", the body told" : "")}");
                }
                if (SmsFenceClipDone())
                {
                    _smsFence = SmsFence.Move;
                    SmsFencePlay("ma_fence_wait", 1f);
                }
                return;
            }
            case SmsFence.Move:
            default:
            {
                // the wall 25 ahead, radius 80, at feet + 50 -- gone: turn around, LANDING
                Node w = SmsFenceProbe(feet, face, 25f, 50f, 80f, out Vector3 pt, out Vector3 pn);
                if (w == null)
                {
                    SmsFenceLetGo(false, "fenceMove: no fence 25 units ahead");
                    return;
                }
                _smsFenceBody = w;
                Vector3 nxz = new Vector3(pn.X, 0f, pn.Z);
                if (nxz.LengthSquared() > 1e-6f)
                {
                    _smsFenceNormal = nxz.Normalized();
                    face = -_smsFenceNormal; // mFaceAngle.y = matan(n.z, n.x) + 0x8000 every tick
                    SmsLatchFace(face, 1);
                    lastFacingDirection = face;
                    armature.Rotation = new Vector3(0f, YawFromDir(face), 0f);
                }
                Vector3 newFeet = feet;
                bool moved = false;
                float dv = 0f, dh = 0f;
                if (stick)
                {
                    // 0.015625 x the raw counts x FenceSpeed a tick, up the plane and along the camera's right on it
                    Vector2 pad = SmsStick.PadStick(lstick);
                    float sv = SmsFenceStickCounts(-pad.Y); // Godot's stick Y is down-positive; the game's mStickV is up-positive
                    float sh = SmsFenceStickCounts(pad.X);
                    dv = 0.015625f * sv * SmsParams.Jump.FenceSpeed * n;
                    dh = 0.015625f * sh * SmsParams.Jump.FenceSpeed * n;
                    Vector3 camRight = new Vector3(MathF.Cos(camYaw), 0f, -MathF.Sin(camYaw));
                    Vector3 tangent = camRight - _smsFenceNormal * camRight.Dot(_smsFenceNormal);
                    if (tangent.LengthSquared() < 1e-4f)
                        tangent = Vector3.Up.Cross(face);
                    tangent = tangent.Normalized();
                    Vector3 cand = feet + Vector3.Up * SmsUnits.UnitsToMetres(dv) + tangent * SmsUnits.UnitsToMetres(dh);
                    // the step holds only where the two deeper probes (radius 20 and 140, 25 ahead) still find a fence
                    if (SmsFenceProbe(cand, face, 25f, 50f, 20f, out _, out _) != null && SmsFenceProbe(cand, face, 25f, 50f, 140f, out _, out _) != null)
                    {
                        newFeet = cand;
                        moved = true;
                    }
                }
                else
                {
                    SmsFencePlay("ma_fence_wait", 1f);
                }
                // jumpProcess(1): the floor under the new feet -> LANDING; the top -> ASCEND; a roof within 160 -> clamped under it
                if (dv < 0f && SmsRay(newFeet + Vector3.Up * SmsUnits.UnitsToMetres(10f), newFeet + Vector3.Down * SmsUnits.UnitsToMetres(2f), out var gnd))
                {
                    GlobalPosition = new Vector3(GlobalPosition.X, ((Vector3)gnd["position"]).Y + SmsFeetOffset(), GlobalPosition.Z);
                    SmsFenceLetGo(false, "the floor under his feet (jumpProcess case 1)");
                    return;
                }
                if (dv > 0f && SmsFenceTryTop(newFeet, face))
                    return;
                if (SmsRay(newFeet + Vector3.Up * SmsUnits.UnitsToMetres(80f), newFeet + Vector3.Up * SmsUnits.UnitsToMetres(160f), out var roof))
                {
                    float roofY = ((Vector3)roof["position"]).Y;
                    if (roofY < newFeet.Y + SmsUnits.UnitsToMetres(160f))
                        newFeet.Y = roofY - SmsUnits.UnitsToMetres(160f);
                }
                SmsFencePin(newFeet, pt, pn);
                if (aPressed)
                {
                    SmsFenceJumpOff("on the fence");
                    return;
                }
                if (bPressed)
                {
                    _smsFence = SmsFence.Punch;
                    _smsFencePunchHit = false;
                    SmsFencePlay("ma_fence_punch", 1f, false);
                    if (SmsDebugPrint)
                        GD.Print("[SMS fence] B: FENCE_PUNCH (ma_fence_punch)");
                    return;
                }
                if (stick && moved)
                {
                    // the clip from the displacement a tick: |v| > 5 |h| -> up / down, else left / right (his left = up x face), at rate = the distance
                    Vector3 disp = (newFeet - feet) / n;
                    float v = SmsUnits.MetresToUnits(disp.Y);
                    float h = SmsUnits.MetresToUnits(disp.Dot(Vector3.Up.Cross(face)));
                    float dist = SmsUnits.MetresToUnits(disp.Length());
                    string clip = MathF.Abs(v) > 5f * MathF.Abs(h) ? (v > 0f ? "ma_fence_move_up" : "ma_fence_move_down") : (h > 0f ? "ma_fence_move_l" : "ma_fence_move_r");
                    SmsFencePlay(clip, dist);
                }
                else if (stick)
                {
                    SmsFencePlay("ma_fence_wait", 1f); // pushed against the fence's edge: no step, the wait pose
                }
                return;
            }
        }
    }

    // ------------------------------------------------------------------------------------------------- the roof hang
    /// <summary>jumpProcess() roofCode 4 (doHorizontalPhysics, MarioPhysics.cpp 376): a roof plane that is a fence met by the head
    /// (160 + y > roofY) while rising or level (mVel.y >= 0), the caller's roof bit (the jumps, the hover), hands empty, not on Yoshi ->
    /// HANG_ROOF. Checked after the move: this frame's ceiling contact.</summary>
    private void SmsRoofHangCheck()
    {
        if (!IsOnCeiling() || heldBody != null)
            return;
        if (!(TryGetAirProfile(stateOfMario, out _) || stateOfMario == MarioState.fluddRocket) || stateOfMario == MarioState.hurt || stateOfMario == MarioState.bonk)
            return;
        if (SmsPreMoveVelocity.Y < -0.01f)
            return;
        for (int i = 0; i < GetSlideCollisionCount(); i++)
        {
            KinematicCollision3D c = GetSlideCollision(i);
            Vector3 cn = c.GetNormal();
            if (cn.Y > -0.5f)
                continue;
            Node body = c.GetCollider() as Node;
            if (!SmsIsFenceBody(body))
                continue;
            SmsRoofHangEnter(c.GetPosition().Y, cn, body, stateOfMario.ToString());
            return;
        }
    }

    private void SmsRoofHangEnter(float roofY, Vector3 roofNormal, Node body, string from)
    {
        _smsFenceBody = body;
        _smsRoofY = roofY;
        _smsRoofNormalY = roofNormal.Y;
        _smsRoofTicks = 0;
        _smsRoofArg = 0;
        _smsRoofFwd = 0f;
        ledgePinned = false;
        _smsHangMovingAnim = false;
        _smsLongFallAnim = false;
        _smsFallCancel = false;
        isJumping = false;
        jumpBuffer = 0;
        StopWaistIKHard();
        if (_smsSpinBlur != null)
            _smsSpinBlur.Active = false;
        Vector3 face = _smsFaceValid ? SmsMath.DirFromYaw(_smsFaceYaw) : SmsFacingOrVelocityDir();
        SmsLatchFace(face, 1);
        stateOfMario = MarioState.roofHang;
        _smsRoof = SmsRoof.Hang;
        _smsFenceAnim = "";
        SmsRoofPin();
        SmsFencePlay("ma_ladder_hang_catch", 1f, false);
        if (SmsDebugPrint)
            GD.Print($"[SMS roof] HANG_ROOF from {from} under '{body?.Name}': the head 160 units under the roof at y {SmsUnits.MetresToUnits(roofY):F0}");
    }

    /// <summary>doRoofWaitingProcess(): the feet at roofY - 160, velocity 0.</summary>
    private void SmsRoofPin()
    {
        float feetY = _smsRoofY - SmsUnits.UnitsToMetres(160f);
        GlobalPosition = new Vector3(GlobalPosition.X, feetY + SmsFeetOffset(), GlobalPosition.Z);
        velocity = Vector3.Zero;
        Velocity = Vector3.Zero;
        _smsTrueVyValid = false;
    }

    /// <summary>roofCommonEvents(): B lets go (LANDING, the face kept), A kicks the roof (KICK_ROOF; the Boo net's roll is not ported).</summary>
    private bool SmsRoofCommonEvents(bool aPressed, bool bPressed)
    {
        if (bPressed)
        {
            SmsRoofLetGo("B");
            return true;
        }
        if (aPressed)
        {
            _smsRoof = SmsRoof.Kick;
            SmsFencePlay("ma_ladder_hang_kick", 1f, false);
            if (_smsFenceBody != null && _smsFenceBody.HasMethod("sms_roof_kicked"))
                _smsFenceBody.Call("sms_roof_kicked", this); // receiveMessage(this, 3) to the roof's actor
            if (SmsDebugPrint)
                GD.Print("[SMS roof] A: KICK_ROOF (ma_ladder_hang_kick, radius 200 / height 250)");
            return true;
        }
        return false;
    }

    private void SmsRoofLetGo(string why)
    {
        _smsFenceAnim = "";
        animPlayer.SpeedScale = 1f;
        velocity = Vector3.Zero;
        _smsTrueVyValid = false;
        _smsHangDropFall = false;
        stateOfMario = MarioState.ledgeFall;
        SetMarioState(stateOfMario);
        if (SmsDebugPrint)
            GD.Print($"[SMS roof] let go ({why}): LANDING");
    }

    /// <summary>hangingCheckRoof(pos): 3 = a fence WALL within 50 ahead (-> FENCE_CATCH), 1 = no ground / the gap under 160 / the head
    /// 30 past the roof (he stays, moved), 2 = no roof, not a fence, or the roof 30 above the head (-> LANDING), 0 = in range (pinned).</summary>
    private int SmsHangingCheckRoof(ref Vector3 feet, Vector3 face)
    {
        Node wall = SmsFenceProbe(feet, face, 0f, 50f, 50f, out _, out Vector3 wn);
        if (wall != null)
        {
            Vector3 nxz = new Vector3(wn.X, 0f, wn.Z);
            if (nxz.LengthSquared() > 1e-6f)
                _smsFenceNormal = nxz.Normalized();
            _smsFenceBody = wall;
            return 3;
        }
        float groundY = float.NegativeInfinity;
        if (SmsRay(feet + Vector3.Up * 0.05f, feet + Vector3.Down * 60f, out var g))
            groundY = ((Vector3)g["position"]).Y;
        else
            return 1;
        Vector3 from = new Vector3(feet.X, groundY + SmsUnits.UnitsToMetres(80f), feet.Z);
        if (!SmsRay(from, from + Vector3.Up * 60f, out var r))
            return 2;
        Node roofBody = r["collider"].AsGodotObject() as Node;
        if (!SmsIsFenceBody(roofBody))
            return 2;
        float roofY = ((Vector3)r["position"]).Y;
        if (roofY - groundY <= SmsUnits.UnitsToMetres(160f))
            return 1;
        float space = roofY - (SmsUnits.UnitsToMetres(160f) + feet.Y);
        if (space < -SmsUnits.UnitsToMetres(30f))
            return 1;
        if (space > SmsUnits.UnitsToMetres(30f))
            return 2;
        _smsRoofY = roofY;
        _smsRoofNormalY = ((Vector3)r["normal"]).Y;
        _smsFenceBody = roofBody;
        feet.Y = roofY - SmsUnits.UnitsToMetres(160f);
        return 0;
    }

    /// <summary>One physics frame of HANG_ROOF / WAIT_ROOF / MOVE_ROOF / KICK_ROOF (hangRoof / waitRoof / moveRoof / kickRoof).</summary>
    private void SmsTickRoof(double delta, Vector3 stickDir)
    {
        int n = SmsUnits.TicksFor(delta, ref _smsTickAccum);
        bool aPressed = Input.IsActionJustPressed("button_a") || Input.IsActionJustPressed("key_space");
        bool bPressed = Input.IsActionJustPressed("button_b");
        bool stick = stickDir.LengthSquared() > 1e-6f && _smsIntendedMag > 0f; // mInput & 1 (0x20 = its absence)
        Vector3 face = SmsMath.DirFromYaw(_smsFaceYaw);
        switch (_smsRoof)
        {
            case SmsRoof.Hang:
            {
                // the roof re-found from feet + 80 (checkRoof); mStatusTimer; the stick after 120 ticks -> WAIT_ROOF; the events; the catch clip; pinned
                Vector3 feet = SmsFeet();
                if (SmsRay(feet + Vector3.Up * SmsUnits.UnitsToMetres(80f), feet + Vector3.Up * 60f, out var r))
                    _smsRoofY = ((Vector3)r["position"]).Y;
                _smsRoofTicks += n;
                if (stick && _smsRoofTicks > 120)
                {
                    _smsRoof = SmsRoof.Wait;
                    if (SmsDebugPrint)
                        GD.Print($"[SMS roof] the stick after {_smsRoofTicks} ticks: WAIT_ROOF");
                    return;
                }
                if (SmsRoofCommonEvents(aPressed, bPressed))
                    return;
                SmsFencePlay("ma_ladder_hang_catch", 1f, false);
                SmsRoofPin();
                if (SmsFenceClipDone())
                {
                    _smsRoof = SmsRoof.Wait;
                    if (SmsDebugPrint)
                        GD.Print("[SMS roof] caught: WAIT_ROOF");
                }
                return;
            }
            case SmsRoof.Wait:
            {
                if (SmsRoofCommonEvents(aPressed, bPressed))
                    return;
                if (stick)
                {
                    _smsRoof = SmsRoof.Move;
                    _smsRoofFwd = 0f;
                    goto case SmsRoof.Move;
                }
                SmsFencePlay((_smsRoofArg & 1) != 0 ? "ma_ladder_hang_wait_l" : "ma_ladder_hang_wait_r", 1f);
                SmsRoofPin();
                return;
            }
            case SmsRoof.Move:
            {
                if (SmsRoofCommonEvents(aPressed, bPressed))
                    return;
                Vector3 feet = SmsFeet();
                Vector3 before = feet;
                if (stick)
                {
                    // doRoofMovingProcess(): fwd + 1 a tick to 4.0; the face toward the stick by IConverge(diff, 0, 0x800, 0x800) a tick; the step
                    // -vel x the roof normal's y (down-facing: along the face)
                    Vector3 sd = new Vector3(stickDir.X, 0f, stickDir.Z).Normalized();
                    float yaw = _smsFaceYaw;
                    float want = SmsMath.YawFromDir(sd);
                    for (int i = 0; i < n; i++)
                    {
                        _smsRoofFwd = MathF.Min(_smsRoofFwd + 1f, 4f);
                        yaw = SmsMath.ConvergeAngle(yaw, want, 0x800 * SmsUnits.BamToRad);
                    }
                    face = SmsMath.DirFromYaw(yaw);
                    SmsLatchFace(face, 1);
                    lastFacingDirection = face;
                    armature.Rotation = new Vector3(0f, YawFromDir(face), 0f);
                    Vector3 step = face * SmsUnits.UnitsToMetres(_smsRoofFwd) * (-_smsRoofNormalY) * n;
                    Vector3 cand = feet + new Vector3(step.X, 0f, step.Z);
                    int code = SmsHangingCheckRoof(ref cand, face);
                    if (code != 2)
                        feet = cand;
                    switch (code)
                    {
                        case 2:
                            SmsRoofLetGo("the roof ended / is not a fence / slipped 30 units above the head (hangingCheckRoof 2)");
                            return;
                        case 3:
                            GlobalPosition = new Vector3(feet.X, feet.Y + SmsFeetOffset(), feet.Z);
                            SmsFenceCatchEnter(false, _smsFenceNormal, _smsFenceBody, "the roof met a fence wall (hangingCheckRoof 3)");
                            return;
                    }
                    GlobalPosition = new Vector3(feet.X, feet.Y + SmsFeetOffset(), feet.Z);
                    velocity = Vector3.Zero;
                    Velocity = Vector3.Zero;
                    _smsTrueVyValid = false;
                }
                else
                {
                    _smsRoof = SmsRoof.Wait; // mInput & 0x20: the stick at rest
                    SmsFencePlay((_smsRoofArg & 1) != 0 ? "ma_ladder_hang_wait_l" : "ma_ladder_hang_wait_r", 1f);
                    SmsRoofPin();
                    return;
                }
                float dist = SmsUnits.MetresToUnits((feet - before).Length()) / n * SmsParams.HangRoof.AnmMult;
                string clip = (_smsRoofArg & 1) != 0 ? "ma_ladder_hang_move_l" : "ma_ladder_hang_move_r";
                if (_smsFenceAnim == clip && SmsFenceClipDone())
                {
                    _smsRoofArg = 1 - _smsRoofArg; // the other hand as the clip ends
                    clip = (_smsRoofArg & 1) != 0 ? "ma_ladder_hang_move_l" : "ma_ladder_hang_move_r";
                }
                SmsFencePlay(clip, dist);
                return;
            }
            case SmsRoof.Kick:
            default:
            {
                SmsFencePlay("ma_ladder_hang_kick", 1f, false);
                SmsRoofPin();
                if (SmsFenceClipDone())
                {
                    _smsRoof = SmsRoof.Wait;
                    _smsRoofArg = 0;
                }
                return;
            }
        }
    }

    private void LegacyTakeDamage(Vector3 hitSourcePosition)
    {
        // Don't interrupt if already hurt or dead
        if (stateOfMario == MarioState.hurt || stateOfMario == MarioState.dead)
            return;

        // Reduce health; the console's life meter reads _health every frame
        _health = Mathf.Max(_health - 1, 0);
        GD.Print($"[TakeDamage] Health: {_health}/{StartingHealth}");

        // Die if health is 0
        if (_health <= 0)
        {
            stateOfMario = MarioState.dead;
            velocity = Vector3.Zero;
            SleepStatus(true); // Close eyes
            if (animTree != null)
            {
                animPlayer.Stop(false);
                animTree.Active = true;
            }
            if (_sm != null)
                _sm.Travel("ma_die");
            return;
        }

        // Determine front or back hit using dot product with Mario's facing direction
        Vector3 toHitSource = hitSourcePosition - GlobalPosition;
        toHitSource.Y = 0;
        toHitSource = toHitSource.Normalized();

        // Mario's forward is -Z in local space, rotated by armature yaw
        float yaw = armature.Rotation.Y;
        Vector3 forward = new Vector3(-Mathf.Sin(yaw), 0, -Mathf.Cos(yaw));

        _hitFromFront = forward.Dot(toHitSource) > 0f;

        // Apply knockback away from hit source
        Vector3 knockbackDir = -toHitSource;
        velocity = knockbackDir * HURT_KNOCKBACK;

        _hurtAirborne = !IsOnFloor();
        stateOfMario = MarioState.hurt;

        // Play directional hurt animation
        if (animTree != null)
        {
            animPlayer.Stop(false);
            animTree.Active = true;
        }

        if (_hurtAirborne)
        {
            // Airborne: play air hurt anim, no timer yet (waits for landing)
            velocity.Y = 0f;
            if (_sm != null)
                _sm.Travel(_hitFromFront ? "ma_bkdwn" : "ma_shfdn");
        }
        else
        {
            // Grounded: play ground hurt anim with timer
            _hurtTimer = HURT_DURATION;
            velocity.Y = 0f;
            if (_sm != null)
                _sm.Travel(_hitFromFront ? "ma_sfbdn" : "ma_sffdn");
        }
    }

    public void GainExtraLife()
    {
        _lives++;
        if (GameData.Instance != null)
            GameData.Instance.Lives = _lives;
    }

    public void AddCoin()
    {
        _coins++;
        if (_coins >= 50)
        {
            _coins = 0;
            GainExtraLife();
        }
    }

    /// <summary>The coins' heal: TMario::incHP(1) (a red coin calls it twice).</summary>
    public void HealOneHP() => SmsIncHP(1);

    /// <summary>MSD_SE_SY_HP_RECOVER (incHP: a heal that was not already full): an AudioStreamPlayer anywhere under Mario with the
    /// sound in its Stream; empty = silent.</summary>
    [Export] public AudioStreamPlayer HpRecover;

    /// <summary>TMario::incHP (MarioCollision.cpp 25): under water (isUnderWater(): head below the surface less CanBreathDepth) the
    /// heal goes to the AIR, capped at mMaxAir -- a coin taken while submerged refills a unit of air and the meter steps back up --
    /// otherwise to the health, capped at HPMax; MSD_SE_SY_HP_RECOVER either way when it was not already full (pass 47).</summary>
    public void SmsIncHP(int hp)
    {
        if (UseSmsPhysics && SmsIsUnderWater())
        {
            if (_smsAir >= _smsMaxAir)
                return;
            _smsAir = MathF.Min(_smsAir + hp, _smsMaxAir);
            if (HpRecover != null && HpRecover.Stream != null)
                HpRecover.Play();
            if (SmsDebugPrint)
                GD.Print($"[SMS air] +{hp} air from a heal under water -> {_smsAir:F2}");
            return;
        }
        if (_health >= StartingHealth)
            return;
        _health = Mathf.Min(_health + hp, StartingHealth);
        if (HpRecover != null && HpRecover.Stream != null)
            HpRecover.Play();
    }

    public int AddRedCoin()
    {
        _redCoins++;
        GD.Print($"[RedCoin] {_redCoins} collected");
        return _redCoins;
    }

    public void AddBlueCoin()
    {
        _blueCoins++; // the console holds the star HUD out for 13 s on the change (startBlueCoinGet)
    }

    /// <summary>Waits ShineCountDelay (so the count ticks up mid-cutscene), then
    /// increments. A tween on Mario so it's auto-cancelled if he's freed.</summary>
    private void ScheduleShineCountUp()
    {
        var t = CreateTween();
        t.TweenInterval(ShineCountDelay);
        t.TweenCallback(Callable.From(SmsShineCountUp));
    }

    public void AddShine()
    {
        _shines++; // the console's shine digits flip on the change
    }

    private bool _smsShineFresh = true;
    /// <summary>setShineFlag: true when this shine's flag was clear (the count goes up); a shine with no key is counted for the run only.</summary>
    private bool SmsShineRegister(ShineSprite shine)
    {
        string key = shine.SmsShineKey;
        if (GameData.Instance == null || key == "")
        {
            if (SmsDebugPrint) GD.Print("[SMS shine] no ShineId (a spawned shine without one): counted for the run, not saved");
            return true;
        }
        bool fresh = GameData.Instance.CollectShine(key);
        // 124: the write is the card save's ("Save and ..."); with the prompt off (or no CardSave node) the touch writes at once, as before 124
        bool prompt = SmsShineGetSavePrompt && SmsCardSave.Current != null;
        if (!prompt) GameData.Instance.SaveNow();
        if (SmsDebugPrint) GD.Print($"[SMS shine] flag '{key}' {(fresh ? "set -- the count is now" : "was already set -- the count stays at")} {GameData.Instance.ShineCount} ({(prompt ? "the card save writes" : "saved")})");
        return fresh;
    }
    /// <summary>The count-up 2 s into the demo: one more only for a fresh flag (an empty shine's demo leaves the digits alone).</summary>
    private void SmsShineCountUp() { if (_smsShineFresh) AddShine(); _smsShineFresh = true; }

    // ---------------------------------------------------------------------------------------------------------------
    // TTakeActor (pass 62): holding, carrying and throwing, 1:1. Mario's mHeldObject is heldBody; the object's mHolder is implied.
    // The take comes from the collision check (hitWantToTake, MarioCheckCol.cpp 101): B HELD against a takeable in reach, before the
    // status machine runs, so it beats the dive. The carry is an UPPER state (HOLDING_OBJECT): ma_carry_p over whatever the body does
    // -- the tree's CarryBlend for its clips, SmsUpperPose for the swim set and the other tree-off frames. B again: isThrowStart.
    // ---------------------------------------------------------------------------------------------------------------

    /// <summary>isTakeSituation() (MarioCollision.cpp 86) less the per-object part: no invincibility frames, not a throwing status (the
    /// 0x80000000 flag: PITCHING / PUTTING / JUMP_THROW -- the decomp's '// Airborn?' is a wrong guess, JUMP 0x2000880 and DIVE 0x891
    /// have no such bit), not the 0x10000000 family (bars, wires, fences, hangs, TAKEN, the losers), not CATCH (the belly slide),
    /// hands idle (UPPER_STATE_IDLE), not holding, not held, not in a demo. Plus taking()'s own first line (MarioAction.cpp 8): the
    /// floor within 100 units (mInput & 4, MarioMove.cpp 1699) or the take is a LANDING fall -- so a DIVE with B held into a fruit
    /// near the floor takes it (waitProcess puts his feet on the floor), a belly slide into one does not.</summary>
    private bool SmsCanTakeNow()
    {
        if (heldBody != null || pendingPickup != null || CameraLocked || !SmsFloorWithin(SmsParams.Take.FloorLossUnits))
            return false;
        if (_smsInvincibleTicks > 0)
            return false;
        if (_fluddUpper != SmsUpper.Idle)
            return false;
        switch (stateOfMario)
        {
            case MarioState.idle: case MarioState.walking: case MarioState.running: case MarioState.sprinting: case MarioState.sneak:
            case MarioState.pivot: case MarioState.landing: case MarioState.singleJumpLanding: case MarioState.doubleJumpLanding:
            case MarioState.tripleJumpLanding: case MarioState.rolloutRun: case MarioState.crouch: case MarioState.gettingUpFromSliding:
            case MarioState.diving: case MarioState.singleJumpDive: case MarioState.doubleJumpDive: case MarioState.tripleJumpDive: // DIVE 0x891
            case MarioState.singleJump: case MarioState.doubleJump: case MarioState.tripleJump: // JUMP 0x2000880 .. (no 0x80000000 either)
                return true;
            // bellySlidingFromDive = CATCH (0x800456): excluded by name in isTakeSituation
            default:
                return false;
        }
    }

    /// <summary>The nearest takeable he is touching: the two receive cylinders overlap (THitActor: his DamageRadius 42 x 160 high against the
    /// object's hit radius x height), within mAttackRadius (= HoldRadius 80, setNormalAttackArea) + the object's damage radius of his
    /// position, and within +-60 degrees (0x2aaa) of his face (isTakeSituation 120-128). Bodies in the group "pickable" (his), skipped
    /// when his Fruit says CanBePickedUp false or an SmsTakeable child says CanTake false.</summary>
    private bool SmsFindTakeTarget(out RigidBody3D best)
    {
        best = null;
        if (!SmsCanTakeNow())
            return false;
        Vector3 feet = GlobalPosition;
        Vector3 face = _smsFaceValid ? SmsMath.DirFromYaw(_smsFaceYaw) : SmsFacingOrVelocityDir();
        float cosCone = Mathf.Cos(SmsParams.Take.ConeBam * SmsUnits.BamToRad);
        float marioH = SmsUnits.UnitsToMetres(SmsUnits.MarioHeightUnits);
        float bestD = float.MaxValue;
        foreach (Node n in GetTree().GetNodesInGroup("pickable"))
        {
            if (n is not RigidBody3D rb || !IsInstanceValid(rb) || rb == heldBody || !rb.IsInsideTree() || !SmsTakeable.MayTake(rb))
                continue;
            SmsTakeData d = SmsTakeable.For(rb);
            Vector3 bottom = rb.GlobalPosition - Vector3.Up * SmsBodyHalfHeight(rb, d); // the game's mPosition is the object's ground point
            Vector3 rel = bottom - feet;
            float dxz = new Vector2(rel.X, rel.Z).Length();
            if (dxz > SmsUnits.UnitsToMetres(SmsParams.Mario.HoldRadius + d.HitRadius)) // the hit pair: his standing attack radius (setNormalAttackArea) + the object's damage radius
                continue;
            float objH = SmsUnits.UnitsToMetres(d.HitHeight);
            if (rel.Y + objH < 0f || rel.Y > marioH)
                continue;
            float dist = rel.Length();
            if (dist > SmsUnits.UnitsToMetres(SmsParams.Mario.HoldRadius + d.HitRadius))
                continue;
            if (dxz > 1e-4f && new Vector3(rel.X, 0f, rel.Z).Normalized().Dot(face) < cosCone)
                continue;
            if (dist < bestD)
            {
                bestD = dist;
                best = rb;
            }
        }
        // hitNpc (MarioCheckCol.cpp 95): an NPC carrying LIVE_FLAG_UNK100000 is offered to wantToTakeActor on contact -- the same canTake /
        // isTakeSituation geometry (pass 83). The NPC's origin is its ground point; its hit cylinder is the profile's damage cylinder.
        SmsNpc bestNpc = SmsFindTakeNpc(feet, marioH, face, cosCone, ref bestD);
        if (bestNpc != null)
            best = SmsNpcHoldProxy.Create(bestNpc, this); // the frozen stand-in his RigidBody-typed hold carries; the NPC rides it (getTakingMtx)
        return best != null;
    }

    /// <summary>The liftable NPC nearest his feet inside the isTakeSituation geometry, nearer than <paramref name="bestD"/> (updated).</summary>
    private SmsNpc SmsFindTakeNpc(Vector3 feet, float marioH, Vector3 face, float cosCone, ref float bestD)
    {
        SmsNpc bestNpc = null;
        foreach (SmsNpc npc in SmsNpc.Everyone)
        {
            if (npc == null || !IsInstanceValid(npc) || !npc.IsInsideTree() || !npc.IsNowCanTaken())
                continue;
            Vector3 rel = npc.GlobalPosition - feet;
            float dxz = new Vector2(rel.X, rel.Z).Length();
            if (dxz > SmsUnits.UnitsToMetres(SmsParams.Mario.HoldRadius + npc.HitRadiusUnits)) // the pair Mario-as-attacker: 80 + 100 = 180 u -- keepDistance leaves him at 150, inside it (pass 85)
                continue;
            if (rel.Y + SmsUnits.UnitsToMetres(npc.HitHeightUnits) < 0f || rel.Y > marioH)
                continue;
            float dist = rel.Length();
            if (dist > SmsUnits.UnitsToMetres(SmsParams.Mario.HoldRadius + npc.HitRadiusUnits))
                continue;
            if (dxz > 1e-4f && new Vector3(rel.X, 0f, rel.Z).Normalized().Dot(face) < cosCone)
                continue;
            if (dist < bestD)
            {
                bestD = dist;
                bestNpc = npc;
            }
        }
        return bestNpc;
    }

    /// <summary>TTakeActor::ensureTakeSituation from the held side: is this body what he pends or holds.</summary>
    public bool SmsHoldsOrPends(Node body) => body != null && (heldBody == body || pendingPickup == body);

    /// <summary>The body's half height off its first CollisionShape3D (his fruit are centred RigidBody3Ds; the game's object origin is its
    /// ground point), else half the game's hit height.</summary>
    private static float SmsBodyHalfHeight(RigidBody3D rb, SmsTakeData d)
    {
        foreach (Node c in rb.GetChildren())
        {
            if (c is not CollisionShape3D cs || cs.Shape == null)
                continue;
            float sy = Mathf.Abs(cs.GlobalTransform.Basis.Scale.Y);
            switch (cs.Shape)
            {
                case SphereShape3D s: return s.Radius * sy;
                case BoxShape3D b: return b.Size.Y * 0.5f * sy;
                case CapsuleShape3D cap: return cap.Height * 0.5f * sy;
                case CylinderShape3D cyl: return cyl.Height * 0.5f * sy;
            }
        }
        return SmsUnits.UnitsToMetres(d.HitHeight) * 0.5f;
    }

    /// <summary>mInput &amp; 4 is clear: the floor within this many units under his feet (he is on it, or a ray finds it).</summary>
    /// <summary>The floor within <paramref name="units"/> below his feet, with its height (waitProcess: mPosition.y = mFloorPosition.y).</summary>
    private bool SmsFloorYBelow(float units, out float y)
    {
        y = GlobalPosition.Y;
        var q = PhysicsRayQueryParameters3D.Create(GlobalPosition + Vector3.Up * 0.02f, GlobalPosition - Vector3.Up * SmsUnits.UnitsToMetres(units), CollisionMask,
            new Godot.Collections.Array<Rid> { GetRid() });
        var hit = GetWorld3D().DirectSpaceState.IntersectRay(q);
        if (hit.Count == 0)
            return IsOnFloor();
        y = ((Vector3)hit["position"]).Y;
        return true;
    }

    private bool SmsFloorWithin(float units)
    {
        if (IsOnFloor())
            return true;
        var q = PhysicsRayQueryParameters3D.Create(GlobalPosition + Vector3.Up * 0.02f, GlobalPosition - Vector3.Up * SmsUnits.UnitsToMetres(units), CollisionMask,
            new Godot.Collections.Array<Rid> { GetRid() });
        return GetWorld3D().DirectSpaceState.IntersectRay(q).Count > 0;
    }

    /// <summary>mFloorTriangle->getNormal() for a tick grounded within 4 units: Godot's GetFloorNormal() is zero until MoveAndSlide has
    /// registered the floor -- the first tick after a spawn or a teleport, when only the 4-unit ray (_smsGround4cm) says "floor" -- and a
    /// zero normal reads as a steep slope (a one-frame OIL_SLOPE on goop under the spawn). The ray's own normal stands in; no floor = flat.</summary>
    private Vector3 SmsFloorNormal4cm()
    {
        if (IsOnFloor())
            return GetFloorNormal();
        var q = PhysicsRayQueryParameters3D.Create(GlobalPosition + Vector3.Up * 0.02f, GlobalPosition - Vector3.Up * SmsUnits.UnitsToMetres(4f), CollisionMask,
            new Godot.Collections.Array<Rid> { GetRid() });
        var hit = GetWorld3D().DirectSpaceState.IntersectRay(q);
        return hit.Count > 0 ? ((Vector3)hit["normal"]).Normalized() : Vector3.Up;
    }

    /// <summary>isThrowStart() (MarioRun.cpp 50; the run, brake and turn ticks) and the wait side (MarioWait.cpp 566): B pressed while holding.
    /// An enemy (actor type bit 0x10000000) is always PITCHED; a map object is pitched when mForwardVel > 16, else PUT down if canPut() allows,
    /// else kept. Both are stopCommon states: waitProcess() zeroes his speed at once, the clip plays at 1.0, WAIT at its last frame.</summary>
    private void SmsThrowOrPut()
    {
        float fwd = SmsUnits.MpsToSpeed(new Vector2(velocity.X, velocity.Z).Length());
        bool pitch = _smsTakeData.Kind == SmsTakeable.TakeKind.Enemy || fwd > SmsParams.Take.PitchMinFwd;
        if (!pitch && !SmsCanPut())
        {
            if (SmsDebugPrint) GD.Print($"[SMS take] B at fwd {fwd:F1}: canPut() false (a wall within {_smsTakeData.HitRadius:F0} units ahead or at his feet) -- kept");
            return;
        }
        _smsThrowRunVel = new Vector3(velocity.X, 0f, velocity.Z);
        velocity = Vector3.Zero;
        Velocity = Vector3.Zero;
        _isThrowQueued = pitch;
        _smsActReleased = false;
        _smsJumpThrow = false;
        stateOfMario = MarioState.putDown;
        if (animTree != null)
            animTree.Active = false;
        string clip = pitch ? "ma_throw" : "ma_put";
        if (animPlayer.HasAnimation(clip))
            animPlayer.Play(clip);
        if (SmsDebugPrint)
            GD.Print($"[SMS take] {(pitch ? "PITCHING" : "PUTTING")} the {_smsTakeData.Name} ({_smsTakeData.Kind}) at fwd {fwd:F1}: {(pitch ? "dropObject() at frame 4" : "HIT_MESSAGE_PUT at frame 20")}");
    }

    /// <summary>canPut() (MarioWait.cpp 65): isTouchedOneWall with the object's damage radius 100 units ahead (y + 10) and at his own spot.
    /// The port stands eight horizontal rays of that radius in for the wall-plane test; a static body counts, a body or an area does not.</summary>
    private bool SmsCanPut()
    {
        Vector3 face = _smsFaceValid ? SmsMath.DirFromYaw(_smsFaceYaw) : SmsFacingOrVelocityDir();
        float r = SmsUnits.UnitsToMetres(_smsTakeData.HitRadius);
        Vector3 up = Vector3.Up * SmsUnits.UnitsToMetres(SmsParams.Take.PutProbeUp);
        return !SmsWallWithin(GlobalPosition + face * SmsUnits.UnitsToMetres(SmsParams.Take.PutProbeUnits) + up, r) && !SmsWallWithin(GlobalPosition + up, r);
    }

    private bool SmsWallWithin(Vector3 p, float r)
    {
        var space = GetWorld3D().DirectSpaceState;
        var excl = new Godot.Collections.Array<Rid> { GetRid() };
        if (heldBody != null)
            excl.Add(heldBody.GetRid());
        for (int i = 0; i < 8; i++)
        {
            float a = i * Mathf.Tau / 8f;
            var q = PhysicsRayQueryParameters3D.Create(p, p + new Vector3(Mathf.Sin(a), 0f, Mathf.Cos(a)) * r, CollisionMask, excl);
            q.HitFromInside = true; // isTouchedOneWall counts a point already behind a wall plane within the radius: a ray starting inside the solid reports it
            var hit = space.IntersectRay(q);
            if (hit.Count == 0)
                continue;
            if (hit["collider"].AsGodotObject() is Node col && col is not RigidBody3D && col is not CharacterBody3D && col is not Area3D)
                return true;
        }
        return false;
    }

    /// <summary>checkJumpingThrowStart() (MarioJump.cpp 33) -> MARIO_STATUS_JUMP_THROW: jumpingThrow() (495) plays ANIM_THROW over the ordinary
    /// air physics (doJumping, jumpProcess), checkThrowObject() releases at frame 4; the landing is JUMP_THROW_END (see the landing code).</summary>
    private void SmsStartJumpThrow()
    {
        _smsJumpThrow = true;
        _smsJumpThrowT = 0.0;
        _smsActReleased = false;
        _isThrowQueued = true;
        if (animTree != null)
            animTree.Active = false;
        if (animPlayer.HasAnimation("ma_throw"))
            animPlayer.Play("ma_throw");
        _aerialThrowLockTimer = AERIAL_THROW_LOCK_DURATION; // B's held frame must not read as a dive (the legacy guard)
        if (SmsDebugPrint)
            GD.Print($"[SMS take] JUMP_THROW: the {_smsTakeData.Name} leaves at frame 4 with his air speed x {SmsParams.Take.NormalThrowSpeedRate} added");
    }

    /// <summary>Once a physics frame: the thrown bodies' numbers, the carry pose for the tree-off frames, the jump throw's clock.</summary>
    private void SmsTakeTick(double delta)
    {
        SmsThrownFlight.Tick(delta);
        SmsUpperDamageRunTick(delta);                                                     // pass 110: the fixed upper animation's clock
        if (_smsCarryGraft != null)
        {
            // UPPER_STATE_HOLDING_OBJECT (MarioDraw.cpp 1880): bck 0x4B, ma_carry_p, on the second root over whatever the body plays -- the
            // swim set, a knockdown, the throw until frame 4 (the state clears when PUTTING starts or the object is gone, MarioUpper.cpp 122)
            bool treeOn = animTree != null && animTree.Active;
            bool on = heldBody != null && !treeOn && stateOfMario != MarioState.pickupRaise && !(stateOfMario == MarioState.putDown && !_isThrowQueued);
            _smsCarryGraft.Weight = on ? 1f : 0f;
            if (on)
            {
                _smsCarryGraftT += delta;
                if (_smsCarryGraftLen > 0.0 && _smsCarryGraftT >= _smsCarryGraftLen)
                    _smsCarryGraftT -= _smsCarryGraftLen;
                _smsCarryGraft.Time = _smsCarryGraftT;
            }
        }
        if (_smsJumpThrow)
        {
            _smsJumpThrowT += delta;
            if (!_smsActReleased && heldBody != null && _smsJumpThrowT >= SmsParams.Take.ThrowFrame / 60.0)
            {
                _smsActReleased = true;
                Anim_DetachPickup(); // checkThrowObject(): dropObject()
                SmsPlaySlot(ExertVoice);
            }
            if (stateOfMario == MarioState.swimming)
            {
                _smsJumpThrow = false; // the swim took the body; the object stays held (no dropObject in MarioSwim.cpp)
                _isThrowQueued = false;
            }
            else if (!IsOnFloor() && animPlayer != null && animPlayer.HasAnimation("ma_throw") && animPlayer.CurrentAnimation != "ma_throw"
                     && _smsJumpThrowT < animPlayer.GetAnimation("ma_throw").Length)
            {
                // jumpingThrow(): setAnimation(ANIM_THROW) every tick -- the clip is the body's until he lands
                if (animTree != null)
                    animTree.Active = false;
                animPlayer.Play("ma_throw");
                animPlayer.Seek(_smsJumpThrowT, true);
            }
            else if (IsOnFloor() && stateOfMario != MarioState.putDown)
            {
                _smsJumpThrow = false; // landed through a path the landing code did not see (a ledge, a slope): the clip is whatever the state wants
                _isThrowQueued = false;
            }
        }
    }

    /// <summary>dropObject() (MarioCollision.cpp 78) -> the object's HIT_MESSAGE_THROWN -- TMapObjGeneral::thrown (MapObjGeneral.cpp 109): it leaves
    /// from HIS position (the feet) with ThrowPower x ThrowRate along his face + NormalThrowSpeedRate x his mVel, vy = ThrowVy -- all per 120 Hz
    /// tick (TLiveActor::bind adds mVelocity whole every CUE_MOVE; his mVel, in units a frame, is mixed in raw, as the game does) -- one tick
    /// of lead, and flies on its own gravity and bounce (SmsThrownFlight). Or putting()'s HIT_MESSAGE_PUT -- put() (91): set down
    /// objRadius + 42 + 10 ahead of him at his feet, no velocity. Every drop in the game is one of these two.</summary>
    private void SmsReleaseHeld(bool put)
    {
        var rb = heldBody;
        heldBody = null;
        _smsTakeAttached = false;
        if (rb is SmsNpcHoldProxy smsNpcProxy)
        {
            // TBaseNPC ignores THROWN and PUT: its ensureTakeSituation sees the hold end and releaseTaken_ launches it on its own numbers
            if (SmsDebugPrint) GD.Print($"[SMS take] {(put ? "PUT" : "THROWN")} the NPC {smsNpcProxy.Npc?.Name}: its own releaseTaken_ (ThrowSpeedXZ {SmsParams.Npc.ThrowSpeedXZ} / Y {SmsParams.Npc.ThrowSpeedY} a tick along my facing)");
            smsNpcProxy.Release();
            return;
        }
        rb.TopLevel = false;
        rb.Freeze = false;
        rb.CollisionLayer = heldLayer;
        rb.CollisionMask = heldMask;
        Vector3 face = _smsFaceValid ? SmsMath.DirFromYaw(_smsFaceYaw) : SmsFacingOrVelocityDir();
        face = new Vector3(face.X, 0f, face.Z);
        face = face.LengthSquared() > 1e-6f ? face.Normalized() : Vector3.Forward;
        float halfH = SmsBodyHalfHeight(rb, _smsTakeData);
        if (put)
        {
            float ahead = SmsUnits.UnitsToMetres(_smsTakeData.HitRadius + SmsParams.Mario.DamageRadius + SmsParams.Take.PutGapUnits);
            rb.GlobalPosition = GlobalPosition + face * ahead + Vector3.Up * halfH;
            rb.Sleeping = false;
            rb.SetDeferred("linear_velocity", Vector3.Zero);
            rb.SetDeferred("angular_velocity", Vector3.Zero);
            if (rb is Fruit putFruit) putFruit.SmsPut();   // pass 115: the ball sim takes it back, still
            if (SmsDebugPrint)
                GD.Print($"[SMS take] PUT the {_smsTakeData.Name}: {SmsUnits.MetresToUnits(ahead):F0} units ahead at his feet");
        }
        else
        {
            float power = SmsParams.Take.ThrowPower * _smsTakeData.ThrowRate * ThrowPowerScale; // the game: 2.8 x rate (ThrowPowerScale 1)
            Vector3 run = (ThrowKeepsRunSpeed && !_smsJumpThrow) ? _smsThrowRunVel : new Vector3(velocity.X, 0f, velocity.Z); // the game: mVel (0 after waitProcess on the ground)
            Vector3 vUnits = face * power + new Vector3(SmsUnits.MpsToSpeed(run.X), 0f, SmsUnits.MpsToSpeed(run.Z)) * SmsParams.Take.NormalThrowSpeedRate;
            Vector3 vel = new Vector3(SmsUnits.TickSpeedToMps(vUnits.X), SmsUnits.TickSpeedToMps(_smsTakeData.ThrowVy * ThrowVyScale), SmsUnits.TickSpeedToMps(vUnits.Z)); // per tick, not Mario's SpeedToMps (pass 75)
            rb.GlobalPosition = GlobalPosition + Vector3.Up * halfH + vel / SmsUnits.TicksPerSecond; // mPosition = his; mPosition.add(vel): one tick of lead
            rb.Sleeping = false;
            rb.SetDeferred("linear_velocity", vel);
            rb.SetDeferred("angular_velocity", Vector3.Zero);
            SmsThrownFlight.Begin(rb, _smsTakeData.WithGravity(_smsTakeData.Gravity * ThrowGravityScale)); // the game: the type's gravity (ThrowGravityScale 1)
            if (rb is Fruit thrownFruit) thrownFruit.SmsThrown(vel);   // pass 115: the ball sim flies it on the same launch (Begin skips a sim fruit)
            // it starts inside his cylinder: no shoving him for the first moments (his legacy's guard, kept)
            rb.AddCollisionExceptionWith(this);
            var clearExc = GetTree().CreateTimer(0.6);
            clearExc.Timeout += () =>
            {
                if (IsInstanceValid(rb) && IsInstanceValid(this))
                    rb.RemoveCollisionExceptionWith(this);
            };
            if (SmsDebugPrint)
                GD.Print($"[SMS take] THROWN the {_smsTakeData.Name}: {power:F1} forward (x{ThrowPowerScale}) + {SmsParams.Take.NormalThrowSpeedRate} x his ({SmsUnits.MpsToSpeed(run.X):F1}, {SmsUnits.MpsToSpeed(run.Z):F1}), vy {_smsTakeData.ThrowVy * ThrowVyScale:F1} (x{ThrowVyScale}) -> {vel.Length():F2} m/s; gravity {SmsUnits.TickAccelToMps2(_smsTakeData.Gravity * ThrowGravityScale):F1} m/s2 (x{ThrowGravityScale}), bounce {_smsTakeData.Bounce}");
        }
        if (animTree != null && animTree.Active)
            animTree.Set(CARRY_BLEND_PATH, 0.0f);
    }

    /// <summary>ma_carry_p (the HOLDING_OBJECT upper clip, bck 0x4B) on the chn_chest subtree for the frames the tree does not run.</summary>
    private void SmsTakeSetupGraft()
    {
        if (skeleton == null || animPlayer == null || !animPlayer.HasAnimation("ma_carry_p"))
            return;
        var clip = animPlayer.GetAnimation("ma_carry_p");
        _smsCarryGraft = new SmsUpperPose { Name = "SmsUpper_ma_carry_p" };
        skeleton.AddChild(_smsCarryGraft);
        skeleton.MoveChild(_smsCarryGraft, 0);
        _smsCarryGraft.Bind(skeleton, clip, "chn_chest");
        _smsCarryGraftLen = clip.Length;
        if (SmsDebugPrint)
            GD.Print($"[SMS take] upper graft: ma_carry_p ({clip.Length:F3} s) on {_smsCarryGraft.BoneCount} bones under chn_chest");
    }

    // ---------------------------------------------------------------------------------------------------------------
    // RIDING (pass 63): TMario::checkRideMovement (MarioMove.cpp 1706) at the top of the tick, checkRideReCalc (1750) at the bottom.
    // The game carries a rider by the owner's MATRIX: his position is kept as a point in the actor's local space (unk2F4), put
    // through the actor's current transform every tick (translation and the turn about its origin at once), and his face is turned
    // by the actor's yaw delta; his own move happens in world space after, and the local point is re-measured at the end of the
    // tick. Nothing goes into his velocity, and leaving the actor keeps nothing. The original assembly (QbeRoot asm/Player/
    // MarioMove.s, checkRideMovement) attaches on groundActor != null && !JUMPING && isTouchGround4cm -- the decomp's 'wall !=
    // nullptr' in that test is wrong (r5 = mGroundPlane->mActor is what is compared). The engine's own carry (contact-point
    // velocity, nothing about the pivot, the platform's velocity ADDED on leaving) is switched off.
    // GODOT'S LAG (pass 81, measured): the collision world holds a kinematic deck TWO steps behind its node at his tick (a transform
    // set in a script is flushed to the server after that frame's step and moved in the next), and MoveAndSlide settles him against
    // that -- so the carry puts him on the deck the COLLISION knows (the server's matrix), his move runs consistent with it, and the
    // step from that deck to the DRAWN one (node x local - server x local) is added after the move: he ends the tick where the deck
    // is drawn, his point re-measured against the drawn matrix. A lift whose script runs before his is exact; one that runs after is
    // one step behind at render (as the engine's own carry is).
    // ---------------------------------------------------------------------------------------------------------------

    /// <summary>DEVIATION knob (off = the game): keep the platform's velocity when he leaves it, as Godot's CharacterBody3D did by
    /// default. checkRideMovement sets unk2C0 = null and adds nothing to mVel -- a jump off a moving lift is his own jump.</summary>
    [Export] public bool RideKeepVelocityOnLeave = false;
    private Node3D _smsRideBody;            // unk2C0: the actor he rides (the floor's owner), null = none
    private Vector3 _smsRideLocal;          // unk2F4: his position in the actor's local space
    private float _smsRideYawRef;           // unk30C: the actor's yaw last tick
    private Transform3D _smsRideLastXf;     // the actor's matrix at the last carry (the knob's leave velocity)
    private Vector3 _smsRideVel;            // the platform's velocity at his point over the last tick (the knob only)
    private Transform3D _smsRideXf;         // the collision world's matrix this tick's carry placed him by
    private Vector3 _smsRideShift;          // drawn x local - collision x local: the deck's lag, added after his move (pass 81)
    private bool _smsRideApplied;

    private void SmsRideSetup()
    {
        PlatformFloorLayers = 0;  // the engine's platform carry off: checkRideMovement's own carry below
        PlatformWallLayers = 0;
        PlatformOnLeave = PlatformOnLeaveEnum.DoNothing; // the game keeps nothing; RideKeepVelocityOnLeave adds it back by hand
    }

    /// <summary>A floor whose owner is an actor: an AnimatableBody3D (a lift, a turntable, anything moved by code or an animation with
    /// sync_to_physics), or any body in the group "sms_ride".</summary>
    private static bool SmsIsRideBody(Node n) => n is AnimatableBody3D || (n is PhysicsBody3D && n.IsInGroup("sms_ride"));

    /// <summary>!checkStatusType(MARIO_STATUS_FLAG_JUMPING), plus the states the port pins itself (the ledge and fence tracking is theirs).</summary>
    private bool SmsRideStateOk()
    {
        switch (stateOfMario)
        {
            // the JUMPING-type statuses (a launch frame still reads grounded) and the air dives / rollouts
            case MarioState.singleJump: case MarioState.doubleJump: case MarioState.tripleJump: case MarioState.sideFlip: case MarioState.SpinJump:
            case MarioState.backFlip: case MarioState.diving: case MarioState.singleJumpDive: case MarioState.doubleJumpDive: case MarioState.tripleJumpDive:
            case MarioState.bellyRollout: case MarioState.singleRollout: case MarioState.stomping: case MarioState.bonk:
            case MarioState.groundPoundStartup: case MarioState.groundPoundFalling:
            case MarioState.ledgeHang: case MarioState.ledgeClimb: case MarioState.ledgeHopUp: case MarioState.ledgeDescend: case MarioState.ledgeFall:
            case MarioState.fence: case MarioState.roofHang: case MarioState.swimming: case MarioState.wallSlide: case MarioState.wallJump: case MarioState.wire:
            case MarioState.fluddRocket: case MarioState.treeGrab: case MarioState.treeWait: case MarioState.treeClimb: case MarioState.treeMoveL:
            case MarioState.treeMoveR: case MarioState.treeTopReach: case MarioState.shineGet: case MarioState.dead: case MarioState.talking:
                return false;
            default:
                return true;
        }
    }

    /// <summary>The actor's matrix as the collision world has it: a kinematic body's server transform (two steps behind the node when its
    /// script ran first this frame, one when it runs after -- pass 81's measurement), else the node's.</summary>
    private static Transform3D SmsRideServerXf(Node3D body)
    {
        if (body is AnimatableBody3D ab)
        {
            var st = PhysicsServer3D.BodyGetDirectState(ab.GetRid());
            if (st != null)
                return st.Transform;
        }
        return body.GlobalTransform;
    }

    /// <summary>checkRideMovement's riding branch, at the top of the tick: mPosition = ridingMtx x unk2F4; mFaceAngle.y += the actor's yaw
    /// delta (unk30C). The mount tick (checkRideReCalc only) moves nothing -- that is the bottom's job. Here by the COLLISION world's
    /// matrix, the drawn deck's lead kept aside for after his move (pass 81; see the header).</summary>
    private void SmsRideApply()
    {
        if (_smsRideBody == null)
            return;
        if (!IsInstanceValid(_smsRideBody) || !_smsRideBody.IsInsideTree())
        {
            _smsRideBody = null;
            return;
        }
        Transform3D col = SmsRideServerXf(_smsRideBody);     // the deck the collision world knows: what MoveAndSlide will touch
        Transform3D drawn = _smsRideBody.GlobalTransform;    // the deck as it is drawn this frame (already moved when its script ran first)
        _smsRideXf = col;
        _smsRideApplied = true;
        GlobalPosition = col * _smsRideLocal;                // on the collision's deck: his own move stays consistent with the floor
        Vector3 onDrawn = drawn * _smsRideLocal;
        _smsRideShift = onDrawn - GlobalPosition;            // the deck's lag, put back after his move (SmsRideReCalc)
        float dt = (float)GetPhysicsProcessDeltaTime();
        _smsRideVel = dt > 0f ? (onDrawn - _smsRideLastXf * _smsRideLocal) / dt : Vector3.Zero;
        _smsRideLastXf = drawn;
        float yaw = drawn.Basis.GetEuler().Y;
        float d = SmsMath.WrapAngle(yaw - _smsRideYawRef);
        _smsRideYawRef = yaw;
        if (MathF.Abs(d) > 1e-6f)
        {
            if (_smsFaceValid)
                _smsFaceYaw = SmsMath.WrapAngle(_smsFaceYaw + d);
            lastFacingDirection = lastFacingDirection.Rotated(Vector3.Up, d);
            if (armature != null)
                armature.Rotation = new Vector3(armature.Rotation.X, armature.Rotation.Y + d, armature.Rotation.Z);
        }
    }

    /// <summary>checkRideReCalc at the bottom of the tick (playerControl 2392): on an actor's floor, grounded, not in a jump status -> ride
    /// it (a new actor: mount -- unk2C0, unk30C seeded, no displacement); unk2F4 = inverse(ridingMtx) x mPosition, so his own walking
    /// this tick is folded into the local point. Off the actor -> unk2C0 = null, nothing kept (the knob adds the engine's old carry-over).
    /// A tick that rode in: the deck's lag (SmsRideApply's shift) is added first, so he stands where the deck is drawn and his point is
    /// measured against the drawn matrix (pass 81). The mount measures against the collision's matrix: that is the deck he landed on.</summary>
    private void SmsRideReCalc()
    {
        Node3D body = null;
        if (IsOnFloor() && SmsRideStateOk())
        {
            for (int i = 0; i < GetSlideCollisionCount(); i++)
            {
                var c = GetSlideCollision(i);
                if (c.GetNormal().Dot(UpDirection) > 0.5f && c.GetCollider() is Node3D n && SmsIsRideBody(n))
                {
                    body = n;
                    break;
                }
            }
            if (body == null && SmsRay(GlobalPosition + Vector3.Up * 0.05f, GlobalPosition - Vector3.Up * 0.15f, out var hit)
                && hit["collider"].AsGodotObject() is Node3D fn && SmsIsRideBody(fn))
                body = fn;
        }
        if (body == null)
        {
            if (_smsRideBody != null)
            {
                if (RideKeepVelocityOnLeave)
                    velocity += _smsRideVel; // DEVIATION: the engine's old carry-over
                if (SmsDebugPrint)
                    GD.Print($"[SMS ride] off {_smsRideBody.Name}{(RideKeepVelocityOnLeave ? $" (+ its {_smsRideVel.Length():F2} m/s, the knob)" : " (nothing kept)")}: state {stateOfMario}, floor {IsOnFloor()}");
                _smsRideBody = null;
                _smsRideApplied = false;
            }
            return;
        }
        Transform3D xf;
        if (body == _smsRideBody && _smsRideApplied)
        {
            GlobalPosition += _smsRideShift;   // from the collision's deck to the drawn one: the hover was this step, left in (pass 81)
            xf = body.GlobalTransform;         // the drawn matrix: his own walking is what changed in between
        }
        else
        {
            xf = SmsRideServerXf(body);        // the mount: the deck he landed on, as the collision world had it
            _smsRideBody = body;
            _smsRideLastXf = xf;
            _smsRideYawRef = xf.Basis.GetEuler().Y;
            _smsRideVel = Vector3.Zero;
            if (SmsDebugPrint)
                GD.Print($"[SMS ride] on {body.Name}: his point kept in its local space, turned with it; nothing on leaving (node {body.GlobalPosition}, world {xf.Origin}, his {GlobalPosition})");
        }
        _smsRideApplied = false;
        _smsRideLocal = xf.AffineInverse() * GlobalPosition;
    }

    // ------------------------------------------------------------------------------------------------------------------------
    // WIRE (pass 66): the tightropes. TMapWire / TMapWireActor live in SmsWire.cs; here Mario's WIRE_* statuses (MarioSpecial.cpp
    // 649-1167: getOnWirePosAngle, wireMove, wireWait, wireSWait, the turns, changeWireHanging, the drops, wireReturn, wireHanging,
    // wireRolling), the grab (MarioReceiveMsg.cpp 319-371), the jumps (MarioMove.cpp 608-642, MarioJump.cpp 1022-1035), the rope
    // spring (specMain, 1532-1545). The game's per-frame quantities run per 120 Hz tick at a quarter (SmsUnits.TicksPerFrame); the
    // angles stay in the game's BAM (32768 = a half turn). Sounds (ROPE_JUMP_A/B/C, the swing's, the creaks) are not ported.
    // ------------------------------------------------------------------------------------------------------------------------
    private const float SmsBamPerRad = 32768f / MathF.PI;

    private static float SmsWrapBam(float bam)
    {
        bam %= 65536f;
        if (bam >= 32768f) bam -= 65536f;
        if (bam < -32768f) bam += 65536f;
        return bam;
    }

    private Vector3 SmsWireAlong()
    {
        Vector3 d = new Vector3(_smsWireEnd.X - _smsWireStart.X, 0f, _smsWireEnd.Z - _smsWireStart.Z);
        return d.LengthSquared() > 1e-10f ? d.Normalized() : Vector3.Forward;
    }

    /// <summary>The heading + 0x4000: the game's forward is (sin a, cos a), so a quarter turn on is (cos a, -sin a) = (along.z, -along.x).</summary>
    private static Vector3 SmsWirePerp(Vector3 along) => new Vector3(along.Z, 0f, -along.X);

    /// <summary>The wire actor's hit (MarioReceiveMsg.cpp 319-371), run every frame like the manager's doActorToWire: his position inside a
    /// wire's cube, not held, and not WIRE_JUMP / WIRE_ROLL_JUMP going up nor the let-go fall -> the grab: the tips copied, his ratio,
    /// bounceVel = 0.2 x -vy, sag 0; falling onto it -> WIRE_WAIT on top; rising into it, or from a roll jump or a dive (JUMP_CATCH) ->
    /// hanging under; the ends swapped so his facing agrees with his travel. While held, the wire's hang point is his root every frame
    /// (the V under his feet / at his hands); a stick drop keeps the holder until his position leaves the cube.</summary>
    private void SmsWireCheck()
    {
        if (!UseSmsPhysics)
            return;
        if (_smsRollJumpSpin)
        {
            // keep the roll-jump dismount spinning (ANIM_ROLL, tree off) until he lands or the state changes, then hand back to the tree
            if (IsOnFloor() || stateOfMario != MarioState.singleJump)
            {
                _smsRollJumpSpin = false;
                _smsWireAnim = "";
                if (animTree != null)
                    animTree.Active = true; // the landing SetMarioState also does this; belt-and-suspenders so the clip can't stick on
                SmsWireSwingBlur(false);
            }
            else
            {
                SmsWirePlay(_smsRollJumpClip, 1f, true);
                SmsWireSwingBlur(true);
            }
        }
        if (_smsWireAir != SmsWireAir.None && stateOfMario != MarioState.wire && IsOnFloor() && stateOfMario != MarioState.singleJump)
            _smsWireAir = SmsWireAir.None; // the jumping-type wire statuses end with the landing
        Vector3 root = SmsFeet();
        if (stateOfMario == MarioState.wire)
        {
            if (_smsWireNode != null && IsInstanceValid(_smsWireNode))
                _smsWireNode.SetHang(root);
            return;
        }
        if (_smsWireNode != null)
        {
            // startHangLanding's stick drop sends no message 8: the actor keeps him until his position leaves the cube (doActorToWire)
            if (!IsInstanceValid(_smsWireNode) || !_smsWireNode.InCube(root) || IsOnFloor())
                SmsWireReleaseHolder("left the cube");
            else
                _smsWireNode.SetHang(root);
            return;
        }
        if (stateOfMario == MarioState.dead || stateOfMario == MarioState.talking || stateOfMario == MarioState.shineGet || stateOfMario == MarioState.swimming)
            return;
        SmsWire w = SmsWireMap.CatchAt(root);
        if (w == null)
            return;
        float vy = SmsUnits.MpsToSpeed(velocity.Y);
        if (_smsWireAir == SmsWireAir.Jump && vy > 0f)
            return;
        if (_smsWireAir == SmsWireAir.RollJump && vy > 0f)
            return;
        if (_smsWireAir == SmsWireAir.SafeDown)
            return;
        bool dive = stateOfMario == MarioState.diving || stateOfMario == MarioState.singleJumpDive || stateOfMario == MarioState.doubleJumpDive || stateOfMario == MarioState.tripleJumpDive;
        bool flipDir = _smsWireAir == SmsWireAir.RollJump || dive || vy >= 0f;
        if (flipDir && heldBody != null)
            return; // changeWireHanging() with a held object -> LANDING: he does not hang on (the holder it leaves set is not modelled)
        _smsWireNode = w;
        _smsWireStart = w.StartPoint;
        _smsWireEnd = w.EndPoint;
        _smsWirePosRatio = w.PosInWire(root);
        SmsWireMove(0f);
        _smsWireJumpLatch = false;
        Vector3 along = SmsWireAlong();
        float faceYaw = _smsFaceValid ? _smsFaceYaw : SmsMath.YawFromDir(SmsFacingOrVelocityDir());
        float dirToEnd = SmsMath.WrapAngle(SmsMath.YawFromDir(along) - faceYaw); // (s16)(matan(span.z, span.x) - mFaceAngle.y)
        _smsWireBounceVel = SmsParams.Wire.GrabBounceSeed * -vy;
        _smsWireSag = 0f;
        _smsWireAir = SmsWireAir.None;
        if (flipDir)
        {
            if (dirToEnd > 0f)
                SmsWireSwapEnds();
            SmsWireEnter(SmsWireState.Hanging, $"rising into it (vy {vy:F1}): hanging under");
        }
        else
        {
            if (dirToEnd <= -MathF.PI * 0.5f || dirToEnd > MathF.PI * 0.5f)
                SmsWireSwapEnds();
            SmsWireEnter(SmsWireState.Wait, $"falling onto it (vy {vy:F1}): on top, bounce charge {_smsWireBounceVel:F1}");
        }
    }

    private void SmsWireSwapEnds()
    {
        (_smsWireStart, _smsWireEnd) = (_smsWireEnd, _smsWireStart);
        _smsWirePosRatio = 1f - _smsWirePosRatio;
    }

    /// <summary>message 8 to the holder then mHolder = nullptr: the wire releases with his velocity (its bounce's amplitude).</summary>
    private void SmsWireReleaseHolder(string why)
    {
        if (_smsWireNode != null && IsInstanceValid(_smsWireNode))
            _smsWireNode.Release(SmsUnits.MpsToSpeed(1f) * velocity);
        _smsWireNode = null;
        if (SmsDebugPrint)
            GD.Print($"[SMS wire] let go of the wire ({why})");
    }

    /// <summary>wireMove(dist): his ratio on by dist / the chord's length, no closer than 100 units to a tip; false when it clamped.</summary>
    private bool SmsWireMove(float units)
    {
        float len = SmsUnits.MetresToUnits((_smsWireEnd - _smsWireStart).Length());
        if (len < 1f)
            return false;
        float delta = units / len, margin = SmsParams.Wire.EndMargin / len;
        bool clean = true;
        if (_smsWirePosRatio + delta > 1f - margin)
        {
            _smsWirePosRatio = 1f - margin;
            clean = false;
        }
        if (_smsWirePosRatio + delta < margin)
        {
            _smsWirePosRatio = margin;
            clean = false;
        }
        if (clean)
            _smsWirePosRatio += delta;
        return clean;
    }

    /// <summary>changePlayerStatus(a WIRE status) from off the wire: everything else over, velocity 0, the sub-status, the first pose.</summary>
    private void SmsWireEnter(SmsWireState st, string why)
    {
        if (heldBody != null && st == SmsWireState.Hanging)
            Anim_DetachPickup();
        ledgePinned = false;
        _smsHangMovingAnim = false;
        _smsLongFallAnim = false;
        _smsFallCancel = false;
        _fluddDashAnimOn = false;
        isJumping = false;
        jumpBuffer = 0;
        StopWaistIKHard();
        isSpining(false);
        velocity = Vector3.Zero;
        Velocity = Vector3.Zero;
        _smsTrueVyValid = false;
        _smsWireAngVel = 0f;
        _smsWirePitch = 0f;
        _smsWireRollState = 0;
        _smsWireAnim = "";
        stateOfMario = MarioState.wire;
        _smsWire = st;
        Vector3 along = SmsWireAlong();
        if (st == SmsWireState.Hanging)
            SmsWirePose(SmsWirePerp(along), along, 0f);
        else
            SmsWirePose(along, along, 0f);
        _smsWireNode?.SetHang(SmsFeet()); // the V under him from this frame
        if (SmsDebugPrint)
            GD.Print($"[SMS wire] on the wire: {st} -- {why}; ratio {_smsWirePosRatio:F3}");
    }

    /// <summary>getOnWirePosAngle: his root = the chord point at his ratio, StandHeight (160) under it, plus (0, -mWireSag, 0) turned by
    /// his pitch (the swing) then his control yaw: -sag cos(pitch) up, -sag sin(pitch) along the face. The model faces modelDir, pitched by
    /// the swing about its own X (the game's forward is +Z, the port's -Z: the Godot pitch is the negative).</summary>
    private void SmsWirePose(Vector3 faceDir, Vector3 modelDir, float pitchBam)
    {
        Vector3 p = _smsWireStart + (_smsWireEnd - _smsWireStart) * _smsWirePosRatio;
        p.Y -= SmsUnits.UnitsToMetres(SmsParams.Wire.StandHeight);
        float pitch = pitchBam / SmsBamPerRad;
        float sag = SmsUnits.UnitsToMetres(_smsWireSag);
        p += Vector3.Up * (-sag * MathF.Cos(pitch)) + faceDir * (-sag * MathF.Sin(pitch));
        GlobalPosition = new Vector3(p.X, p.Y + SmsFeetOffset(), p.Z);
        velocity = Vector3.Zero;
        Velocity = Vector3.Zero;
        _smsTrueVyValid = false;
        SmsLatchFace(faceDir, 1);
        lastFacingDirection = modelDir;
        armature.Rotation = new Vector3(-pitch, YawFromDir(modelDir), 0f);
    }

    /// <summary>setAnimation(clip, rate) for the rope clips (library-only, like the fence's): driven directly, the tree back with the next
    /// SetMarioState. A one-shot is left finished for SmsWireClipDone(); reverse plays the clip backwards (setReverseAnimation).</summary>
    private void SmsWirePlay(string anim, float rate, bool loop, bool reverse = false)
    {
        if (animTree != null)
            animTree.Active = false;
        animPlayer.SpeedScale = MathF.Max(rate, 0f);
        if (_smsWireAnim != anim || (loop && !animPlayer.IsPlaying()))
        {
            _smsWireAnim = anim;
            if (animPlayer.HasAnimation(anim))
            {
                Animation a = animPlayer.GetAnimation(anim);
                if (a != null)
                    a.LoopMode = loop ? Animation.LoopModeEnum.Linear : Animation.LoopModeEnum.None;
                // the crossfade is processed in SCALED time, so a fast clip (high SpeedScale -- the rope walk/run) collapses a fixed
                // blend to almost nothing and snaps. Scale the blend by the rate so it stays ~AnimBlend seconds of REAL time.
                float blend = SmsParams.Wire.AnimBlend * MathF.Max(rate, 1f);
                if (reverse)
                    animPlayer.PlayBackwards(anim, blend);
                else
                    animPlayer.Play(anim, blend); // blend from the previous clip so rope transitions don't snap
            }
        }
        SmsWireFluddGraft(); // keep the FLUDD pump pose (grab/spray) over the wire clip while he sprays -- top walk or hang
    }

    /// <summary>FLUDD on the wire runs with the anim tree OFF, so the upper-body pump pose must come from a graft, not the tree's clip.
    /// Force the graft matching the current pump bind -- ma_hgpmp while hanging/swinging (hang clips), ma_pump while walking the top --
    /// so the grab/spray pose blends over the wire's lower body in BOTH stances. SmsFluddUpperBody turns it off when he stops.</summary>
    private void SmsWireFluddGraft()
    {
        if (!SmsFluddUpperBlend)
            return;
        foreach (var kv in _fluddUpperGraft)
            kv.Value.Weight = kv.Key == _fluddPumpBound ? 1f : 0f;
        if (_fluddUpperGraft.TryGetValue(_fluddPumpBound, out var g))
            g.Time = _fluddPumpTime;
    }

    private bool SmsWireClipDone() => !(animPlayer.IsPlaying() && animPlayer.CurrentAnimation == _smsWireAnim);

    /// <summary>roof - floor >= 160 (wireHanging's b, mFloorPosition.x - .y): room to stand back up on the rope.</summary>
    private bool SmsWireHeadroom()
    {
        Vector3 feet = SmsFeet();
        float floorY = SmsFloorYBelow(4000f, out float fy) ? fy : feet.Y - SmsUnits.UnitsToMetres(4000f);
        float roofY = SmsRay(feet + Vector3.Up * 0.02f, feet + Vector3.Up * SmsUnits.UnitsToMetres(4000f), out var hit) ? ((Vector3)hit["position"]).Y : feet.Y + SmsUnits.UnitsToMetres(4000f);
        return SmsUnits.MetresToUnits(roofY - floorY) >= SmsParams.Wire.ReturnHeadroom;
    }

    /// <summary>The swing impulse of the nozzle he is pumping (wireHanging / wireRolling): rocket / turbo 1400, hover 8, the spray -8 (BAM a frame).</summary>
    private float SmsWireRotSpeed() => _fluddNozzle switch
    {
        SmsNozzle.Rocket => SmsParams.Wire.RotSpeedTrgRocket,
        SmsNozzle.Hover => SmsParams.Wire.RotSpeedTrgHover,
        SmsNozzle.Turbo => SmsParams.Wire.RotSpeedTrgTurbo,
        _ => SmsParams.Wire.RotSpeed,
    };

    private bool SmsWirePumping() => _fluddUpper == SmsUpper.Pumping && SmsFluddCanSpray();

    /// <summary>specMain() + the WIRE status of the moment, once a frame (per tick at a quarter): the rope spring first -- bounceVelPrev =
    /// bounceVel; bounceVel -= sag x SwingRate; sag += bounceVel; sag x= SwingBrake; |sag| <= SwingMax -- then the status.</summary>
    private void SmsTickWire(double delta, Vector3 stickDir)
    {
        if (_smsWireNode == null || !IsInstanceValid(_smsWireNode))
        {
            SmsWireLetGo(false, "the wire is gone");
            return;
        }
        int n = SmsUnits.TicksFor(delta, ref _smsTickAccum);
        bool aPressed = Input.IsActionJustPressed("button_a") || Input.IsActionJustPressed("key_space");
        bool bPressed = Input.IsActionJustPressed("button_b");
        bool rHeld = _smsPadDisabledTicks == 0 && Input.IsActionPressed("button_r");   // pass 114: a dead pad pumps nothing
        bool bHeld = _smsPadDisabledTicks == 0 && Input.IsActionPressed("button_b");
        bool stick = stickDir.LengthSquared() > 1e-6f && _smsIntendedMag > 0f; // mInput & 1
        float intendedYaw = stick ? SmsMath.YawFromDir(stickDir) : 0f;
        float q = 1f / SmsUnits.TicksPerFrame;
        float sc = _smsWireNode.RopeSpeedScale; // DEVIATION: his rope-speed dial (1 = the game) scales the walk, hand-over-hand and the swing
        for (int i = 0; i < n; i++)
        {
            // specMain(): the rope spring under him (per tick at a quarter: the velocity's step and the sag's; the damping's root)
            _smsWireBounceVelPrev = _smsWireBounceVel;
            _smsWireBounceVel -= _smsWireSag * SmsParams.Wire.SwingRate * sc * q; // sc stiffens the rope spring -> the bounce/jump fires sooner and higher (his "jumping is slow")
            _smsWireSag += _smsWireBounceVel * q;
            _smsWireSag *= MathF.Pow(SmsParams.Wire.SwingBrake, q);
            _smsWireSag = Mathf.Clamp(_smsWireSag, -SmsParams.Wire.SwingMax, SmsParams.Wire.SwingMax);
            bool first = i == 0;
            Vector3 along = SmsWireAlong();
            float alongYaw = SmsMath.YawFromDir(along);
            Vector3 perp = SmsWirePerp(along);
            switch (_smsWire)
            {
                case SmsWireState.Wait:
                {
                    // wireWait: A latches; the jump goes when the rope is at or above its rest (sag <= 0); B drops to the hang; the stick
                    // within 45 deg of the heading walks (0.1 x the counts a frame; ROPE_RUN above 16 counts, else ROPE_WALK, at 0.05 x
                    // the counts), beyond it turns sideways (L / R); no stick: ROPE_WAIT
                    SmsWirePose(along, along, 0f);
                    if (first && aPressed)
                        _smsWireJumpLatch = true;
                    if (_smsWireJumpLatch && _smsWireSag <= 0f)
                    {
                        SmsWireJumpOff(false);
                        return;
                    }
                    if (first && bPressed)
                    {
                        _smsWireBounceVel = SmsParams.Wire.DropBounceVel;
                        _smsWire = SmsWireState.WaitToHang;
                        _smsWireAnim = "";
                        break;
                    }
                    if (stick)
                    {
                        float diff = SmsMath.WrapAngle(alongYaw - intendedYaw);
                        if (diff > -MathF.PI * 0.25f && diff < MathF.PI * 0.25f)
                        {
                            float rate = SmsParams.Wire.WalkAnimRatePerMag * _smsIntendedMag * sc;
                            if (SmsWireMove(SmsParams.Wire.WalkSpeedPerMag * _smsIntendedMag * q * sc))
                                SmsWirePlay(_smsIntendedMag > SmsParams.Wire.RunMagThreshold ? "ma_rope_run" : "ma_rope_walk", rate, true);
                            else
                                SmsWirePlay("ma_rope_wait", 1f, true);
                        }
                        if (diff < -MathF.PI * 0.25f)
                        {
                            _smsWire = SmsWireState.WaitToSWaitL;
                            _smsWireAnim = "";
                            break;
                        }
                        if (diff > MathF.PI * 0.25f)
                        {
                            _smsWire = SmsWireState.WaitToSWaitR;
                            _smsWireAnim = "";
                            break;
                        }
                    }
                    else
                        SmsWirePlay("ma_rope_wait", 1f, true);
                    break;
                }
                case SmsWireState.SWait:
                {
                    // wireSWait: sideways on the rope -- the model along it, the control face a quarter turn on; A latches, the jump
                    // needs sag < 0 and adds 5 x -bounceVelPrev (no base: the game's quirk); the stick within 90 deg of the heading
                    // turns back (L), beyond it swaps the ends and turns back (R); the drop's input bit (0x10000) is never set by the pad
                    SmsWirePose(perp, along, 0f);
                    if (first && aPressed)
                        _smsWireJumpLatch = true;
                    if (_smsWireJumpLatch && _smsWireSag < 0f)
                    {
                        SmsWireJumpOff(true);
                        return;
                    }
                    if (stick)
                    {
                        float diff = SmsMath.WrapAngle(intendedYaw - alongYaw);
                        if (diff > -MathF.PI * 0.5f && diff < MathF.PI * 0.5f)
                            _smsWire = SmsWireState.SWaitToWaitL;
                        else
                        {
                            SmsWireSwapEnds();
                            _smsWire = SmsWireState.SWaitToWaitR;
                        }
                        _smsWireAnim = "";
                        break;
                    }
                    SmsWirePlay("ma_rope_swait", 1f, true);
                    break;
                }
                case SmsWireState.WaitToSWaitL:
                case SmsWireState.WaitToSWaitR:
                {
                    bool right = _smsWire == SmsWireState.WaitToSWaitR;
                    SmsWirePose(right ? -perp : perp, along, 0f);
                    SmsWirePlay(right ? "ma_rope_wtosw_r" : "ma_rope_wtosw", 1f, false);
                    if (SmsWireClipDone())
                    {
                        _smsWire = SmsWireState.SWait;
                        _smsWireAnim = "";
                        if (right)
                            SmsWireSwapEnds(); // wireWaitToSWaitR: the ends swapped as the turn lands
                    }
                    break;
                }
                case SmsWireState.SWaitToWaitL:
                case SmsWireState.SWaitToWaitR:
                {
                    bool right = _smsWire == SmsWireState.SWaitToWaitR;
                    SmsWirePose(right ? -perp : perp, along, 0f);
                    SmsWirePlay(right ? "ma_rope_wtosw_r" : "ma_rope_wtosw", 1f, false, reverse: true); // setReverseAnimation
                    if (SmsWireClipDone())
                    {
                        _smsWire = SmsWireState.Wait;
                        _smsWireAnim = "";
                    }
                    break;
                }
                case SmsWireState.WaitToHang:
                case SmsWireState.SWaitToHang:
                {
                    // the drop clip (ROPE_WHG / ROPE_SWHG) carries the body from above the root to below it; at its end: hanging (or a
                    // plain fall with a held object)
                    bool side = _smsWire == SmsWireState.SWaitToHang;
                    if (side)
                        SmsWirePose(along, along, 0f);
                    else
                        SmsWirePose(perp, along, 0f);
                    SmsWirePlay(side ? "ma_rope_swhg" : "ma_rope_whg", 1f, false);
                    if (SmsWireClipDone())
                    {
                        if (heldBody == null)
                        {
                            _smsWire = SmsWireState.Hanging;
                            _smsWireAnim = "";
                        }
                        else
                        {
                            SmsWireLetGo(false, "drop to hang with a held object: LANDING");
                            return;
                        }
                    }
                    break;
                }
                case SmsWireState.Return:
                {
                    SmsWirePose(along, along, 0f);
                    SmsWirePlay("ma_rope_return", 1f, false);
                    if (SmsWireClipDone())
                    {
                        _smsWire = SmsWireState.Wait;
                        _smsWireAnim = "";
                    }
                    break;
                }
                case SmsWireState.Hanging:
                {
                    // wireHanging: A with headroom -> the climb (bounceVel 5); B -> let go (message 8, the safe fall); the stick: toward the
                    // end (within -45 .. +75 deg of the heading) 3 units a frame hand over hand (ROPE_HMOVR), toward the start (beyond
                    // -135 / +105) ROPE_HMOVL, across one way (-135 .. -45) the climb, across the other (75 .. 105) the drop; no stick and
                    // the pump spraying -> the swing: angVel kicked 2 x RotStop toward the nozzle's impulse, plus the impulse -> ROLLING
                    _smsWireAngVel = 0f;
                    _smsWirePitch = 0f;
                    SmsWirePose(perp, along, 0f);
                    if (first && aPressed && SmsWireHeadroom())
                    {
                        _smsWireBounceVel = SmsParams.Wire.DropBounceVel;
                        _smsWire = SmsWireState.Return;
                        _smsWireAnim = "";
                        break;
                    }
                    if (first && bPressed)
                    {
                        SmsWireReleaseHolder("B: let go");
                        SmsWireStartHangLanding("B while hanging");
                        return;
                    }
                    if (stick)
                    {
                        float diff = SmsMath.WrapAngle(alongYaw - intendedYaw);
                        float d45 = MathF.PI * 0.25f, d75 = MathF.PI * 0x3555 / 32768f, d105 = MathF.PI * 0x4AAA / 32768f, d135 = MathF.PI * 0.75f;
                        if (diff > -d45 && diff < d75)
                            SmsWirePlay(SmsWireMove(SmsParams.Wire.HandMoveSpeed * q * sc) ? "ma_rope_hmovr" : "ma_rope_hgwat", 1f, true);
                        if (diff < -d135 || diff > d105)
                            SmsWirePlay(SmsWireMove(-SmsParams.Wire.HandMoveSpeed * q * sc) ? "ma_rope_hmovl" : "ma_rope_hgwat", 1f, true);
                        if (diff >= -d135 && diff <= -d45)
                        {
                            _smsWireBounceVel = SmsParams.Wire.DropBounceVel;
                            _smsWire = SmsWireState.Return;
                            _smsWireAnim = "";
                            break;
                        }
                        if (diff >= d75 && diff <= d105)
                        {
                            SmsWireStartHangLanding("the stick across: the drop (the holder stays until he leaves the cube)");
                            return;
                        }
                        break;
                    }
                    if (SmsWirePumping())
                    {
                        float rotSp = SmsWireRotSpeed();
                        _smsWireAngVel += (rotSp > 0f ? 2f : -2f) * SmsParams.Wire.RotStop;
                        _smsWireAngVel += rotSp * sc;
                        _smsWire = SmsWireState.Rolling;
                        _smsWireAnim = "";
                        if (SmsDebugPrint)
                            GD.Print($"[SMS wire] the pump swings him: ROLLING, angular speed {_smsWireAngVel:F0} BAM a frame ({_fluddNozzle})");
                        break;
                    }
                    SmsWirePlay("ma_rope_hgwat", 1f, true);
                    break;
                }
                case SmsWireState.Rolling:
                {
                    // wireRolling: the pendulum. A arms the release: swinging one way (angVel < 0) through (-0x2000, max - 0x2000] ->
                    // ROLL_JUMP 0, the other (angVel > 0) through [0x6000 - max, 0x6000) -> ROLL_JUMP 1. The stick still moves him along.
                    // The pump adds its impulse; gravity -RotGravity x sin(angle); R held brakes x RotBrake; |angVel| <= RotSpeedMax;
                    // angle += angVel; sag = 0.1 x |angVel|, bounceVel 0. Settled (|angle| < 0x200, |angVel| < RotStop) -> hanging. The
                    // model faces a quarter turn on (ANIM_HANG, the ledge hang's two-handed grip) and pitches with the swing.
                    float initial = _smsWirePitch;
                    if (first && aPressed)
                        _smsWireRollState |= 1;
                    float max = SmsParams.Wire.RotSpeedMax * sc;
                    if ((_smsWireRollState & 1) != 0 && _smsWireAngVel < 0f && _smsWirePitch > -SmsParams.Wire.RollReleaseWindow && _smsWirePitch <= max - SmsParams.Wire.RollReleaseWindow)
                    {
                        SmsWireRollJumpOff(0);
                        return;
                    }
                    if ((_smsWireRollState & 1) != 0 && _smsWireAngVel > 0f && _smsWirePitch >= SmsParams.Wire.RollJumpAngleBack - max && _smsWirePitch < SmsParams.Wire.RollJumpAngleBack)
                    {
                        SmsWireRollJumpOff(1);
                        return;
                    }
                    if (stick)
                    {
                        float diff = SmsMath.WrapAngle(alongYaw - intendedYaw);
                        float d45 = MathF.PI * 0.25f, d75 = MathF.PI * 0x3555 / 32768f, d105 = MathF.PI * 0x4AAA / 32768f, d135 = MathF.PI * 0.75f;
                        if (diff > -d45 && diff < d75)
                            SmsWireMove(SmsParams.Wire.HandMoveSpeed * q * sc);
                        if (diff < -d135 || diff > d105)
                            SmsWireMove(-SmsParams.Wire.HandMoveSpeed * q * sc);
                    }
                    if (SmsWirePumping())
                        _smsWireAngVel += SmsWireRotSpeed() * q * sc;
                    _smsWireAngVel -= SmsParams.Wire.RotGravity * MathF.Sin(_smsWirePitch / SmsBamPerRad) * q;
                    if (bHeld)
                        // Hold B to wind the swing down (Super Whirl Jump: "hold B to stop swinging before he jumps"). The settle check
                        // below returns him to HANGING once he's slow near the bottom -- he STAYS on the rope. Without B the loop conserves.
                        _smsWireAngVel *= MathF.Pow(SmsParams.Wire.RotBrake, q);
                    _smsWireAngVel = Mathf.Clamp(_smsWireAngVel, -max, max);
                    _smsWirePitch = SmsWrapBam(_smsWirePitch + _smsWireAngVel * q);
                    _smsWireSag = SmsParams.Wire.SwingRadiusCoeff * MathF.Abs(_smsWireAngVel); // the loop's radius (DEVIATION coeff so the circle isn't huge at the raised speed cap)
                    _smsWireBounceVel = 0f;
                    SmsWireSwingBlur(MathF.Abs(_smsWireAngVel) > SmsParams.Wire.SwingBlurSpeed); // the trailing streak during a fast swing / loop (hip-drop blur, not the spin-jump rings)
                    if (initial < -0x4000 && _smsWirePitch > 0x4000)
                        _smsWireRollState |= 2; // over the top (the full-loop sounds' flag)
                    else if (initial < _smsWirePitch)
                        _smsWireRollState &= ~2;
                    if (_smsWirePitch > -SmsParams.Wire.SettleAngle && _smsWirePitch < SmsParams.Wire.SettleAngle
                        && _smsWireAngVel > -SmsParams.Wire.RotStop && _smsWireAngVel < SmsParams.Wire.RotStop)
                    {
                        _smsWirePitch = 0f;
                        _smsWireAngVel = 0f;
                        _smsWireBounceVel = 0f;
                        _smsWireSag = 0f;
                        _smsWireRollState = 0;
                        SmsWireSwingBlur(false);
                        if (heldBody == null)
                        {
                            _smsWire = SmsWireState.Hanging;
                            _smsWireAnim = "";
                            SmsWirePose(perp, along, 0f);
                            break;
                        }
                        SmsWireLetGo(false, "the swing settled with a held object: LANDING");
                        return;
                    }
                    SmsWirePose(perp, perp, _smsWirePitch);
                    SmsWirePlay("ma_hang", 1f, true);
                    break;
                }
            }
        }
    }

    /// <summary>wireWait's jump (wireSWait's for the sideways stance): message 8, WIRE_JUMP -- setPlayerJumpSpeed(0.25, 42) with fwd 0 then
    /// setPlayerVelocity(0), vy += JumpMult x -bounceVel when the rope is moving up, + JumpBase 25 (the sideways jump: 5 x -bounceVelPrev,
    /// no base); the clip ANIM_JUMP, weak air steering (0.01), no fall cancel; it lands in SEC_JUMP_SLIP (a triple is next).</summary>
    private void SmsWireJumpOff(bool fromSWait)
    {
        Vector3 along = SmsWireAlong();
        Vector3 face = fromSWait ? SmsWirePerp(along) : along;
        float vy = SmsParams.Wire.WireJumpVy;
        if (!fromSWait)
        {
            if (_smsWireBounceVel < 0f)
                vy -= SmsParams.Wire.JumpMult * _smsWireBounceVel;
            vy += SmsParams.Wire.JumpBase;
        }
        else if (_smsWireBounceVelPrev < 0f)
            vy -= 5f * _smsWireBounceVelPrev;
        _smsWireJumpLatch = false;
        SmsWireExit();
        velocity = new Vector3(0f, SmsUnits.SpeedToMps(vy), 0f);
        SmsLatchFace(face, 2);
        lastFacingDirection = face;
        armature.Rotation = new Vector3(0f, YawFromDir(face), 0f);
        _smsTrueVyValid = false;
        _smsNoLandFrames = 3;
        _smsFallCancel = false;
        _smsWireAir = SmsWireAir.Jump;
        stateOfMario = MarioState.singleJump;
        SetMarioState(stateOfMario);
        SmsWireReleaseHolder($"the jump: vy {vy:F1} (bounce {_smsWireBounceVel:F1}, prev {_smsWireBounceVelPrev:F1})");
    }

    /// <summary>WIRE_ROLL_JUMP (MarioMove.cpp 620-642): power = angVel x JumpRate; arg 0: vy = power sin(0xE000), fwd = power -cos(0xE000)
    /// along the control face (a quarter turn on from the rope); arg 1 the same at 0x6000. The clip (wireJumping, MarioJump.cpp 1023-1028):
    /// ANIM_GIANT_ROLLING for arg 0, ANIM_ROLL for arg 1 -- the two rolls turn opposite ways, each with the spin that launched it; it lands
    /// in SEC_JUMP_SLIP and never clash-crashes.</summary>
    private void SmsWireRollJumpOff(int arg)
    {
        Vector3 along = SmsWireAlong();
        Vector3 face = SmsWirePerp(along);
        float power = _smsWireAngVel * SmsParams.Wire.JumpRate; // decomp jumpPower = unkF6 x mJumpRate: the launch is PROPORTIONAL to the built-up spin (momentum), so the more you whirl the farther you fly. Bounded only by the spin's own cap (RotSpeedMax), not a separate clamp
        float ang = (arg == 0 ? SmsParams.Wire.RollJumpAngleFwd : SmsParams.Wire.RollJumpAngleBack) / SmsBamPerRad;
        float vy = power * MathF.Sin(ang);
        float fwd = power * -MathF.Cos(ang);
        SmsWireExit();
        float mps = SmsUnits.SpeedToMps(fwd);
        velocity = new Vector3(face.X * mps, SmsUnits.SpeedToMps(vy), face.Z * mps);
        SmsLatchFace(face, 2);
        lastFacingDirection = face;
        armature.Rotation = new Vector3(0f, YawFromDir(face), 0f);
        _smsTrueVyValid = false;
        _smsNoLandFrames = 3;
        _smsFallCancel = false;
        _smsWireAir = SmsWireAir.RollJump;
        stateOfMario = MarioState.singleJump;
        SetMarioState(stateOfMario);
        // The dismount spins through the air: ma_giant_rolling (arg 0) / ma_roll (arg 1), as wireJumping sets them. The tree has no roll
        // nodes, so _sm.Travel fell through to the plain jump (ma_tjmp1); drive the library clip directly (tree off), looped, and keep it
        // going until he lands (SmsWireCheck). The other roll is the fallback for a library without one.
        string[] rollClips = arg == 0 ? new[] { "ma_giant_rolling", "ma_roll", "ma_jump_rolling", "ma_roll_jump" }
                                      : new[] { "ma_roll", "ma_giant_rolling", "ma_jump_rolling", "ma_roll_jump" };
        _smsRollJumpClip = System.Array.Find(rollClips, c => animPlayer.HasAnimation(c));
        _smsRollJumpSpin = _smsRollJumpClip != null;
        if (_smsRollJumpSpin)
        {
            SmsWirePlay(_smsRollJumpClip, 1f, true);
            isSpining(true); // the giant-roll's speed blur carries into the dismount
        }
        SmsWireReleaseHolder($"the roll jump {arg}: power {power:F1} -> vy {vy:F1} fwd {fwd:F1}, spin {(_smsRollJumpSpin ? _smsRollJumpClip : "none (no roll clip)")}");
    }

    /// <summary>startHangLanding(WIRE_HANG_LAND_SAFE_DOWN): velocity 0, 60 units back along the face, onto the ground within 100 units or
    /// 100 down, then the let-go fall (landSafeDown: ANIM_LAND into LAND_SLIP). The port's LAND_SAFE_DOWN is the ledgeFall with
    /// _smsHangDropFall; the wire's own flag keeps it from re-grabbing on the way down.</summary>
    private void SmsWireStartHangLanding(string why)
    {
        Vector3 face = _smsFaceValid ? SmsMath.DirFromYaw(_smsFaceYaw) : SmsFacingOrVelocityDir();
        SmsWireExit();
        Vector3 feet = SmsFeet() - face * SmsUnits.UnitsToMetres(60f);
        float y = feet.Y;
        if (SmsFloorYBelow(4000f, out float groundY) && groundY >= feet.Y - SmsUnits.UnitsToMetres(100f))
            y = groundY;
        else
            y -= SmsUnits.UnitsToMetres(100f);
        GlobalPosition = new Vector3(feet.X, y + SmsFeetOffset(), feet.Z);
        velocity = Vector3.Zero;
        _smsTrueVyValid = false;
        lastFacingDirection = face;
        SmsLatchFace(face, 2);
        armature.Rotation = new Vector3(0f, YawFromDir(face), 0f);
        _smsHangDropFall = true;
        _smsWireAir = SmsWireAir.SafeDown;
        stateOfMario = MarioState.ledgeFall;
        SetMarioState(stateOfMario);
        if (SmsDebugPrint)
            GD.Print($"[SMS wire] off the wire into the safe fall ({why})");
    }

    /// <summary>Off the wire into a plain fall (changePlayerStatus(LANDING) in the game's held-object branches, or the wire vanishing).</summary>
    private void SmsWireLetGo(bool landSafeDown, string why)
    {
        Vector3 face = _smsFaceValid ? SmsMath.DirFromYaw(_smsFaceYaw) : SmsFacingOrVelocityDir();
        SmsWireExit();
        SmsWireReleaseHolder(why);
        velocity = Vector3.Zero;
        _smsTrueVyValid = false;
        _smsHangDropFall = landSafeDown;
        _smsWireAir = landSafeDown ? SmsWireAir.SafeDown : SmsWireAir.None;
        lastFacingDirection = face;
        SmsLatchFace(face, 2);
        armature.Rotation = new Vector3(0f, YawFromDir(face), 0f);
        stateOfMario = MarioState.ledgeFall;
        SetMarioState(stateOfMario);
        if (SmsDebugPrint)
            GD.Print($"[SMS wire] off the wire ({why}): {(landSafeDown ? "LAND_SAFE_DOWN" : "LANDING")}");
    }

    private void SmsWireExit()
    {
        _smsWireAnim = "";
        animPlayer.SpeedScale = 1f;
        _smsWirePitch = 0f;
        _smsWireAngVel = 0f;
        _smsWireRollState = 0;
        SmsWireSwingBlur(false); // drop the swing trail (the roll-jump re-enables it for the dismount spin)
    }

    /// <summary>The giant-swing trail: the hip-drop / ground-pound blur streak (ms_m_blur3), NOT the spin-jump rings.</summary>
    private void SmsWireSwingBlur(bool on)
    {
        if (_smsHipBlur == null)
            return;
        _smsHipBlur.Active = on;
        _smsHipBlur.LifeFrames = on ? SmsParams.Wire.TrailLifeFrames : 10; // longer streak on the wire; back to the hip-drop's own length (BEM1 life 10) when off
    }

    private void Respawn()
    {
        SmsFluddOnRespawn(); // a full tank, the drops gone
        SmsCameraWarpBehind(); // the game's camera starts behind him as a stage load's does (pass 53); an open L camera is dropped with it (pass 68)
        _health = StartingHealth;
        _smsGameOver = false;
        _smsLoserFalling = false;
        SmsAirReset();
        _smsSwimAnim = "";
        animPlayer.SpeedScale = 1f;
        velocity = Vector3.Zero;
        SleepStatus(false); // Open eyes
        stateOfMario = MarioState.idle;
        SetMarioState(MarioState.idle);
    }

    private void SetMarioState(MarioState state)
    {
        // Safety check - if AnimationTree isn't set up, fall back to AnimationPlayer
        if (_sm == null || animTree == null)
        {
            // Fallback to AnimationPlayer for basic animations
            string fallbackAnim = state switch
            {
                MarioState.idle => "ma_wait",
                MarioState.talking => "ma_t_wait",
                MarioState.sneak => "ma_sstep",
                MarioState.running => "ma_run1",
                MarioState.walking => "ma_run1",
                MarioState.sprinting => "ma_run2",
                MarioState.pivot => "ma_pivot",
                _ => "ma_wait",
            };
            if (animPlayer.CurrentAnimation != fallbackAnim)
                animPlayer.Play(fallbackAnim);
            return;
        }

        // Diving would throw the object (not implemented yet), so no carry blend
        bool isDiving = (
            state == MarioState.diving
            || state == MarioState.singleJumpDive
            || state == MarioState.doubleJumpDive
            || state == MarioState.tripleJumpDive
        );

        // Always activate AnimationTree when SetMarioState is called.
        // Sleep animations bypass SetMarioState entirely (they use animPlayer directly),
        // so this is safe — it also ensures we wake up correctly when movement starts.
        if (animTree != null)
        {
            if (_smsDamageWaitPhase != 0 && animPlayer.IsPlaying())
                _smsDamageWaitPos = animPlayer.CurrentAnimationPosition; // the pant resumes here if this is idle again
            animPlayer.Stop(false); // stop animPlayer so it doesn't fight animTree
            animTree.Active = true;
        }

        // Apply carry blend to ALL animations when holding an object (except diving)
        if (animTree != null && animTree.Active)
        {
            if ((heldBody != null && !isDiving) || SmsFluddUpperBlend)
            {
                animTree.Set(CARRY_BLEND_PATH, 1.0f); // Full carry blend
            }
            else
            {
                animTree.Set(CARRY_BLEND_PATH, 0.0f); // No carry blend
            }
        }

        // Travel to the appropriate animation in the state machine
        switch (state)
        {
            case MarioState.idle:
                if (UseSmsPhysics && _smsTalking)
                {
                    // readBillboard (MarioAutodemo.cpp 63): setAnimation(ANIM_T_WAIT, 1.0) -- the talk wait, a library-only clip like the
                    // damage wait below (pass 87; 82-86 left the WAIT clip on). SmsTalkEnd puts the tree back.
                    if (animTree != null)
                        animTree.Active = false;
                    animPlayer.SpeedScale = 1f;
                    if (animPlayer.CurrentAnimation != "ma_t_wait")
                        animPlayer.Play("ma_t_wait");
                }
                else if (UseSmsPhysics && SmsWantsDamageWait())
                {
                    // waiting(): mHealth <= 3 -> ANIM_DAMAGE_WAIT_START once, then ANIM_DAMAGE_WAIT. Library-only clips, driven
                    // directly like ma_t_wait below; SmsDamageWaitTick chains the two and lets go when something else takes over.
                    if (animTree != null)
                        animTree.Active = false;
                    animPlayer.SpeedScale = 1f;
                    SetEyeTexture(tiredEyeTexture ?? awakeEyeTexture); // heavy-lidded: he is tired
                    if (_smsDamageWaitPhase == 0)
                    {
                        animPlayer.Play("ma_damage_wait_start");
                        _smsDamageWaitPhase = 1;
                    }
                    else
                    {
                        animPlayer.Play(_smsDamageWaitPhase == 1 ? "ma_damage_wait_start" : "ma_damage_wait");
                        animPlayer.Seek(_smsDamageWaitPos, true); // idle re-entered mid-pant: carry on, do not restart
                    }
                }
                else
                {
                    _smsDamageWaitPhase = 0;
                    _sm.Travel("ma_wait");
                }
                break;
            case MarioState.talking:
                // ma_t_wait is present in the AnimationPlayer library but not as
                // an AnimationTree state, so play its forced loop directly.
                if (animTree != null)
                    animTree.Active = false;
                if (animPlayer.CurrentAnimation != "ma_t_wait")
                    animPlayer.Play("ma_t_wait");
                break;
            case MarioState.pivot:
                _sm.Travel("ma_pivot");
                break;
            case MarioState.sneak:
                _sm.Travel(UseSmsPhysics && _smsRunBlendReady ? SmsGaitClip() : "ma_sstep");
                break;
            case MarioState.walking:
            case MarioState.running:
            case MarioState.sprinting:
                // doRunningAnimation(): ANIM_TURBO_DASH while mForwardVel >= DashMax - 1 (the dash), RUN1 / RUN2 otherwise. The grounded
                // classification calls this EVERY frame while he runs, after SmsGroundTick's travel to ma_turbo_dash -- and the state
                // machine honours only the last travel() of the frame, so until 2026-09-27 the dash clip never played: ma_run2 ran at
                // the doubled rate with the water-gun waist lean on top (MarioWaistCtrl applies for RUN1 / RUN2, not TURBO_DASH), and
                // any steering twisted the shoulders to the 22 deg cap (0.5 x dYaw x 80 saturates from 100 BAM a tick).
                // Under SMS the clip follows the SPEED, not the stick: doRunningAnimation picks SSTEP below Walk2Soft (back to the run above
                // Soft2Walk), TURBO_DASH at the dash, else RUN2 blended with RUN1 by its rate -- ma_runblend, a Blend2 of the two clips.
                _sm.Travel(UseSmsPhysics && _smsRunBlendReady ? SmsGaitClip()
                    : _fluddDashAnimOn && _fluddTurboAnimReady ? "ma_turbo_dash" : state == MarioState.sprinting ? "ma_run2" : "ma_run1");
                break;
            case MarioState.singleJump:
                // Just left a slip for airborne (slid off the edge, or the
                // escape hop) — ma_slpla plays for that beat instead of the
                // normal jump pose.
                _sm.Start(_fluddBroadJump && _fluddTurboAnimReady ? "ma_broad_jump" : slipAirLaunchTimer > 0f ? "ma_slpla" : "ma_jump"); // BROAD_JUMP: ANIM_BROAD_JUMP
                break;
            case MarioState.doubleJump:
                // Double jump: ma_2jmp1 while rising, ma_2jmp2 while falling
                if (Velocity.Y > 0)
                    _sm.Travel("ma_2jmp1");
                else
                    _sm.Travel("ma_2jmp2");
                break;
            case MarioState.tripleJump:
                _sm.Travel("ma_demo_gate_out_rolling_get");
                break;
            case MarioState.singleJumpLanding:
            case MarioState.doubleJumpLanding:
            case MarioState.landing:
                _sm.Travel("ma_laend");
                break;
            case MarioState.tripleJumpLanding:
                _sm.Travel("ma_tjmp2");
                break;
            case MarioState.diving:
            case MarioState.singleJumpDive:
                _sm.Travel("ma_sldct");
                break;
            case MarioState.doubleJumpDive:
            case MarioState.tripleJumpDive:
                _sm.Travel("ma_sldct");
                break;
            case MarioState.singleRollout:
                _sm.Travel("ma_roll_jump");
                break;
            case MarioState.bellySlidingFromDive:
                _sm.Travel("ma_slpbk");
                break;
            case MarioState.bellyRollout:
                _sm.Travel("ma_roll");
                break;
            case MarioState.gettingUpFromSliding:
                _sm.Travel("ma_lost");
                break;
            case MarioState.sideFlip:
                _sm.Travel("ma_tjmp1");
                break;
            case MarioState.sideFlipTurning:
                _sm.Travel("ma_trned");
                break;
            case MarioState.SpinJump:
            case MarioState.groundSpin:
                _sm.Travel("ma_spin_p");
                break;
            case MarioState.crouch:
                _sm.Travel("ma_sqwat");
                break;
            case MarioState.bonk:
                _sm.Travel("ma_bkdwn");
                break;
            case MarioState.backFlip:
                _sm.Travel("ma_jump_rolling");
                break;
            case MarioState.rolloutRun:
                _sm.Travel("ma_run2");
                break;
            case MarioState.wallSlide:
                _sm.Travel("ma_wsld");
                break;

            case MarioState.slipping:
                // Start, not Travel — ma_slpla/ma_slpbk/ma_slip are only
                // graph-connected in the ground-pound/belly-rollout
                // recovery neighborhood (they're reused for that too).
                // Travel() pathfinds through the graph to reach them, which
                // from a jump/wall-slide state routes through whatever
                // unrelated recovery animation is on that path — the "weird
                // animation" flash. Start() jumps straight there.
                _sm.Start(_slipFacingUphill ? "ma_slpbk" : "ma_slip");
                break;
            case MarioState.wallJump:
                _sm.Travel("ma_wjmp");
                break;
            case MarioState.ledgeFall:
                _sm.Travel("ma_land");
                break;
            case MarioState.fluddRocket:
                _sm.Travel("ma_land"); // rocketing(): setAnimation(ANIM_LAND); the pump is the upper-body blend
                break;
            case MarioState.ledgeHang:
                _sm.Travel("ma_hang");
                break;
            case MarioState.ledgeClimb:
                _sm.Travel("ma_hgup");
                break;
            case MarioState.ledgeHopUp:
                _sm.Travel("ma_hgjmp");
                break;
            case MarioState.ledgeDescend:
                // ma_hgdwn is in the AnimationPlayer library but not in the tree: drive it directly (the next SetMarioState
                // re-enables the tree)
                if (animTree != null)
                    animTree.Active = false;
                animPlayer.Play("ma_hgdwn");
                break;
            case MarioState.pickupFail:
                _sm.Travel("ma_get_fail");
                break;
            case MarioState.pickupRaise:
                // Keep AnimationPlayer for pickup animations
                if (animTree != null)
                    animTree.Active = false;
                animPlayer.Play("ma_raise");
                break;
            case MarioState.carrying:
                // Carrying uses AnimationTree with carry blend
                if (animTree != null)
                {
                    animTree.Active = true;
                    animTree.Set(CARRY_BLEND_PATH, 1.0f);
                }
                _sm.Travel("ma_wait");
                break;
            case MarioState.putDown:
                // Keep AnimationPlayer for putdown animations
                if (animTree != null)
                    animTree.Active = false;
                animPlayer.Play("ma_put");
                break;
            case MarioState.shineGet:
                // Keep AnimationPlayer for the shine-get cutscene animation
                if (animTree != null)
                    animTree.Active = false;
                animPlayer.SpeedScale = 1f;   // 116c: setAnimation(ANIM_DEMO_SHINE_GET, 1.0) -- the run's SpeedScale must not leak in (it ran the
                                              // 6.97 s clip out in 1.7 s and froze the LAST frame, the shine at the chest, under the raised shine)
                animPlayer.Play("ma_demo_shine_get");
                break;
            case MarioState.wallPush:
                _sm.Travel("ma_push");
                break;
            case MarioState.wallShuffle:
                // Wall shuffle direction is handled dynamically in TickGroundWall
                // Don't override it here - keep using AnimationPlayer
                if (animTree != null)
                    animTree.Active = false;
                break;
            case MarioState.groundPoundStartup:
                if (UseSmsPhysics && _smsHipsrInTree)
                    _sm.Travel("ma_hipsr"); // no path to it: a teleport; the clip holds its last frame for the rest of the hover, as setAnimation(ANIM_HIPSR) does
                else
                {
                    if (animTree != null)
                        animTree.Active = false;
                    animPlayer.Play("ma_hipsr");
                }
                break;
            case MarioState.groundPoundFalling:
                _sm.Travel("ma_hipat");
                break;
            case MarioState.groundPoundLanding:
                _sm.Travel("ma_hiped");
                break;
            case MarioState.treeGrab:
                if (animTree != null)
                    animTree.Active = false;
                if (animPlayer.CurrentAnimation != "ma_tree_catch")
                    animPlayer.Play("ma_tree_catch");
                break;
            case MarioState.treeWait:
                if (animTree != null)
                    animTree.Active = false;
                if (animPlayer.CurrentAnimation != "ma_tree_wait")
                    animPlayer.Play("ma_tree_wait");
                break;
            case MarioState.treeClimb:
                if (animTree != null)
                    animTree.Active = false;
                if (animPlayer.CurrentAnimation != "ma_tree_climb")
                    animPlayer.Play("ma_tree_climb");
                break;
            case MarioState.treeMoveL:
                if (animTree != null)
                    animTree.Active = false;
                if (animPlayer.CurrentAnimation != "ma_tree_move_l")
                    animPlayer.Play("ma_tree_move_l");
                break;
            case MarioState.treeMoveR:
                if (animTree != null)
                    animTree.Active = false;
                if (animPlayer.CurrentAnimation != "ma_tree_move_r")
                    animPlayer.Play("ma_tree_move_r");
                break;
            case MarioState.treeTopReach:
                if (animTree != null)
                    animTree.Active = false;
                if (animPlayer.CurrentAnimation != "ma_tjmp2")
                    animPlayer.Play("ma_tjmp2");
                break;
        }
    }
    // ======================================================================================
    //  SMS 1:1 physics bridge (see assets/Sms/SmsPhysics.cs for the ported math and sources)
    //
    //  Mario.cs keeps ownership of the state machine, animation, VFX and collision; these
    //  methods only decide the NUMBERS: velocity in m/s derived from the Sunshine model
    //  (scalar forward speed along a face angle, 120 Hz sub-ticks, per-tick gravity).
    //  Godot moves once per physics frame, so the vertical speed handed to MoveAndSlide is
    //  the sub-tick AVERAGE (exact displacement) and the post-gravity value is kept in
    //  _smsTrueVy for the next frame.
    // ======================================================================================

    /// <summary>The launched jumps (JUMP, the second and third, the rotate jumps, the back flip, the wall kick): the states the
    /// LedgeLandWhileRising deviation applies to.</summary>
    private static bool SmsIsJumpState(MarioState s) =>
        s == MarioState.singleJump || s == MarioState.doubleJump || s == MarioState.tripleJump
        || s == MarioState.SpinJump || s == MarioState.sideFlip || s == MarioState.backFlip || s == MarioState.wallJump;

    private static bool SmsStateSteers(MarioState s) =>
        s == MarioState.singleJump || s == MarioState.doubleJump || s == MarioState.tripleJump
        || s == MarioState.SpinJump || s == MarioState.sideFlip || s == MarioState.backFlip
        || s == MarioState.wallJump || s == MarioState.diving || s == MarioState.singleJumpDive
        || s == MarioState.doubleJumpDive || s == MarioState.tripleJumpDive
        || s == MarioState.singleRollout || s == MarioState.bellyRollout
        || s == MarioState.stomping || s == MarioState.ledgeHopUp;

    /// <summary>
    /// Who gets doJumping()'s stick control in the air: the launched states, plus a plain fall off an edge. In the game
    /// running() -> walkProcess() 0 -> LANDING, and landing() is jumpingBasic(LAND_SLIP, ANIM_LAND, 3): the same air control
    /// as a jump, the ledge bit, B dives. Not the LAND_SAFE_DOWN drop after letting go of a ledge (jumpProcess(0): no stick).
    /// The landing and step rules keep SmsStateSteers (ledgeFall's landing has its own fall-speed proof).
    /// </summary>
    private bool SmsAirSteers(MarioState s) =>
        SmsStateSteers(s) || (s == MarioState.ledgeFall && !_smsHangDropFall);

    private static SmsAir.Launch SmsLaunchKindFor(MarioState s)
    {
        switch (s)
        {
            case MarioState.doubleJump: return SmsAir.Launch.SecondJump;
            case MarioState.tripleJump: return SmsAir.Launch.UltraJump;
            case MarioState.SpinJump: return SmsAir.Launch.RotateJump;
            case MarioState.sideFlip: return SmsAir.Launch.UTurnJump;
            case MarioState.backFlip: return SmsAir.Launch.BackJump;
            case MarioState.wallJump: return SmsAir.Launch.WallJump;
            case MarioState.diving:
            case MarioState.singleJumpDive:
            case MarioState.doubleJumpDive:
            case MarioState.tripleJumpDive: return SmsAir.Launch.JumpCatchAir;
            case MarioState.singleRollout:
            case MarioState.bellyRollout: return SmsAir.Launch.RotateBroadJump;
            case MarioState.stomping: return SmsAir.Launch.Trample1;
            case MarioState.groundPoundFalling: return SmsAir.Launch.HipDrop;
            default: return SmsAir.Launch.Jump;
        }
    }

    private Vector3 SmsFacingOrVelocityDir()
    {
        Vector3 f = new Vector3(lastFacingDirection.X, 0f, lastFacingDirection.Z);
        if (f.LengthSquared() < 1e-6f)
            f = new Vector3(velocity.X, 0f, velocity.Z);
        if (f.LengthSquared() < 1e-6f)
            f = SmsMath.DirFromYaw(_smsFaceYaw);
        return f.Normalized();
    }

    /// <summary>The way the model looks this frame: the armature's yaw read back through the convention every writer uses for it
    /// (armature.Rotation.Y = YawFromDir(world direction)); the velocity, or the face, when there is no armature.</summary>
    private Vector3 SmsModelFacing() => armature != null ? SmsMath.DirFromYaw(armature.Rotation.Y) : SmsFacingOrVelocityDir();

    /// <summary>Set the SMS face angle from a world XZ direction. source: 1 = ground, 2 = air.</summary>
    private void SmsLatchFace(Vector3 dir, int source)
    {
        dir.Y = 0f;
        if (dir.LengthSquared() < 1e-6f)
            dir = SmsFacingOrVelocityDir();
        _smsFaceYaw = SmsMath.YawFromDir(dir.Normalized());
        _smsFaceValid = true;
        _smsFaceSource = source;
        _smsLatchedFacing = lastFacingDirection;
    }

    /// <summary>
    /// Apply setStatusToJumping's launch table to the current velocity: vy from the table, forward
    /// speed scaled/replaced per move, along the current facing (lastFacingDirection).
    /// </summary>
    private void SmsLaunch(SmsAir.Launch kind)
    {
        Vector3 velXZ = new Vector3(velocity.X, 0f, velocity.Z);
        float speed = velXZ.Length();
        // On the ground SMS velocity always points along mFaceAngle, so the takeoff face IS the velocity
        // direction. The U-turn jump faces the stick (their code has already set lastFacingDirection to
        // it) and the backflip faces the way the model looks while moving backwards.
        Vector3 faceDir = (kind == SmsAir.Launch.UTurnJump || kind == SmsAir.Launch.BackJump || speed <= 0.5f)
            ? SmsFacingOrVelocityDir()
            : velXZ / speed;
        float sign = (speed > 1e-4f && velXZ.Dot(faceDir) < 0f) ? -1f : 1f;
        float fwd = SmsUnits.MpsToSpeed(sign * speed);
        float vy = SmsUnits.MpsToSpeed(velocity.Y);
        SmsAir.ApplyLaunch(kind, ref fwd, ref vy);
        if (_smsFootPrintTimer > SmsParams.Graffito.FootPrintTimerMax / 2)
        {
            // setStatusToJumping (MarioMove.cpp 432): fresh off the paint (the footprint window's first half) a takeoff stamps a 250-unit goop disc
            SmsPollutionMap.Pollute(new Vector3(GlobalPosition.X, SmsFeetY(), GlobalPosition.Z), SmsParams.Dirty.PolSizeJump);
        }
        if (_smsSinkTimer > 0f)
        {
            // setStatusToJumping() (MarioMove.cpp 657): isSinking() -> vy and fwd x the sink jump rate (0.5 flat as shipped); the depth bleeds (1 - t) x SinkTime x SinkRecover
            float sinkScale = SmsSinkScale(SmsParams.Graffito.SinkJumpRateMin, SmsParams.Graffito.SinkJumpRateMax);
            vy *= sinkScale;
            fwd *= sinkScale;
            _smsSinkTimer -= (1f - _smsSinkTimer / SmsParams.Graffito.SinkTime) * (SmsParams.Graffito.SinkTime * SmsParams.Graffito.SinkRecover);
            if (_smsSinkTimer < 0f)
                _smsSinkTimer = 0f;
        }
        _smsFallCancel = SmsAir.FallCancelEligible(kind);
        if (SmsDebugPrint)
            GD.Print($"[SMS launch] {kind}: fwd {fwd:F1} ({SmsUnits.SpeedToMps(fwd):F1} m/s) vy {vy:F1} cancel {_smsFallCancel}");
        float mps = SmsUnits.SpeedToMps(fwd);
        velocity.X = faceDir.X * mps;
        velocity.Z = faceDir.Z * mps;
        velocity.Y = SmsUnits.SpeedToMps(vy);
        SmsLatchFace(faceDir, 2);
        _smsTrueVyValid = false;
        _smsNoLandFrames = 3; // see the landing rule: floor snapping still reports the ground just left
    }

    /// <summary>
    /// MARIO_STATUS_JUMP_CATCH ("dive jump"): fwd = min(15 + fwd, 48) along <paramref name="dir"/>;
    /// from the ground vy = 20, from the air vy is left alone. Replaces the fixed DIVE_SPEED_XZ.
    /// </summary>
    private void SmsSetDiveVelocity(Vector3 dir, bool fromGround)
    {
        dir.Y = 0f;
        dir = dir.LengthSquared() > 1e-6f ? dir.Normalized() : SmsFacingOrVelocityDir();
        if (!UseSmsPhysics)
        {
            velocity.X = dir.X * DIVE_SPEED_XZ;
            velocity.Z = dir.Z * DIVE_SPEED_XZ;
            return;
        }
        // Sunshine dives along mFaceAngle: in the air that is the takeoff face (the stick does not redirect
        // a dive), on the ground it is the way he is running (or looking, when standing).
        Vector3 velXZ0 = new Vector3(velocity.X, 0f, velocity.Z);
        if (!fromGround && _smsFaceValid && _smsFaceSource == 2)
            dir = SmsMath.DirFromYaw(_smsFaceYaw);
        else if (velXZ0.Length() > 0.5f)
            dir = velXZ0.Normalized();
        lastFacingDirection = dir;
        float fwd = SmsUnits.MpsToSpeed(velXZ0.Length());
        float vy = SmsUnits.MpsToSpeed(velocity.Y);
        SmsAir.ApplyLaunch(fromGround ? SmsAir.Launch.JumpCatchGround : SmsAir.Launch.JumpCatchAir, ref fwd, ref vy);
        _smsFallCancel = false;
        float mps = SmsUnits.SpeedToMps(fwd);
        velocity.X = dir.X * mps;
        velocity.Z = dir.Z * mps;
        velocity.Y = SmsUnits.SpeedToMps(vy);
        SmsLatchFace(dir, 2);
        _smsTrueVyValid = false;
        _smsNoLandFrames = 3;
    }

    /// <summary>
    /// A pressed during the belly slide (catching()): above ClashSpeed (40) it is MARIO_STATUS_ROTATE_BROAD_JUMP
    /// (vy 38, fwd 55, fall-cancellable); otherwise MARIO_STATUS_CATCH_STOP, a vy-30 hop that keeps the slide
    /// speed and rolls him to his feet (not cancellable).
    /// </summary>
    private void SmsRolloutLaunch()
    {
        Vector3 velXZ = new Vector3(velocity.X, 0f, velocity.Z);
        float speed = velXZ.Length();
        Vector3 dir = speed > 0.5f ? velXZ / speed : SmsFacingOrVelocityDir();
        float fwd = SmsUnits.MpsToSpeed(speed);
        float vy = SmsUnits.MpsToSpeed(velocity.Y);
        bool broad = fwd > SmsRollJumpMinSpeed;
        SmsAir.Launch kind = broad ? SmsAir.Launch.RotateBroadJump : SmsAir.Launch.CatchStop;
        SmsAir.ApplyLaunch(kind, ref fwd, ref vy);
        stateOfMario = broad ? MarioState.singleRollout : MarioState.bellyRollout;
        SetMarioState(stateOfMario);
        float mps = SmsUnits.SpeedToMps(fwd);
        velocity.X = dir.X * mps;
        velocity.Z = dir.Z * mps;
        velocity.Y = SmsUnits.SpeedToMps(vy);
        lastFacingDirection = dir;
        SmsLatchFace(dir, 2);
        _smsTrueVyValid = false;
        _smsFallCancel = SmsAir.FallCancelEligible(kind);
        _smsNoLandFrames = 3; // floor snapping still reports the ground for a frame or two after the launch
        initalJumpHold = true;
        jumpHoldTime = 0f;
        jumpBuffer = 0;
        if (SmsDebugPrint)
            GD.Print($"[SMS slide] A at fwd {SmsUnits.MpsToSpeed(speed):F1} ({speed:F1} m/s, threshold {SmsRollJumpMinSpeed:F0}) -> {kind}: "
                + (broad ? "singleRollout / ma_roll_jump, fwd 55 vy 38" : $"bellyRollout / ma_roll, fwd kept {fwd:F1} vy 30"));
    }

    /// <summary>considerRotateJumpStart(): on the ground, A becomes a spin jump if the stick was just spun.</summary>
    private bool SmsOrBufferedSpin() => UseSmsPhysics ? _smsSpin.Check(out _smsSpinSign) : spinBuffer > 0;

    /// <summary>
    /// considerJumpRotate(): only a single, double, U-turn, wall or trample jump can turn into a spin jump in the
    /// air (jumpingCommonEvents is not called from the triple, back, dive, roll or hip-drop handlers).
    /// </summary>
    private bool SmsAirSpinDetected()
    {
        bool eligible = stateOfMario == MarioState.singleJump || stateOfMario == MarioState.doubleJump
            || stateOfMario == MarioState.sideFlip || stateOfMario == MarioState.wallJump
            || stateOfMario == MarioState.stomping;
        return eligible && _smsSpin.Check(out _smsSpinSign);
    }

    /// <summary>
    /// JUMP_SHORT_BACK_DOWN entry (jumpDownCommon): knocked back at 16 units/tick along <paramref name="backDir"/> with the
    /// given vertical speed, facing the way he came; TickBonk lands him into SHORT_BACK_DOWN (ma_sdown) where the slide
    /// decays 0.96 per tick and the get-up cannot be interrupted.
    /// </summary>
    private void SmsEnterBonk(Vector3 backDir, float vyMps, string why, float fwdAtHit)
    {
        StopWaistIKHard();
        isSpining(false);
        stateOfMario = MarioState.bonk;
        _bonkAirborne = true;
        _bonkTimer = 0f;
        backDir.Y = 0f;
        backDir = backDir.LengthSquared() > 1e-6f ? backDir.Normalized() : -SmsFacingOrVelocityDir();
        _bonkAwayDirection = backDir;
        float back = SmsUnits.SpeedToMps(SmsParams.Timing.BonkBackSpeed);
        velocity.X = backDir.X * back;
        velocity.Z = backDir.Z * back;
        velocity.Y = vyMps;
        _smsTrueVyValid = false;
        Vector3 faceWall = -backDir;
        lastFacingDirection = faceWall;
        armature.Rotation = new Vector3(0f, YawFromDir(faceWall), 0f);
        SetMarioState(stateOfMario); // -> ma_bkdwn
        SpawnBonkStars(ComputeFeetPosition(), backDir); // PARTICLE_MS_DMG_C at mPosition (MarioJump.cpp 164 / 464), aimed along the knock-back
        if (SmsDebugPrint)
            GD.Print($"[SMS bonk] {why} at fwd {fwdAtHit:F1} (threshold {SmsParams.Mario.ClashSpeed:F0}) -> knocked back 16/tick, vy {SmsUnits.MpsToSpeed(vyMps):F1}");
    }

    /// <summary>
    /// running() case 2: hitting a wall on the ground faster than ClashSpeed (40) knocks him down with no hop. The run cap is
    /// 32, so this only happens with borrowed speed (roll-jump run-out at 55, slopes, dashes).
    /// </summary>
    private void SmsGroundWallBonk(Vector3 preMoveVel, MarioState preMoveState)
    {
        if (!IsOnFloor() || !IsOnWall() || stateOfMario == MarioState.bonk)
            return;
        bool runState = preMoveState == MarioState.running || preMoveState == MarioState.sprinting
            || preMoveState == MarioState.walking || preMoveState == MarioState.rolloutRun;
        if (!runState)
            return;
        Vector3 n = GetWallNormal();
        n.Y = 0f;
        if (n.LengthSquared() < 1e-6f)
            return;
        n = n.Normalized();
        Vector3 v = new Vector3(preMoveVel.X, 0f, preMoveVel.Z);
        float sp = v.Length();
        if (sp < 1e-4f || (v / sp).Dot(-n) < 0.5f) // must run into it, not brush along it
            return;
        float fwd = SmsUnits.MpsToSpeed(sp);
        if (fwd <= SmsParams.Mario.ClashSpeed)
            return;
        SmsEnterBonk(-(v / sp), 0f, "ground wall hit", fwd);
    }

    private static bool SmsStepUpAllowed(MarioState s) =>
        s == MarioState.walking || s == MarioState.running || s == MarioState.sprinting || s == MarioState.sneak
        || s == MarioState.rolloutRun || s == MarioState.idle || s == MarioState.pivot || s == MarioState.carrying
        || s == MarioState.wallPush || s == MarioState.wallShuffle || s == MarioState.landing
        || s == MarioState.singleJumpLanding || s == MarioState.doubleJumpLanding || s == MarioState.tripleJumpLanding
        || s == MarioState.bellySlidingFromDive; // the slide uses the same ground check: it climbs stairs

    /// <summary>
    /// checkGroundAtJumping(target, param) bit 1: the statuses whose wall hit is ignored (or turned into a ledge grab) when
    /// the wall does not reach feet + 150 units. Passed by jumping() [JUMP and FALL], secJumping(), landing(), uTurnJumping(),
    /// jumpWall(), trample(), broadJumping(), rotateBroadJumping(). Not by the triple, backflip, spin jump, dive, catchStop
    /// or hip drop, which treat every wall as a wall.
    /// </summary>
    private static bool SmsWallLedgeBit(MarioState s) =>
        s == MarioState.singleJump || s == MarioState.doubleJump || s == MarioState.ledgeFall
        || s == MarioState.sideFlip || s == MarioState.wallJump || s == MarioState.stomping
        || s == MarioState.singleRollout;

    /// <summary>
    /// Does the wall he is touching continue up to <paramref name="heightAboveFeet"/> metres? A ray from the body centre at
    /// that height toward the wall (into -normal), 6 cm past the body radius. The game's checkWallPlane(pos, 150, r).
    /// </summary>
    private bool SmsWallReachesHeight(Vector3 wallNormalXZ, float heightAboveFeet)
    {
        Vector3 dir = -wallNormalXZ;
        dir.Y = 0f;
        if (dir.LengthSquared() < 1e-6f)
            return true;
        dir = dir.Normalized();
        Vector3 from = new Vector3(GlobalPosition.X, SmsFeetY() + heightAboveFeet, GlobalPosition.Z);
        var q = PhysicsRayQueryParameters3D.Create(from, from + dir * (capRadiusWorld + 0.06f), CollisionMask);
        q.CollideWithAreas = false;
        q.Exclude = new Godot.Collections.Array<Rid> { GetRid() };
        return GetWorld3D().DirectSpaceState.IntersectRay(q).Count > 0;
    }

    /// <summary>World Y of the bottom of the collision shape (the feet). ComputeFeetPosition() is the capsule-style value used by the FX.</summary>
    private float SmsFeetY() => (bodyCol != null ? bodyCol.GlobalPosition.Y : GlobalPosition.Y) - capHalfHeightWorld;

    /// <summary>
    /// checkGroundAtWalking() / checkGroundAtJumping(): the ground under the next position is looked up from feet + 30
    /// units, so a floor up to 30 units (0.40 m) above the feet is simply stepped onto; wall planes are only tested at
    /// feet + 30 and + 60 (+ 150 in the air), so a lower riser is not a wall to the game at all -- on the ground, in the
    /// air, and on the frame a jump or dive lands on a tread while touching the next riser. Godot's cylinder is stopped by
    /// any riser, so when MoveAndSlide reported a wall, ask the two questions the game asks, with two rays anchored on the
    /// contact it reported: (1) is the wall still there just above the step limit (feet + 30)? then it is a wall, keep the
    /// wall handling. (2) where is the ground just past the riser face, read from feet + 30? 0.01..0.40 m up on a floor-
    /// angled face of level geometry: a step, move onto it; level with the feet: the "wall" was a trimesh edge or a lip,
    /// dismiss it. Either way the wall never existed for the game: keep the clipped speed and set _smsSteppedUp so the
    /// dive bonk / wall-push / ground-bonk / wall-slide checks skip this frame. Runs after MoveAndSlide.
    /// </summary>
    private void SmsTryStepUp(Vector3 preMoveVel, Vector3 preMovePos, double delta, MarioState preMoveState)
    {
        if (!IsOnWall())
            return;
        bool onFloorNow = IsOnFloor();
        bool fromGround = _smsGroundMoved;                  // on the floor at frame start (ground step, slope-scaled)
        bool landingFrame = onFloorNow && !fromGround;      // airborne at frame start, on a floor now: tread + riser in one move
        if (fromGround)
        {
            if (!SmsStepUpAllowed(preMoveState))
                return;
        }
        else
        {
            // Airborne or landing this frame: launched air states only, not from ledgeFall (its landing needs its own
            // fall-speed proof). Launch frames are NOT excluded: _smsNoLandFrames guards FLOOR contact with the ground he
            // just left, and a wall contact is a wall contact. A dive or roll from the foot of a staircase meets the
            // first riser within a frame, and the game lands it on the step (logForLarry.txt: re-dive from the slide,
            // `dive at fwd 48.1` one frame after the launch).
            if (!SmsStateSteers(preMoveState) || preMoveState == MarioState.ledgeHopUp)
                return;
            // DEVIATION (Jaysonn, pass 31: "running into a wall then jumping ... if you can jump higher then the ledge mario will just snap
            // to the ledge ... instead of doing the full jump"): jumpProcess -> checkGroundAtJumping(next) has no mVel.y test -- once the
            // next position's feet are within 30 units below a ledge top the wall plane at feet + 30 is gone, the ground check from
            // pos.y + 30 finds the top and mPosition.y is SET to it: the game lands a RISING jump on the ledge the moment his feet reach
            // it (SMS's early ledge landing). He wants the arc: while a jump rises the riser stays a wall, he clears it by his own height
            // and lands on the way down. The dives, rollouts and the stomp keep the game's rule (a dive onto a stair's first riser).
            if (!SmsParams.Jump.LedgeLandWhileRising && preMoveVel.Y > 0f && SmsIsJumpState(preMoveState))
            {
                if (SmsDebugPrint)
                    GD.Print($"[SMS step] air {preMoveState}: rising (vy {SmsUnits.MpsToSpeed(preMoveVel.Y):F1}) -- the riser stays a wall until he clears it (LedgeLandWhileRising off)");
                return;
            }
        }
        Vector3 want = new Vector3(preMoveVel.X, 0f, preMoveVel.Z) * (float)delta * (fromGround ? _smsGroundStepScale : 1f); // what MoveAndSlide was asked to do
        if (want.LengthSquared() < 1e-8f)
            return;
        Vector3 did = GlobalPosition - preMovePos;
        did.Y = 0f;
        Vector3 remaining = want - did;
        if (remaining.LengthSquared() < 1e-6f)
            return; // the wall did not take anything off the step
        Vector3 moveDir = want.Normalized();

        // The wall he actually walked into: the steepest contact facing the motion (a floor or ceiling contact is not it).
        bool found = false;
        float bestDot = 0.3f;
        Vector3 wallN = Vector3.Zero, contact = Vector3.Zero;
        for (int i = 0; i < GetSlideCollisionCount(); i++)
        {
            KinematicCollision3D c = GetSlideCollision(i);
            Vector3 cn = c.GetNormal();
            if (cn.AngleTo(Vector3.Up) <= FloorMaxAngle)
                continue;
            Vector3 cnXZ = new Vector3(cn.X, 0f, cn.Z);
            if (cnXZ.LengthSquared() < 1e-6f)
                continue;
            cnXZ = cnXZ.Normalized();
            float dot = moveDir.Dot(-cnXZ);
            if (dot < bestDot)
                continue;
            bestDot = dot;
            wallN = cnXZ;
            contact = c.GetPosition();
            found = true;
        }
        if (!found)
            return; // brushing along it, not walking into it

        Vector3 dir = -wallN; // into the wall, horizontal
        float feetY = SmsFeetY();
        float stepMax = SmsGroundContact.StepUpMetres;
        float probeY = feetY + stepMax + 0.05f; // just above the step limit: the game's feet + 30
        string where = fromGround ? "ground" : (landingFrame ? "landing frame" : "air");
        var space = GetWorld3D().DirectSpaceState;
        var exclude = new Godot.Collections.Array<Rid> { GetRid() };

        // (1) Is the wall still there above the step limit? Ray from the body centre toward the contact, 6 cm past the face.
        Vector3 toContactXZ = new Vector3(contact.X - GlobalPosition.X, 0f, contact.Z - GlobalPosition.Z);
        Vector3 wallFrom = new Vector3(GlobalPosition.X, probeY, GlobalPosition.Z);
        var qWall = PhysicsRayQueryParameters3D.Create(wallFrom, wallFrom + dir * (toContactXZ.Length() + 0.06f), CollisionMask);
        qWall.CollideWithAreas = false;
        qWall.Exclude = exclude;
        var hWall = space.IntersectRay(qWall);
        if (hWall.Count > 0)
        {
            if (SmsDebugPrint)
            {
                GodotObject wallHit = hWall["collider"].As<GodotObject>();
                GD.Print($"[SMS step] {where} {preMoveState}: wall stays a wall (solid at feet + {SmsUnits.MetresToUnits(stepMax + 0.05f):F0} units: {wallHit?.GetType().Name} '{(wallHit as Node)?.Name}')");
            }
            return;
        }

        // (2) Where is the ground just past the riser face, read from the step limit down?
        Vector3 groundFrom = new Vector3(contact.X, probeY, contact.Z) + dir * 0.03f;
        var qGround = PhysicsRayQueryParameters3D.Create(groundFrom, groundFrom + Vector3.Down * (stepMax + 0.05f + 0.5f), CollisionMask);
        qGround.CollideWithAreas = false;
        qGround.Exclude = exclude;
        var hGround = space.IntersectRay(qGround);
        if (hGround.Count == 0)
        {
            if (SmsDebugPrint)
                GD.Print($"[SMS step] {where} {preMoveState}: no ground within 0.5 m below the feet past the wall, wall stays a wall");
            return;
        }
        Vector3 groundP = (Vector3)hGround["position"];
        Vector3 groundN = (Vector3)hGround["normal"];
        GodotObject hit = hGround["collider"].As<GodotObject>();
        float rise = groundP.Y - feetY;
        bool levelGeometry = hit is StaticBody3D || hit is AnimatableBody3D || hit is CsgShape3D;
        if (!levelGeometry || groundN.AngleTo(Vector3.Up) > FloorMaxAngle || rise > stepMax)
        {
            if (SmsDebugPrint)
                GD.Print($"[SMS step] {where} {preMoveState}: rejected, rise {rise:F3} m ({SmsUnits.MetresToUnits(rise):F0} units, limit {SmsUnits.MetresToUnits(stepMax):F0}), top normal.y {groundN.Y:F2}, onto {hit?.GetType().Name} '{(hit as Node)?.Name}' (level geometry {levelGeometry})");
            return;
        }
        if (rise <= 0.01f)
        {
            // Level or lower beyond it and nothing above the step limit: a trimesh edge, a lip under a centimetre or a
            // knee-high rail. Not a wall for the game: no knockdown, no push, no slide, speed kept.
            velocity.X = preMoveVel.X;
            velocity.Z = preMoveVel.Z;
            if (onFloorNow)
                velocity.Y = 0f;
            if (rise > 0.002f)
            {
                GlobalPosition += remaining + Vector3.Up * rise; // a real lip under a centimetre (a goop slab on a floor): onto it, the frame's motion kept (pass 64)
                ApplyFloorSnap();
            }
            _smsSteppedUp = true;
            if (SmsDebugPrint)
                GD.Print($"[SMS step] {where} {preMoveState}: not a wall (ground past it is level, rise {rise:F3} m), speed kept {new Vector2(velocity.X, velocity.Z).Length():F1} m/s{(rise > 0.002f ? ", onto the lip" : "")}");
            return;
        }
        // Treads shorter than the body radius: moving by the whole remainder puts the cylinder INTO the next riser and
        // Godot's recovery pushes him back out next frame (the jitter). Find the next riser along the tread and stop the
        // front edge at it. On such stairs he still climbs one riser per frame -- that is the geometry -- but cleanly.
        Vector3 advance = remaining;
        float treadDepth = -1f; // this riser's face to the next one, when there is one within 1.5 m (also the ramp's run)
        {
            Vector3 treadFrom = new Vector3(groundP.X, groundP.Y + 0.02f, groundP.Z) + dir * 0.005f;
            var qTread = PhysicsRayQueryParameters3D.Create(treadFrom, treadFrom + dir * 1.5f, CollisionMask);
            qTread.CollideWithAreas = false;
            qTread.Exclude = exclude;
            var hTread = space.IntersectRay(qTread);
            if (hTread.Count > 0)
            {
                treadDepth = (((Vector3)hTread["position"]) - groundFrom).Dot(dir) + 0.03f; // riser face to next riser face (groundFrom sits 3 cm past the face)
                float maxAdvance = MathF.Max(0f, treadDepth - 0.005f);                    // front edge stops 5 mm short
                float wantLen = remaining.Length();
                if (wantLen > maxAdvance)
                    advance = remaining * (maxAdvance / wantLen);
            }
        }
        SmsStepVisualPayDown(); // the travel up to this riser pays off the previous one
        GlobalPosition += advance + Vector3.Up * rise;
        ApplyFloorSnap();
        SmsStepVisualEvent(rise, treadDepth); // the rig stays a riser lower and rides the ramp up (visual only)
        SmsStepVisualPayDown();               // the advance onto the tread already pays part of it
        velocity.X = preMoveVel.X; // the riser clipped the horizontal speed; the game never saw a wall
        velocity.Z = preMoveVel.Z;
        velocity.Y = 0f;
        _smsSteppedUp = true;
        if (!fromGround)
            _smsNoLandFrames = 0; // he is standing on the step: the landing rule takes it this frame (JUMP_END / belly slide), as checkGroundAtJumping does
        if (SmsDebugPrint)
        {
            float frameMove = new Vector2(GlobalPosition.X - preMovePos.X, GlobalPosition.Z - preMovePos.Z).Length();
            string tread = treadDepth > 0f ? $"{treadDepth:F2} m" : "none within 1.5 m";
            GD.Print($"[SMS step] {where} {preMoveState}: up {rise:F2} m ({SmsUnits.MetresToUnits(rise):F0} units) onto {hit.GetType().Name} '{(hit as Node)?.Name}', remaining {remaining.Length():F3} m, moved {frameMove:F3} m this frame, tread {tread}, speed kept {new Vector2(velocity.X, velocity.Z).Length():F1} m/s (tick in {_smsDbgTickInMps:F1}), ramp {_smsStepRampSlope:F2}");
        }
    }

    /// <summary>doRunning() + walkEnd() + the skid U-turn, for one physics frame (2 sub-ticks at 60 Hz).</summary>
    private void SmsGroundTick(double delta)
    {
        int n = SmsUnits.TicksFor(delta, ref _smsTickAccum);
        Vector3 velXZ = new Vector3(velocity.X, 0f, velocity.Z);
        _smsDbgTickInMps = velXZ.Length();
        if (!_smsFaceValid || _smsFaceSource != 1 || velXZ.Length() < 0.5f)
        {
            // Arriving from the air / another system, or (nearly) standing still: face the way he is
            // moving, else the way the model looks (Mario.cs snaps lastFacingDirection to the stick).
            Vector3 f = velXZ.Length() > 0.5f ? velXZ : new Vector3(lastFacingDirection.X, 0f, lastFacingDirection.Z);
            SmsLatchFace(f, 1);
        }
        Vector3 faceDir = SmsMath.DirFromYaw(_smsFaceYaw);
        float fwd = SmsUnits.MpsToSpeed(velXZ.Dot(faceDir)); // signed forward speed along the facing
        bool stick = direction.LengthSquared() > 1e-6f && _smsIntendedMag > 0f;
        float intendedYaw = stick ? SmsMath.YawFromDir(direction.Normalized()) : _smsFaceYaw;
        bool pumpingStyle = SmsPumpingStyle(); // isUpperPumpingStyle(): no U-turn, the PumpingRotSp turn
        Vector3 floorN = IsOnFloor() ? GetFloorNormal() : Vector3.Up;
        float floorNy = floorN.Y;

        for (int i = 0; i < n; i++)
        {
            if (!stick)
            {
                SmsRun.WalkEndTick(ref fwd); // stick released: 1/tick
            }
            else if (!pumpingStyle && SmsRun.IsTurnReversal(_smsFaceYaw, intendedYaw) && fwd >= SmsParams.Run.TurnNeedSp)
            {
                // turnning(): skid down at 4/tick, then TURN_END facing the stick at fwd 8 (isRunningTurnning(): never while pumping).
                SmsRun.BrakeTick(ref fwd);
                if (fwd <= 0f)
                {
                    fwd = 8f;
                    _smsFaceYaw = intendedYaw;
                }
            }
            else
            {
                SmsRun.AccelTick(ref fwd, _smsIntendedMag, floorNy);
                // doRunning(): RunningRotSp (1500) free; PumpingRotSp 300..600 by speed while the upper body pumps or holds the pump;
                // RunningRotSpMin (1500) while FLUDD_EMITTING -- the dash turns at the free run's rate, whatever the pumping says
                float rate = _fluddDashing ? SmsRun.DashTurnRateRad() : pumpingStyle ? SmsRun.PumpingTurnRateRad(fwd) : SmsRun.TurnRateRad(fwd);
                _smsFaceYaw = SmsMath.ConvergeAngle(_smsFaceYaw, intendedYaw, rate);
            }
            // slopeProcess(): slope accel by surface type (0/0 on normal ground, so slopes do not change running speed)
            // and the RunningMax clamp. The step itself is scaled by normal.y in the EndFrame block (walkProcess()).
            fwd = SmsSlope.RunSlopeTick(fwd, floorN, SmsMath.DirFromYaw(_smsFaceYaw), _smsSurface);
            if (_smsInWater)
            {
                // isRunningInWater(): wading (water shallower than SwimDepth) brakes the run with depth, up to InWaterBrake a tick
                float depthRatio = Mathf.Clamp(SmsUnits.MetresToUnits(_smsWaterSurfaceY - SmsFeetY()) / SmsParams.Swim.SwimDepth, 0f, 1f);
                fwd *= 1f - depthRatio * (1f - SmsParams.Swim.InWaterBrake);
            }
        }
        if (_fluddDashing)
            fwd = SmsParams.Mario.DashMax; // running(): setPlayerVelocity(DashMax) at the end of every tick while FLUDD_EMITTING
        SmsFluddDashAnim(fwd);
        faceDir = SmsMath.DirFromYaw(_smsFaceYaw);
        float mps = SmsUnits.SpeedToMps(fwd);
        velocity.X = faceDir.X * mps;
        velocity.Z = faceDir.Z * mps;
        _smsLatchedFacing = lastFacingDirection;
    }

    /// <summary>
    /// Airborne frame: doJumping() air control (steering states only), jumpProcess() speed cap,
    /// fallProcess() gravity with fall cancel and terminal velocity — n sub-ticks, then hand Godot
    /// the average vertical speed so the displacement matches the game exactly.
    /// </summary>
    private void SmsAirTick(double delta, Vector3 stickDir)
    {
        int n = SmsUnits.TicksFor(delta, ref _smsTickAccum);
        float vyMps = (_smsTrueVyValid && Mathf.Abs(velocity.Y - _smsMoveVyMps) < 1e-3f) ? _smsTrueVy : velocity.Y;
        float vy = SmsUnits.MpsToSpeed(vyMps);
        // landing(): the fall timer runs while vy < 0 -- the plain fall only, the LAND_SAFE_DOWN drop has no timer
        if (stateOfMario == MarioState.ledgeFall && !_smsHangDropFall && vy < 0f)
            _smsFallTicks = Math.Min(_smsFallTicks + n, SMS_LONG_FALL_TICKS + 1);
        bool aHeld = Input.IsActionPressed("button_a") || Input.IsActionPressed("key_space");
        bool cancel = _smsFallCancel;
        SmsAir.GravityMode gmode = stateOfMario == MarioState.SpinJump ? SmsAir.GravityMode.SpinJump : SmsAir.GravityMode.Normal;
        float sumMoveVy = 0f;

        if (SmsAirSteers(stateOfMario))
        {
            Vector3 velXZ = new Vector3(velocity.X, 0f, velocity.Z);
            if (!_smsFaceValid || _smsFaceSource != 2)
            {
                // Entered the air without a launch call (walked off, lost a wall, ledge hop...): the face is
                // the way he is moving, else the way he looks, and there is no fall cancel. Launches latch
                // explicitly and it stays put.
                SmsLatchFace(velXZ.Length() > 0.5f ? velXZ : new Vector3(lastFacingDirection.X, 0f, lastFacingDirection.Z), 2);
                _smsFallCancel = false;
            }
            Vector3 faceDir = SmsMath.DirFromYaw(_smsFaceYaw);
            Vector3 sideDir = faceDir.Rotated(Vector3.Up, Mathf.Pi * 0.5f);
            float fwd = SmsUnits.MpsToSpeed(velXZ.Dot(faceDir));
            bool stick = stickDir.LengthSquared() > 1e-6f && _smsIntendedMag > 0f;
            float d = stick ? faceDir.SignedAngleTo(new Vector3(stickDir.X, 0f, stickDir.Z).Normalized(), Vector3.Up) : 0f;
            // doJumping(): while a WALL_JUMP is still rising, a stick more than 90 deg from the face is ignored (mag = 0), so
            // he cannot steer back into the wall he just kicked. This, not a cooldown, is the game's re-stick protection.
            if (stick && stateOfMario == MarioState.wallJump && vy > 0f && Mathf.Abs(d) > Mathf.Pi * 0.5f)
            {
                stick = false;
                d = 0f;
            }
            float sumSide = 0f;
            for (int i = 0; i < n; i++)
            {
                SmsAir.Tick(ref fwd, ref vy, out float side, out float mv, 0f, d, stick ? _smsIntendedMag : 0f, aHeld, cancel, gmode,
                    _smsWireAir == SmsWireAir.Jump ? SmsParams.Wire.JumpAccelControl : SmsParams.Jump.JumpAccelControl); // getJumpAccelControl() (pass 66)
                sumSide += side;
                sumMoveVy += mv;
            }
            float fwdMps = SmsUnits.SpeedToMps(fwd);
            float sideMps = SmsUnits.SpeedToMps(sumSide / n);
            velocity.X = faceDir.X * fwdMps + sideDir.X * sideMps;
            velocity.Z = faceDir.Z * fwdMps + sideDir.Z * sideMps;
        }
        else
        {
            for (int i = 0; i < n; i++)
            {
                SmsAir.GravityOnlyTick(ref vy, out float mv);
                sumMoveVy += mv;
            }
        }

        velocity.Y = SmsUnits.SpeedToMps(sumMoveVy / n);
        _smsMoveVyMps = velocity.Y;
        _smsTrueVy = SmsUnits.SpeedToMps(vy);
        _smsTrueVyValid = true;

        if (SmsDebugPrint)
        {
            if (!_smsDbgAirborne)
            {
                _smsDbgAirborne = true;
                _smsDbgStartY = GlobalPosition.Y;
                _smsDbgMaxY = GlobalPosition.Y;
                _smsDbgAir = 0f;
                _smsDbgKind = stateOfMario;
            }
            _smsDbgMaxY = Mathf.Max(_smsDbgMaxY, GlobalPosition.Y);
            _smsDbgAir += (float)delta;
        }
    }

    /// <summary>catching()/doSliding(): belly-slide friction per sub-tick, with the stick's small influence.</summary>
    private void SmsBellySlideTick(double delta)
    {
        int n = SmsUnits.TicksFor(delta, ref _smsTickAccum);
        Vector3 velXZ = new Vector3(velocity.X, 0f, velocity.Z);
        float speed = velXZ.Length();
        if (speed < 1e-4f)
            return;
        Vector3 slideDir = velXZ / speed;
        float fwd = SmsUnits.MpsToSpeed(speed);
        float cs = (direction.LengthSquared() > 1e-6f && _smsIntendedMag > 0f) ? slideDir.Dot(direction.Normalized()) : 0f;
        // slideProcess(): the slope term is added along the downhill direction before the friction multiply. Normal ground:
        // nothing when sliding downhill (friction only, no gravity assist), 1.5 * sin(slope) per tick against him when
        // sliding uphill, so he loses it and gets up near the top.
        Vector3 slideFloorN = IsOnFloor() ? GetFloorNormal() : Vector3.Up;
        float slopeDv = SmsSlope.SlideSlopeDeltaFwd(slideFloorN, slideDir, _smsSurface);
        SmsSlope.Params slipP = SmsSlope.For(_smsSurface);
        bool neverStops = SmsSlope.NeverStops(_smsSurface);
        for (int i = 0; i < n; i++)
        {
            fwd += slopeDv;
            if (SmsSlide.Tick(ref fwd, _smsIntendedMag, cs, slipP, neverStops))
                break;
        }
        float mps = SmsUnits.SpeedToMps(fwd);
        velocity.X = slideDir.X * mps;
        velocity.Z = slideDir.Z * mps;
    }

    /// <summary>After MoveAndSlide: keep the post-gravity vertical speed unless the world changed it.</summary>
    private void SmsAfterMove()
    {
        SmsUpdateSurface();
        SmsCheckGraffito(); // checkGraffito(): after the status exec and the move, every tick
        if (_smsShockSparks != null && _smsShockSparks.Active && !(stateOfMario == MarioState.hurt && _smsDownKind == SmsDownKind.Electric))
            _smsShockSparks.Active = false; // whatever ended the shock (a respawn): no elecEffect() call this tick, the emitters go
        if (_smsBodyOverlay != null && _smsBodyOverlay.Negative && !(stateOfMario == MarioState.hurt && _smsDownKind == SmsDownKind.Electric))
            _smsBodyOverlay.Negative = false; // drawSpecial() reads the status each frame: no ELECTRIC_DAMAGE, no logic pass
        // addDamageFog() (MarioDraw.cpp 2184): the fog while mInvincibilityFrames > 0, OR while DIRTY on SLIP paint -- yellow-green (0x82, 0x96, 0x00)
        // while mStandingOnGraffitoTimer > 240, the damage pink (0xFF, 0x00, 0x80) below it (the HP tick comes at 360); never while talking
        bool smsSlipDirty = _smsDirty && _smsPollution == SmsPollution.Slip;
        _smsBodyOverlay?.SetFogColor(smsSlipDirty && _smsFogTimer > SmsParams.Dirty.FogTimeYellow ? SmsBodyOverlay.GoopYellow : SmsBodyOverlay.DamagePink);
        _smsBodyOverlay?.SetDamageFog((_smsInvincibleTicks > 0 || smsSlipDirty) && stateOfMario != MarioState.talking);
        // addDirty() (MarioDraw.cpp 2139, every frame from MarioMain.cpp 136): mDirty into every body / hand material's konst alpha -- the goop
        // skin (pass 111). The goop texture: the STAGE's (H_ma_rak_dummy is swapped at load for the stage's one h_ma_rak.bti -- never per goop),
        // unless SmsSkinFromLayer (pass 113) hands him the layer's texture by pass 108's rule
        _smsBodyOverlay?.SetDirty(_smsDirtyAmount, SmsSkinFromLayer && _smsGoopFx != null && _smsGoopFx.GoopLayer != null && _smsGoopFx.GoopLayer.CharacterGoop(out var skinTex, out _, out _) ? skinTex : null);
        SmsMissTick(); // TMarDirector: MARIO_FLAG_GAME_OVER -> the Miss state
        SmsRoofHangCheck(); // jumpProcess() roofCode 4: a fence roof met by the head while rising, hands empty -> HANG_ROOF
        if (_smsNoLandFrames > 0)
            _smsNoLandFrames--;
        if (SmsDebugPrint && _smsDbgAirborne && IsOnFloor())
        {
            float h = _smsDbgMaxY - _smsDbgStartY;
            float landXzMps = new Vector2(velocity.X, velocity.Z).Length();
            GD.Print($"[SMS jump] {_smsDbgKind}: apex {h:F2} m = {SmsUnits.MetresToUnits(h):F0} units = {h / 2.15f:F2} Mario heights, airtime {_smsDbgAir:F2} s, touchdown xz {SmsUnits.MpsToSpeed(landXzMps):F1} ({landXzMps:F1} m/s)");
            _smsDbgAirborne = false;
        }
        if (IsOnFloor() || IsOnCeiling())
        {
            _smsTrueVyValid = false;
            return;
        }
        if (_smsTrueVyValid && Mathf.Abs(velocity.Y - _smsMoveVyMps) < 1e-3f)
            velocity.Y = _smsTrueVy;
        else
            _smsTrueVyValid = false;
    }

    // ======================================================================================================================================
    //  Pass 116: the shine get as the game plays it (MarioReceiveMsg.cpp 236, MarioAutodemo.cpp winDemo, MarDirectorDirect.cpp 839, the bcks)
    // ======================================================================================================================================
    /// <summary>The game's shine-get demo: Mario faces the shine's placed yaw with full HP and air (a carried object dropped, enemies within 2000 u
    /// killed), the camera plays camera_demo_shine_get_outside.bck at his position, the shine flies its shine_demo_shine_get.bck in his frame, the
    /// SHINE! letters come in at 3 s, a 1 s fade to (210, 210, 210) starts at 5.333 s (TShineFader) when the shine's ExitLevel is on, the demo
    /// ends with its camera at 6.98 s (118). false = the hand-authored cutscene (the rig, the rail,
    /// the Wonderful! popup, the clip's end hands control back).</summary>
    [Export] public bool SmsShineGetGame = true;
    /// <summary>camera_demo_shine_get_inside.bck instead of _outside (TShine::mIsInside: the stage's indoor shines).</summary>
    [Export] public bool SmsShineGetInside = false;
    /// <summary>The bck camera rolls: TCameraBck::updateDemo hands C_MTXLookAt the cam_position joint's Y axis as the up vector -- level through
    /// the catch, a -25 deg dutch angle on the pose shot (from 4 s). false = always level (116's camera).</summary>
    [Export] public bool SmsShineGetRoll = true;
    /// <summary>TShineFader's colour (MarDirectorSetup2.cpp 76: setColor(0xD2, 0xD2, 0xD2)): the game's shine fade is to a near-white, not black
    /// (116 had it black). It runs only for a shine whose ExitLevel is on (118).</summary>
    [Export] public Color SmsShineGetFadeColor = new Color(0xD2 / 255f, 0xD2 / 255f, 0xD2 / 255f);
    /// <summary>registFadeout(1 s x rate, 5.3333 s x rate): when the fade starts and how long it takes (seconds since the demo began).</summary>
    /// <summary>124: fireGetStar's DIRECTOR_FLAG_CARD_SAVE_PENDING -- the demo over, the card save (SmsCardSave, PURPOSE_SHINE_GET) before the
    /// stage moves: "Save and Continue" / "Save and Quit" / "Continue". Off = the stage moves at once, nothing written (the pass 118 way).</summary>
    [Export] public bool SmsShineGetSavePrompt = true;
    [Export] public float SmsShineGetFadeAt = 5.3333f;
    [Export] public float SmsShineGetFadeLen = 1.0f;
    /// <summary>When the demo is over, seconds since it began: an ExitLevel shine changes the scene here, otherwise play resumes here. 0 = the camera
    /// bck's end (camera_demo_shine_get_*.bck: 419 frames = 6.98 s, where the game's inner demo ends and moveStage runs; Mario's ma_demo_shine_get
    /// ends there too).</summary>
    [Export] public float SmsShineGetEndAt = 0f;
    /// <summary>118: fired as an ExitLevel shine's demo ends, right before the scene changes (the destination; "" = this level reloads).</summary>
    [Signal] public delegate void SmsShineGetExitEventHandler(string scene);
    /// <summary>The SHINE! letters through the console (TConsoleStr::startAppearShineGet); false = your Wonderful! popup.</summary>
    [Export] public bool SmsShineGetLetters = true;
    /// <summary>MSD_BGM_CHUBOSS, the shine-get fanfare (the pending step starts it) -- a player to fire; no stream yet (the sound front).</summary>
    [Export] public AudioStreamPlayer ShineGetFanfare;
    private float _smsShineDemoT = -1f;              // seconds since the demo began (-1 = no demo)
    private Transform3D _smsShineDemoFrame;          // origin = his position, +Z = the facing, +X = its left (SMS is right-handed, +Z forward)
    private Camera3D _smsShineCam;
    private CanvasLayer _smsShineFadeLayer; private ColorRect _smsShineFadeRect;
    public bool SmsShineDemoRunning => _smsShineDemoT >= 0f;
    public float SmsShineDemoT => _smsShineDemoT;
    public float SmsShineFadeAlpha => _smsShineFadeRect != null && _smsShineFadeRect.Visible ? _smsShineFadeRect.Color.A : 0f;
    public Color SmsShineFadeColorNow => _smsShineFadeRect != null ? _smsShineFadeRect.Color : new Color(0f, 0f, 0f, 0f);
    /// <summary>Seconds since the demo began at which it ends (SmsShineGetEndAt, or the camera bck's last frame).</summary>
    public float SmsShineGetEndTime => SmsShineGetEndAt > 0f ? SmsShineGetEndAt : (SmsShineGetInside ? SmsShineGetData.CamFramesInside : SmsShineGetData.CamFramesOutside) / SmsShineGetData.Fps;
    public Camera3D SmsShineCamera => _smsShineCam;
    public Transform3D SmsShineDemoFrame => _smsShineDemoFrame;

    /// <summary>TMario::receiveMessage(ACTOR_TYPE_SHINE) + winDemo state 0 -> 1 + TMarDirector::fireGetStar + the pending step, at the landing.</summary>
    private void SmsShineGetBegin(ShineSprite shine)
    {
        // winDemo: the held object is dropped (HIT_MESSAGE_UNKD), the enemies within 2000 u are killed
        if (heldBody != null) Anim_DetachPickup();
        pendingPickup = null;
        SmsShineGetKillEnemies(SmsUnits.UnitsToMetres(2000f));
        // mFaceAngle.y = the shine's INITIAL rotation.y; velocity 0; HP and air full
        float yaw = shine.SmsInitialYaw;
        Vector3 face = SmsMath.DirFromYaw(yaw);
        SmsLatchFace(face, 1);
        if (armature != null) armature.Rotation = new Vector3(0f, yaw, 0f);
        lastFacingDirection = face;
        velocity = Vector3.Zero; Velocity = Vector3.Zero;
        _health = StartingHealth;
        _smsAir = _smsMaxAir;
        // the demo frame: fireStartDemoCamera at his position with the shine's yaw; TShine::receiveMessage puts the shine at his position / angle
        _smsShineDemoFrame = new Transform3D(new Basis(Vector3.Up.Cross(face), Vector3.Up, face), GlobalPosition);
        _smsShineDemoT = 0f;
        _activeShine = shine;
        shine.BeginCollectSequence(this, yaw, true);
        // the camera: TCameraBck on camera_model.bmd -- the eye, the look-at and the fovy from the bck
        if (_smsShineCam == null || !IsInstanceValid(_smsShineCam))
        {
            _smsShineCam = new Camera3D { Name = "SmsShineGetCam" };
            (GetTree().CurrentScene ?? GetTree().Root).AddChild(_smsShineCam);
        }
        SmsShineDemoCamera(0f);
        _smsShineCam.MakeCurrent();
        // the pending step: the letters, the fanfare, the fade registered; the count-up as before
        if (SmsShineGetLetters && _smsConsoleStr != null) _smsConsoleStr.StartAppearShineGet(shine.ShineText); else SpawnShineGetPopup();   // 118b: the shine's own word, if any
        ShineGetFanfare?.Play();
        SmsShineFadeAlpha_(0f);
        ScheduleShineCountUp();
        if (SmsDebugPrint)
            GD.Print($"[SMS shine] demo: face {Mathf.RadToDeg(yaw):F0} deg (the shine's placed yaw), HP {_health}, air {_smsAir:F1}, camera {( SmsShineGetInside ? "inside" : "outside")}, {(shine.ExitLevel ? $"fade at {SmsShineGetFadeAt:F2} s for {SmsShineGetFadeLen:F1} s then the exit" : "no exit (the shine's ExitLevel is off)")}, ends at {SmsShineGetEndTime:F2} s");
    }

    /// <summary>gpConductor->killEnemiesWithin(mPosition, 2000): every enemy in the sms_enemy group within the radius dies (its death look).</summary>
    private int SmsShineGetKillEnemies(float radiusM)
    {
        int n = 0;
        foreach (Node node in GetTree().GetNodesInGroup("sms_enemy"))
        {
            if (node is Gooble g && IsInstanceValid(g) && g.GlobalPosition.DistanceTo(GlobalPosition) <= radiusM) { g.SmsKillByDemo(); n++; }
        }
        return n;
    }

    private void SmsShineDemoCamera(float t)
    {
        if (_smsShineCam == null) return;
        SmsShineGetData.Camera(t, SmsShineGetInside, out Vector3 eyeU, out Vector3 targetU, out Vector3 upU, out float fov);
        Vector3 eye = _smsShineDemoFrame * (eyeU / SmsUnits.UnitsPerMetre);
        Vector3 target = _smsShineDemoFrame * (targetU / SmsUnits.UnitsPerMetre);
        // 116b: the up C_MTXLookAt gets is the cam_position joint's Y axis (unkC column 1) -- the bck rolls the pose shot 25 deg
        Vector3 up = SmsShineGetRoll ? (_smsShineDemoFrame.Basis * upU).Normalized() : Vector3.Up;
        if (Mathf.Abs(up.Dot((target - eye).Normalized())) > 0.999f) up = Vector3.Up;
        _smsShineCam.GlobalPosition = eye;
        if ((target - eye).LengthSquared() > 1e-6f) _smsShineCam.LookAt(target, up);
        _smsShineCam.Fov = fov;
    }

    private void SmsShineFadeAlpha_(float a)
    {
        if (_smsShineFadeRect == null || !IsInstanceValid(_smsShineFadeRect))
        {
            _smsShineFadeLayer = new CanvasLayer { Name = "SmsShineFade", Layer = 200 };
            _smsShineFadeRect = new ColorRect { Name = "ShineFader", Color = new Color(SmsShineGetFadeColor, 0f), MouseFilter = Control.MouseFilterEnum.Ignore };
            _smsShineFadeRect.SetAnchorsPreset(Control.LayoutPreset.FullRect);
            _smsShineFadeLayer.AddChild(_smsShineFadeRect);
            (GetTree().CurrentScene ?? GetTree().Root).AddChild(_smsShineFadeLayer);
        }
        _smsShineFadeRect.Color = new Color(SmsShineGetFadeColor, Mathf.Clamp(a, 0f, 1f));
        _smsShineFadeRect.Visible = a > 0f;
    }

    /// <summary>Every physics frame: winDemo state 1 (setAnimation(DEMO_SHINE_GET) + stopProcess), the demo camera and the shine on the bck clock,
    /// TShineFader's fade (an ExitLevel shine only), and the end at the camera's last frame.</summary>
    private void SmsShineDemoTick(double delta)
    {
        float dt = (float)delta;
        if (_smsShineDemoT >= 0f && stateOfMario == MarioState.shineGet)
        {
            velocity = Vector3.Zero; Velocity = Vector3.Zero;   // stopProcess
            _smsShineDemoT += dt;
            float t = _smsShineDemoT;
            SmsShineDemoCamera(t);
            bool exit = _activeShine != null && IsInstanceValid(_activeShine) && _activeShine.ExitLevel;
            if (_activeShine != null && IsInstanceValid(_activeShine)) _activeShine.SmsDemoDrive(_smsShineDemoFrame, t);
            float a = !exit ? 0f : SmsShineGetFadeLen > 0f ? (t - SmsShineGetFadeAt) / SmsShineGetFadeLen : (t >= SmsShineGetFadeAt ? 1f : 0f);
            SmsShineFadeAlpha_(a);
            if (t >= SmsShineGetEndTime) SmsShineGetEnd();
        }
        else if (_smsShineDemoT >= 0f)
        {
            _smsShineDemoT = -1f;   // the state was left some other way (a reload, his debug keys): nothing to drive
            SmsShineFadeAlpha_(0f);
        }
    }

    /// <summary>The demo's end (the camera bck's last frame, 6.98 s). An ExitLevel shine: the game's moveStage -- the scene changes behind the
    /// white (its ExitScene, else the pause menu's Exit Area scene, else this level again, as the Plaza reloads itself). Otherwise (DEVIATION, the
    /// shine's option) the gameplay camera and control come back where he stands, no fade.</summary>
    private void SmsShineGetEnd()
    {
        _smsShineDemoT = -1f;
        ShineSprite shine = _activeShine != null && IsInstanceValid(_activeShine) ? _activeShine : null;
        _activeShine = null;
        // 124: DIRECTOR_FLAG_CARD_SAVE_PENDING (MarDirectorDirect.cpp 854 / 866): the demo over, STATE_CARD_SAVE with PURPOSE_SHINE_GET before the
        // stage moves -- the dialog over the faded screen (or over the live level for a shine that stays, his option), the game stopped under it
        SmsCardSave card = SmsShineGetSavePrompt ? SmsCardSave.Current : null;
        if (card != null && !card.IsOpen)
        {
            if (SmsDebugPrint) GD.Print($"[SMS shine] demo over at {SmsShineGetEndTime:F2} s: the card save (PURPOSE_SHINE_GET), the game stopped");
            void OnDone(int next) { card.Finished -= OnDone; SmsShineGetFinish(shine, next); }
            card.Finished += OnDone;
            card.Open(SmsCardSave.Purpose.ShineGet, pauseTree: true, screenFaded: shine != null && shine.ExitLevel);
            return;
        }
        SmsShineGetFinish(shine, 0);
    }

    /// <summary>After the card save (or at once without it): getNextState 1 = "Save and Quit" -> the title (STATE_UNK12 / APP_STATE_DONE); 0 = the
    /// stage moves (an ExitLevel shine) or control comes back (his option).</summary>
    private void SmsShineGetFinish(ShineSprite shine, int next)
    {
        if (shine != null && !IsInstanceValid(shine)) shine = null;
        if (next == 1)
        {
            string title = SmsCardSave.Current?.TitleScene ?? "";
            if (GameData.Instance != null) { GameData.Instance.ReturnFromScene = null; GameData.Instance.ReturnWithShine = false; }
            if (SmsDebugPrint) GD.Print($"[SMS shine] Save and Quit -> {(title != "" ? title : "the main scene")}");
            if (title != "") GetTree().ChangeSceneToFile(title); else GetTree().ChangeSceneToFile(ProjectSettings.GetSetting("application/run/main_scene").AsString());
            return;
        }
        if (shine != null && shine.ExitLevel)
        {
            string dest = SmsReturnSpot.ScenePath(shine.ExitScene);   // 119b: the editor saves the File export as uid://, resolved to the path
            if (dest == "") dest = SmsReturnSpot.ScenePath(SmsFluddModel.FindChild<SmsPauseMenu>(this)?.ExitAreaScene);
            if (SmsDebugPrint) GD.Print($"[SMS shine] demo over at {SmsShineGetEndTime:F2} s behind the white: moveStage -> {(dest != "" ? dest : "this level again (the Plaza's decideNextStage)")}");
            EmitSignal(SignalName.SmsShineGetExit, dest);
            if (GameData.Instance != null)
            {
                // 119: MSF_GOT_SHINE_IN_PREV_STAGE + the previous area: the next level (this one again included) starts him at its return spot for
                // this one, with the shine pose; no spot for it = the plain start, as the Plaza's own reload
                GameData.Instance.ReturnFromScene = GetTree().CurrentScene?.SceneFilePath;
                GameData.Instance.ReturnWithShine = true;
            }
            if (dest != "") GetTree().ChangeSceneToFile(dest); else GetTree().ReloadCurrentScene();
            return;
        }
        shine?.OnCollectSequenceEnd();
        SmsShineFadeAlpha_(0f);
        CameraLocked = false;
        stateOfMario = MarioState.idle;
        animPlayer.Play("ma_wait");
        SetMarioState(stateOfMario);
        camera?.MakeCurrent();
        if (SmsDebugPrint) GD.Print($"[SMS shine] demo over at {SmsShineGetEndTime:F2} s: control returned (the shine's ExitLevel is off)");
    }

    // ======================================================================================================================================
    //  Pass 119: the return from a stage -- TMario::returnStart + warpOut (MarioAutodemo.cpp 318 / 368), TMarDirector::setMario (534)
    // ======================================================================================================================================
    /// <summary>warpOut state 1: from the appear to the rolling fall, 0xB4 = 180 of Mario's status ticks -- the director's 120 Hz movement ticks, so
    /// 1.5 s: the appear clip's own 89 frames at 60 (he spins in and straight into the roll). 120b: it was 3.0 s here (60 Hz assumed) and he hung.</summary>
    [Export] public float SmsGateOutHoldSeconds = 1.5f;
    /// <summary>120: warpOutEffect kind 0 -- ms_m_gout_gate, the paint-water stream out of the M gate (SmsGateStream: the jpa run on the CPU). The
    /// game's kinds 1 (the pipe, ms_m_gout_dokan) and 2 (the body-part sparkles) are not ported.</summary>
    [Export] public bool SmsGateOutStream = true;
    private int _smsGateOutPhase;                 // 0 none, 1 the appear (held at the gate), 2 the rolling fall, 3 landed (the gate-out clip / the pose)
    private float _smsGateOutT;
    private bool _smsGateOutShine, _smsGateOutPending;
    private string _smsGateOutFrom;
    public bool SmsGateOutRunning => _smsGateOutPhase > 0;
    public int SmsGateOutPhase => _smsGateOutPhase;

    /// <summary>At _Ready: GameData says he left a stage -- the return spot is looked for on the first physics tick (every node is in the tree by
    /// then, spawners included) and the flags are cleared there (the level's own _Ready, which runs after this, still reads them to skip its
    /// intro; TMarDirector::setMario clears MSF_GOT_SHINE_IN_PREV_STAGE the same way, once used).</summary>
    private void SmsGateOutCapture()
    {
        if (GameData.Instance == null || string.IsNullOrEmpty(GameData.Instance.ReturnFromScene)) return;
        _smsGateOutFrom = GameData.Instance.ReturnFromScene;
        _smsGateOutShine = GameData.Instance.ReturnWithShine;
        _smsGateOutPending = true;
    }

    /// <summary>returnStart(pos, rot, gotShine, type): startCommon warps him to the spot facing its forward (a shine) or the opposite way, then
    /// WARP_OUT: ANIM_DEMO_GATE_OUT_APPEAR(_GET) held, the rolling clip falling under gravity, on the floor ANIM_DEMO_GATE_OUT (_GET2: the shine
    /// pose) to its last frame, then WAIT. The gate particle (PARTICLE_MS_M_GOUT_GATE) is SmsGateStream (120).</summary>
    public void SmsGateOutStart(SmsReturnSpot spot, bool withShine)
    {
        if (spot == null) return;
        Vector3 fwd = -spot.GlobalBasis.Z; fwd.Y = 0f;
        if (fwd.LengthSquared() < 1e-6f) fwd = Vector3.Forward;
        Vector3 face = (withShine ? fwd : -fwd).Normalized();   // rotation (a shine) / rotation + 180
        GlobalPosition = spot.GlobalPosition;
        velocity = Vector3.Zero; Velocity = Vector3.Zero;
        float yaw = SmsMath.YawFromDir(face);
        SmsLatchFace(face, 1);
        if (armature != null) armature.Rotation = new Vector3(0f, yaw, 0f);
        lastFacingDirection = face;
        if (heldBody != null) Anim_DetachPickup();
        pendingPickup = null;
        CameraLocked = true;
        stateOfMario = MarioState.shineGet;   // the demo state: input and the state machine off, the tree off for the direct clips
        SetMarioState(stateOfMario);
        SmsCameraWarpBehind();
        _smsGateOutShine = withShine; _smsGateOutPhase = 1; _smsGateOutT = 0f;
        SmsGateOutClip(withShine ? "ma_demo_gate_out_appear_get" : "ma_demo_gate_out_appear");
        // warpOutEffect(kind, (arg & 0xff) * 180 + face): the stream's frame is the spot's forward with or without the shine
        if (SmsGateOutStream) SmsGateStream.Spawn(GetTree().CurrentScene ?? GetTree().Root, GlobalPosition, fwd);
        if (SmsDebugPrint) GD.Print($"[SMS return] gate out at {spot.Name} {GlobalPosition} facing {Mathf.RadToDeg(yaw):F0} deg, {(withShine ? "with the shine (the pose)" : "no shine")}, held {SmsGateOutHoldSeconds:F1} s then the fall");
    }

    /// <summary>121: the body mesh's cap surface -- the dome at the top of the head in Mario.glb (its material's name); hidden while the cap is in his hand.
    /// Another character's mesh names it differently (or has a separate cap node): set it, or leave the cap on.</summary>
    [Export] public string SmsCapSurfaceMaterial = "_mat_head(7)";
    private bool _smsCapInHand;
    private int _smsCapSurface = -2;   // -2 = not looked up, -1 = none
    private Material _smsCapPrevOverride, _smsCapHidden;
    public bool SmsCapInHandNow => _smsCapInHand;
    /// <summary>122: the game's capless head top (ma_cap3.bmd, TMarioCap's hair dome) shown at the M_head bone while the cap is off; the body mesh has no top under the cap.</summary>
    [Export] public bool SmsCaplessHeadDome = true;
    /// <summary>122: the body mesh's head surface (its material's name) -- the hair dome borrows its material (the game gives ma_cap3 the body's texture).</summary>
    [Export] public string SmsHeadSurfaceMaterial = "_mat_head(8)";
    private MeshInstance3D _smsHairDome;
    private bool _smsHandCap;   // 122: hnd4r -- the right hand holds the cap while the frame < 158 (one frame past the head's 157)
    public bool SmsHandCapNow => _smsHandCap;

    private void SmsHandCap(bool on)
    {
        if (_smsHandCap == on) return;
        _smsHandCap = on;
        if (SmsDebugPrint) GD.Print($"[SMS cap] right hand {(on ? "holds the cap (RightHandWithHat)" : "open again")}");
    }

    /// <summary>122: the hair dome -- built once from SmsCaplessHead under a BoneAttachment3D on M_head (the game's attach joint), the head surface's material.</summary>
    private void SmsHairDome(bool on)
    {
        if (!SmsCaplessHeadDome) return;
        if (_smsHairDome == null)
        {
            if (!on || marioMesh?.Mesh == null) return;
            var skel = marioMesh.GetParentOrNull<Skeleton3D>();
            if (skel == null) { if (SmsDebugPrint) GD.Print("[SMS cap] the body mesh is not under a Skeleton3D: no hair dome"); return; }
            string bone = skel.FindBone("M_head") >= 0 ? "M_head" : skel.FindBone("jnt_head") >= 0 ? "jnt_head" : null;
            if (bone == null) { if (SmsDebugPrint) GD.Print("[SMS cap] no M_head / jnt_head bone: no hair dome"); return; }
            Material mat = null;
            for (int i = 0; i < marioMesh.Mesh.GetSurfaceCount() && mat == null; i++)
                if (marioMesh.Mesh.SurfaceGetMaterial(i)?.ResourceName == SmsHeadSurfaceMaterial) mat = marioMesh.GetActiveMaterial(i);
            if (mat == null && _smsCapSurface >= 0) mat = marioMesh.GetActiveMaterial(_smsCapSurface);
            if (mat == null && SmsDebugPrint) GD.Print($"[SMS cap] no surface '{SmsHeadSurfaceMaterial}' on the body mesh: the hair dome goes unlit white");
            var att = new BoneAttachment3D { Name = "SmsCaplessHeadBone", BoneName = bone };
            skel.AddChild(att);
            _smsHairDome = new MeshInstance3D { Name = "SmsCaplessHead", Mesh = SmsCaplessHead.Build(mat), CastShadow = marioMesh.CastShadow, Layers = marioMesh.Layers };
            att.AddChild(_smsHairDome);
            if (SmsDebugPrint) GD.Print($"[SMS cap] hair dome built: ma_cap3's {SmsCaplessHead.TriangleCount} tris on {bone}, material {(mat?.ResourceName ?? "none")}");
        }
        _smsHairDome.Visible = on;
    }

    /// <summary>TMarioCap: ma_cap1 (the head) off and ma_cap3 (the hand) on, or back. The hand pose follows through SmsHandPose (WithHat).</summary>
    private void SmsCapInHand(bool on)
    {
        if (_smsCapInHand == on) return;
        _smsCapInHand = on;
        if (marioMesh?.Mesh == null) return;
        if (_smsCapSurface == -2)
        {
            _smsCapSurface = -1;
            for (int i = 0; i < marioMesh.Mesh.GetSurfaceCount(); i++)
                if (marioMesh.Mesh.SurfaceGetMaterial(i)?.ResourceName == SmsCapSurfaceMaterial) { _smsCapSurface = i; break; }
            if (_smsCapSurface < 0 && SmsDebugPrint) GD.Print($"[SMS cap] no surface '{SmsCapSurfaceMaterial}' on the body mesh: the cap stays on through the pose");
        }
        if (_smsCapSurface < 0) return;
        if (on)
        {
            _smsCapHidden ??= new StandardMaterial3D { ResourceName = "sms cap off (transparent)", Transparency = BaseMaterial3D.TransparencyEnum.Alpha, AlbedoColor = new Color(0f, 0f, 0f, 0f), ShadingMode = BaseMaterial3D.ShadingModeEnum.Unshaded };
            _smsCapPrevOverride = marioMesh.GetSurfaceOverrideMaterial(_smsCapSurface);
            marioMesh.SetSurfaceOverrideMaterial(_smsCapSurface, _smsCapHidden);
        }
        else
            marioMesh.SetSurfaceOverrideMaterial(_smsCapSurface, _smsCapPrevOverride);
        SmsHairDome(on);   // 122: TMarioCap: ma_cap3 (the hair dome) shown while ma_cap1 (the cap) is hidden
        if (SmsDebugPrint) GD.Print($"[SMS cap] {(on ? "off the head (the hair dome on)" : "back on the head")}");
    }

    private void SmsGateOutClip(string clip)
    {
        if (animPlayer == null) return;
        if (animTree != null) animTree.Active = false;
        animPlayer.SpeedScale = 1f;
        if (animPlayer.HasAnimation(clip)) animPlayer.Play(clip);
        else GD.PushWarning($"[SMS return] Player.tscn has no clip '{clip}' (the game's ma_demo_gate_out set)");
    }

    private bool SmsGateOutClipDone() => animPlayer == null || !animPlayer.IsPlaying() || animPlayer.CurrentAnimationPosition >= animPlayer.CurrentAnimationLength - 1f / 60f;

    /// <summary>Every physics frame, before the lock block: the first tick's start (the spot looked up), then warpOut's states.</summary>
    private void SmsGateOutTick(double delta)
    {
        if (_smsGateOutPending)
        {
            _smsGateOutPending = false;
            if (GameData.Instance != null) { GameData.Instance.ReturnFromScene = null; GameData.Instance.ReturnWithShine = false; }
            // a level reloading itself (the Plaza's own shine) takes only a spot made for it: the game's Plaza reload is the plain start
            bool sameLevel = SmsReturnSpot.ScenePath(_smsGateOutFrom) == (GetTree().CurrentScene?.SceneFilePath ?? "");
            var spot = SmsReturnSpot.Find(GetTree(), _smsGateOutFrom, allowAny: !sameLevel);
            if (spot != null) SmsGateOutStart(spot, _smsGateOutShine);
            else if (SmsDebugPrint) GD.Print($"[SMS return] back from {_smsGateOutFrom} but this level has no SmsReturnSpot for it: the plain start");
            return;
        }
        if (_smsGateOutPhase == 0) return;
        if (stateOfMario != MarioState.shineGet) { _smsGateOutPhase = 0; SmsCapInHand(false); SmsHandCap(false); return; }   // left some other way (a reload, his debug keys)
        float dt = (float)delta;
        _smsGateOutT += dt;
        switch (_smsGateOutPhase)
        {
            case 1:
                velocity = Vector3.Zero; Velocity = Vector3.Zero;
                if (_smsGateOutT >= SmsGateOutHoldSeconds)
                {
                    _smsGateOutPhase = 2;
                    SmsGateOutClip(_smsGateOutShine ? "ma_demo_gate_out_rolling_get" : "ma_demo_gate_out_rolling");   // jumpProcess(0): the lock block's gravity
                }
                break;
            case 2:
                if (IsOnFloor())
                {
                    _smsGateOutPhase = 3;
                    SmsGateOutClip(_smsGateOutShine ? "ma_demo_gate_out_get2" : "ma_demo_gate_out");
                }
                break;
            case 3:
                // 121/122: TMarioCap::perform / TMario::calcAnim on ANIM_DEMO_GATE_OUT_GET2: the cap off the head (the hair dome on) while the
                // frame < 157, the right hand holding it (hnd4r) while the frame < 158, both back after
                {
                    float gateFrame = _smsGateOutShine && animPlayer != null && animPlayer.IsPlaying() ? (float)animPlayer.CurrentAnimationPosition * 60f : 1e9f;
                    SmsCapInHand(gateFrame < 157f);
                    SmsHandCap(gateFrame < 158f);
                }
                if (SmsGateOutClipDone())
                {
                    _smsGateOutPhase = 0;
                    SmsCapInHand(false);
                    SmsHandCap(false);
                    CameraLocked = false;
                    stateOfMario = MarioState.idle;
                    animPlayer?.Play("ma_wait");
                    SetMarioState(stateOfMario);
                    if (SmsDebugPrint) GD.Print($"[SMS return] gate out over at {_smsGateOutT:F2} s: WAIT, control returned");
                }
                break;
        }
    }

}
